CREATE OR REPLACE FUNCTION "public"."_caller_may_look_up"("_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  -- Always true or false, never NULL: a NULL here would make has_role()
  -- NULL, and `IF NOT has_role(...)` checks would then let callers through.
  SELECT COALESCE(_user_id = auth.uid(), false)
      OR COALESCE(auth.jwt() ->> 'role', '') NOT IN ('anon', 'authenticated')
      OR EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'admin');
$$;


ALTER FUNCTION "public"."_caller_may_look_up"("_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_can_manage_event"("_user_id" "uuid", "_event_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT _user_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.events e
     WHERE e.id = _event_id
       AND (
         e.user_id = _user_id
         OR public.has_role(_user_id, 'admin')
         OR (e.org_id IS NOT NULL AND (public.is_org_owner(_user_id, e.org_id)
                                       OR public.is_org_member(_user_id, e.org_id)))
       )
  );
$$;


