CREATE OR REPLACE FUNCTION "public"."_company_initials"("_key" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  SELECT string_agg(left(w, 1), '' ORDER BY i)
    FROM unnest(string_to_array(_key, ' ')) WITH ORDINALITY AS t(w, i)
   WHERE w NOT IN ('and','of','the','for');
$$;


ALTER FUNCTION "public"."_company_initials"("_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_company_name_usable"("_key" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $$
  SELECT _key IS NOT NULL
     AND length(_key) >= 2
     AND _key ~ '[a-z0-9]|[^\x00-\x7F]'
     AND _key NOT IN ('na','n a','none','nil','null','self','self employed','selfemployed','freelance','freelancer',
                      'student','students','unemployed','not applicable','not employed','test','testing','xyz','abc',
                      'private','individual','personal','home','homemaker','housewife','retired','nothing','no',
                      'yes','other','others','nan','undefined','tbd','unknown','company','my company');
$$;


ALTER FUNCTION "public"."_company_name_usable"("_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_company_public_logo"("_company" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(es.logo_url, s.logo_url)
    FROM sponsors s
    JOIN event_sponsors es ON es.sponsor_id = s.id
    JOIN events e ON e.id = es.event_id
   WHERE s.company_id = _company AND e.status = 'published' AND COALESCE(es.logo_url, s.logo_url) IS NOT NULL
   ORDER BY e.date DESC NULLS LAST, s.id
   LIMIT 1;
$$;


ALTER FUNCTION "public"."_company_public_logo"("_company" "uuid") OWNER TO "postgres";


