  SELECT COALESCE(c.website, (SELECT 'https://' || d.domain FROM company_domains d WHERE d.company_id = c.id ORDER BY d.domain LIMIT 1))
    FROM companies c WHERE c.id = _company;
$$;


ALTER FUNCTION "public"."_company_website"("_company" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_copy_community_members_from_previous"("_new_community_id" "uuid", "_previous_event_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _prev_community_id uuid;
  _copied int := 0;
BEGIN
  IF _previous_event_id IS NULL THEN RETURN 0; END IF;

  SELECT id INTO _prev_community_id
    FROM communities
   WHERE event_id = _previous_event_id
   LIMIT 1;
  IF _prev_community_id IS NULL THEN RETURN 0; END IF;

  WITH ins AS (
    INSERT INTO community_members (community_id, user_id, role, status, auto, notify_push)
    SELECT _new_community_id, cm.user_id, cm.role, 'active', true, false
      FROM community_members cm
     WHERE cm.community_id = _prev_community_id
       AND cm.status = 'active'
    ON CONFLICT (community_id, user_id) DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO _copied FROM ins;

  RETURN _copied;
END;
$$;


ALTER FUNCTION "public"."_copy_community_members_from_previous"("_new_community_id" "uuid", "_previous_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_cposts_count_trg"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE public.communities SET post_count = post_count + 1, updated_at = now() WHERE id = NEW.community_id;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE public.communities SET post_count = greatest(0, post_count - 1), updated_at = now() WHERE id = OLD.community_id;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."_cposts_count_trg"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_creactions_count_trg"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.post_id IS NOT NULL THEN
      UPDATE public.community_posts SET reaction_count = reaction_count + 1 WHERE id = NEW.post_id;
    ELSE
      UPDATE public.community_comments SET reaction_count = reaction_count + 1 WHERE id = NEW.comment_id;
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.post_id IS NOT NULL THEN
      UPDATE public.community_posts SET reaction_count = greatest(0, reaction_count - 1) WHERE id = OLD.post_id;
    ELSE
      UPDATE public.community_comments SET reaction_count = greatest(0, reaction_count - 1) WHERE id = OLD.comment_id;
    END IF;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."_creactions_count_trg"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_ensure_company_for_name"("_name" "text", "_source" "text" DEFAULT 'typed'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _key text := public.company_name_key(_name);
  _id  uuid;
BEGIN
  IF NOT public._company_name_usable(_key) THEN RETURN NULL; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('company_name:' || _key, 0));
  SELECT c.id INTO _id
    FROM companies c
   WHERE c.verification_status <> 'rejected' AND c.merged_into IS NULL
     AND (c.name_key = _key OR EXISTS (SELECT 1 FROM company_aliases a WHERE a.company_id = c.id AND a.alias_key = _key))
   ORDER BY (c.verification_status = 'verified') DESC, c.entry_count DESC, c.created_at
   LIMIT 1;
  IF _id IS NOT NULL THEN RETURN _id; END IF;
  INSERT INTO companies (name, name_key, source)
  VALUES (public.norm_text(_name), _key, CASE WHEN _source IN ('typed','sponsor','organiser') THEN _source ELSE 'typed' END)
  RETURNING id INTO _id;
  RETURN _id;
END;
$$;


ALTER FUNCTION "public"."_ensure_company_for_name"("_name" "text", "_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_ensure_company_for_sponsor"("_name" "text", "_website" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _domain text := public.norm_website_domain(_website);
  _id     uuid;
BEGIN
  IF _domain IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('company_domain:' || _domain, 0));
    SELECT company_id INTO _id FROM company_domains WHERE domain = _domain;
    IF _id IS NOT NULL THEN RETURN _id; END IF;
  END IF;
  _id := public._ensure_company_for_name(_name, 'sponsor');
  IF _id IS NULL THEN RETURN NULL; END IF;
  -- An organiser named it, so a record first made from typed entries counts as theirs.
  UPDATE companies SET source = 'sponsor' WHERE id = _id AND source = 'typed'
     AND NOT EXISTS (SELECT 1 FROM companies o WHERE o.source = 'sponsor' AND o.name_key = companies.name_key AND o.id <> companies.id);
  IF _domain IS NOT NULL THEN
    INSERT INTO company_domains (company_id, domain, kind) VALUES (_id, _domain, 'website') ON CONFLICT (domain) DO NOTHING;
    UPDATE companies SET website = COALESCE(website, 'https://' || _domain) WHERE id = _id;
  END IF;
  RETURN _id;
END;
$$;


ALTER FUNCTION "public"."_ensure_company_for_sponsor"("_name" "text", "_website" "text") OWNER TO "postgres";


