    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  SELECT CASE WHEN _v IS NULL OR length(_v) < 2 THEN NULL
              WHEN _v = upper(_v) OR _v = lower(_v) THEN initcap(_v)
         END;
$$;


