CREATE OR REPLACE FUNCTION "public"."_meeting_person_check"("_eid" "uuid", "_registration_id" "uuid", "_speaker_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF num_nonnulls(_registration_id, _speaker_id) <> 1 THEN
    RAISE EXCEPTION 'Choose one attendee or one speaker.' USING ERRCODE = '22023';
  END IF;
  IF _registration_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM registrations r
     WHERE r.id = _registration_id AND r.event_id = _eid
       AND r.approval_status = 'approved' AND r.ticket_type <> 'speaker'
  ) THEN
    RAISE EXCEPTION 'That attendee is not available.' USING ERRCODE = '42501';
  END IF;
  IF _speaker_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM event_speakers esp WHERE esp.event_id = _eid AND esp.speaker_id = _speaker_id
  ) THEN
    RAISE EXCEPTION 'That speaker is not available.' USING ERRCODE = '42501';
  END IF;
END;
$$;


ALTER FUNCTION "public"."_meeting_person_check"("_eid" "uuid", "_registration_id" "uuid", "_speaker_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_my_event_sponsors"("_eid" "uuid") RETURNS TABLE("sponsor_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT es.sponsor_id
    FROM event_sponsors es
    JOIN sponsor_members sm ON sm.sponsor_id = es.sponsor_id
   WHERE es.event_id = _eid AND sm.user_id = auth.uid() AND sm.accepted_at IS NOT NULL
  UNION
  SELECT es.sponsor_id
    FROM event_sponsors es
    JOIN sponsors s ON s.id = es.sponsor_id
    JOIN events e   ON e.id = es.event_id
    LEFT JOIN organizations o ON o.id = e.org_id
   WHERE es.event_id = _eid AND s.user_id = auth.uid()
     AND e.user_id IS DISTINCT FROM auth.uid()
     AND o.owner_id IS DISTINCT FROM auth.uid()
     AND NOT EXISTS (SELECT 1 FROM org_members m WHERE m.org_id = e.org_id AND m.user_id = auth.uid());
$$;


ALTER FUNCTION "public"."_my_event_sponsors"("_eid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_note_company_mention"("_person" "uuid", "_name" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _id  uuid := public._ensure_company_for_name(_name, 'typed');
  _new integer;
BEGIN
  IF _id IS NULL OR _person IS NULL THEN RETURN _id; END IF;
  INSERT INTO company_mentions (company_id, person_id) VALUES (_id, _person) ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS _new = ROW_COUNT;
  IF _new > 0 THEN
    UPDATE companies SET entry_count = entry_count + 1 WHERE id = _id;
  END IF;
  RETURN _id;
END;
$$;


ALTER FUNCTION "public"."_note_company_mention"("_person" "uuid", "_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_org_entitlements"("_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _plan     text := 'free';
  _addons   text[] := '{}';
  _over     jsonb := '{}'::jsonb;
  _p        public.plans%ROWTYPE;
  _features text[];
BEGIN
  SELECT o.plan, COALESCE(o.addons, '{}'), COALESCE(o.feature_overrides, '{}'::jsonb)
    INTO _plan, _addons, _over
  FROM public.organizations o WHERE o.id = _org_id;
  -- No such organisation leaves the targets NULL.
  _plan := COALESCE(_plan, 'free');
  _addons := COALESCE(_addons, '{}');
  _over := COALESCE(_over, '{}'::jsonb);

  SELECT * INTO _p FROM public.plans WHERE key = _plan;
  IF NOT FOUND THEN
    SELECT * INTO _p FROM public.plans WHERE key = 'free';
  END IF;

  SELECT COALESCE(array_agg(DISTINCT f ORDER BY f), '{}') INTO _features
  FROM (
    SELECT unnest(COALESCE(_p.features, '{}')) AS f
    UNION SELECT unnest(_addons)
    UNION SELECT e.key FROM jsonb_each(_over) e WHERE e.value = 'true'::jsonb
  ) granted
  WHERE f NOT IN (SELECT e.key FROM jsonb_each(_over) e WHERE e.value = 'false'::jsonb);

  RETURN jsonb_build_object(
    'org_id',    _org_id,
    'plan',      _plan,
    'plan_name', COALESCE(_p.name, initcap(_plan)),
    'limits',    COALESCE(_p.limits, '{}'::jsonb),
    'features',  to_jsonb(_features),
    'overrides', _over
  );
END; $$;


ALTER FUNCTION "public"."_org_entitlements"("_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_organises_sponsor_event"("_sponsor_id" "uuid", "_uid" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM event_sponsors es
      JOIN events e ON e.id = es.event_id
      LEFT JOIN organizations o ON o.id = e.org_id
     WHERE es.sponsor_id = _sponsor_id
       AND (e.user_id = _uid
            OR o.owner_id = _uid
            OR EXISTS (SELECT 1 FROM org_members m WHERE m.org_id = e.org_id AND m.user_id = _uid))
  );
$$;


ALTER FUNCTION "public"."_organises_sponsor_event"("_sponsor_id" "uuid", "_uid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_person_visible_to"("_uid" "uuid", "_person" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT _uid IS NOT NULL AND (
       EXISTS (SELECT 1 FROM people p WHERE p.id = _person AND p.user_id = _uid)
    OR has_role(_uid, 'admin')
    OR EXISTS (SELECT 1 FROM registrations r JOIN events e ON e.id = r.event_id
                WHERE r.person_id = _person
                  AND (e.user_id = _uid OR (e.org_id IS NOT NULL AND is_org_member(_uid, e.org_id))))
    OR EXISTS (SELECT 1 FROM speakers s JOIN event_speakers es ON es.speaker_id = s.id JOIN events e ON e.id = es.event_id
                WHERE s.person_id = _person
                  AND (e.user_id = _uid OR (e.org_id IS NOT NULL AND is_org_member(_uid, e.org_id))))
    OR EXISTS (SELECT 1 FROM sponsor_members m JOIN event_sponsors es ON es.sponsor_id = m.sponsor_id JOIN events e ON e.id = es.event_id
                WHERE m.person_id = _person
                  AND (e.user_id = _uid OR (e.org_id IS NOT NULL AND is_org_member(_uid, e.org_id))))
  );
$$;


ALTER FUNCTION "public"."_person_visible_to"("_uid" "uuid", "_person" "uuid") OWNER TO "postgres";


