    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.user_id IS NOT NULL AND NEW.approval_status = 'approved' THEN
    PERFORM _auto_join_event_community(NEW.event_id, NEW.user_id, 'member');
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."_registrations_join_community"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_registrations_tickets_sold_trg"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM public._recompute_tickets_sold(OLD.event_id);
    RETURN OLD;
  ELSIF TG_OP = 'UPDATE' AND OLD.event_id IS DISTINCT FROM NEW.event_id THEN
    -- Registration moved between events; recount both.
    PERFORM public._recompute_tickets_sold(OLD.event_id);
    PERFORM public._recompute_tickets_sold(NEW.event_id);
    RETURN NEW;
  ELSE
    PERFORM public._recompute_tickets_sold(NEW.event_id);
    RETURN NEW;
  END IF;
END;
$$;


ALTER FUNCTION "public"."_registrations_tickets_sold_trg"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_require_share_access"("_event" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF public._sponsorship_access(_event) IS DISTINCT FROM 'commercial' THEN
    RAISE EXCEPTION 'Only the event owner or an organisation admin can share participant data' USING ERRCODE = '42501';
  END IF;
  RETURN auth.uid();
END;
$$;


