CREATE OR REPLACE FUNCTION "public"."_sponsor_company"("_sponsor" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE s sponsors%ROWTYPE;
BEGIN
  SELECT * INTO s FROM sponsors WHERE id = _sponsor;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF s.company_id IS NOT NULL THEN RETURN public._canonical_company(s.company_id); END IF;
  s.company_id := public._ensure_company_for_sponsor(s.name, s.website);
  IF s.company_id IS NOT NULL THEN UPDATE sponsors SET company_id = s.company_id WHERE id = _sponsor; END IF;
  RETURN s.company_id;
END;
$$;


ALTER FUNCTION "public"."_sponsor_company"("_sponsor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_sponsor_scope"("_sponsor" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _owner uuid;
  _orgs  text[];
BEGIN
  SELECT user_id INTO _owner FROM sponsors WHERE id = _sponsor;
  SELECT ARRAY_AGG(DISTINCT COALESCE(e.org_id::text, 'user:' || e.user_id::text)) INTO _orgs
    FROM event_sponsors es JOIN events e ON e.id = es.event_id WHERE es.sponsor_id = _sponsor;
  IF _orgs IS NULL THEN
    SELECT ARRAY_AGG(DISTINCT x.org) INTO _orgs FROM (
      SELECT o.id::text AS org FROM organizations o WHERE o.owner_id = _owner
      UNION SELECT m.org_id::text FROM org_members m WHERE m.user_id = _owner) x;
  END IF;
  IF array_length(_orgs, 1) = 1 THEN RETURN _orgs[1]; END IF;
  RETURN 'user:' || COALESCE(_owner::text, _sponsor::text);
END;
$$;


ALTER FUNCTION "public"."_sponsor_scope"("_sponsor" "uuid") OWNER TO "postgres";


