CREATE TABLE IF NOT EXISTS "public"."utm_partner_access" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "event_id" "uuid" NOT NULL,
    "utm_source" "text" NOT NULL,
    "utm_medium" "text" DEFAULT '(none)'::"text" NOT NULL,
    "utm_campaign" "text" DEFAULT '(none)'::"text" NOT NULL,
    "invited_email" "text" NOT NULL,
    "partner_user_id" "uuid",
    "can_register" boolean DEFAULT false NOT NULL,
    "can_view_approval" boolean DEFAULT true NOT NULL,
    "can_view_checkin" boolean DEFAULT true NOT NULL,
    "can_export" boolean DEFAULT false NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "granted_by" "uuid",
    "granted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "accepted_at" timestamp with time zone,
    "revoked_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "utm_partner_access_invited_email_check" CHECK ((("invited_email" = "lower"("btrim"("invited_email"))) AND (POSITION(('@'::"text") IN ("invited_email")) > 1))),
    CONSTRAINT "utm_partner_access_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'accepted'::"text", 'revoked'::"text"]))),
    CONSTRAINT "utm_partner_access_utm_source_check" CHECK ((("btrim"("utm_source") <> ''::"text") AND ("utm_source" <> '(direct)'::"text")))
);


ALTER TABLE "public"."utm_partner_access" OWNER TO "postgres";


COMMENT ON TABLE "public"."utm_partner_access" IS 'An organiser''s share of one tracked link (event + utm_source/medium/campaign) with an external partner. No direct client access — use the utm_partner_* (organiser) and partner_utm_* (partner) functions.';



CREATE OR REPLACE FUNCTION "public"."_utm_partner_grant"("_access_id" "uuid") RETURNS "public"."utm_partner_access"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  g public.utm_partner_access;
BEGIN
  IF auth.uid() IS NOT NULL AND _access_id IS NOT NULL THEN
    SELECT a.* INTO g
      FROM public.utm_partner_access a
     WHERE a.id = _access_id
       AND a.partner_user_id = auth.uid()
       AND a.status = 'accepted';
  END IF;
  IF g.id IS NULL OR public.is_user_banned(auth.uid()) THEN
    RAISE EXCEPTION 'You don''t have access to this shared link' USING ERRCODE = '42501';
  END IF;
  RETURN g;
END;
$$;


ALTER FUNCTION "public"."_utm_partner_grant"("_access_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_utm_partner_manages_event"("_event_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT auth.uid() IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.events e
    WHERE e.id = _event_id
      AND (
        e.user_id = auth.uid()
        OR public.has_role(auth.uid(), 'admin')
        OR public.is_org_member(auth.uid(), e.org_id)
      )
  );
$$;


ALTER FUNCTION "public"."_utm_partner_manages_event"("_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_utm_partner_notify"("_user_id" "uuid", "_type" "text", "_title" "text", "_body" "text", "_link" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF _user_id IS NULL THEN RETURN; END IF;
  INSERT INTO public.app_notifications(user_id, type, title, body, link)
  VALUES (_user_id, _type, _title, _body, _link);
EXCEPTION WHEN OTHERS THEN
  NULL;
END;
$$;


ALTER FUNCTION "public"."_utm_partner_notify"("_user_id" "uuid", "_type" "text", "_title" "text", "_body" "text", "_link" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_utm_partner_row"("a" "public"."utm_partner_access") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'id', a.id, 'event_id', a.event_id,
    'utm_source', a.utm_source, 'utm_medium', a.utm_medium, 'utm_campaign', a.utm_campaign,
    'invited_email', a.invited_email,
    'partner_name', (SELECT p.display_name FROM public.profiles p WHERE p.user_id = a.partner_user_id),
    'can_register', a.can_register, 'can_view_approval', a.can_view_approval,
    'can_view_checkin', a.can_view_checkin, 'can_export', a.can_export,
    'status', a.status, 'granted_at', a.granted_at, 'accepted_at', a.accepted_at, 'revoked_at', a.revoked_at,
    'stats', public._utm_partner_stats(a.event_id, a.utm_source, a.utm_medium, a.utm_campaign),
    'registered_by_partner', (
      SELECT count(*) FROM public.registrations r
       WHERE a.partner_user_id IS NOT NULL
         AND r.created_by = a.partner_user_id
         AND r.event_id   = a.event_id
         AND r.status    <> 'cancelled'
         AND r.utm_source = a.utm_source
         AND coalesce(r.utm_medium,   '(none)') = a.utm_medium
         AND coalesce(r.utm_campaign, '(none)') = a.utm_campaign
    )
  );
$$;


ALTER FUNCTION "public"."_utm_partner_row"("a" "public"."utm_partner_access") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_utm_partner_stats"("_event_id" "uuid", "_source" "text", "_medium" "text", "_campaign" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'total',          count(*),
    'approved',       count(*) FILTER (WHERE r.approval_status = 'approved'),
    'pending',        count(*) FILTER (WHERE r.approval_status = 'pending'),
    'declined',       count(*) FILTER (WHERE r.approval_status = 'declined'),
    'waitlisted',     count(*) FILTER (WHERE r.approval_status = 'waitlisted'),
    'checked_in',     count(*) FILTER (WHERE r.checked_in),
    'not_checked_in', count(*) FILTER (WHERE NOT r.checked_in AND r.approval_status = 'approved')
  )
  FROM public.registrations r
  WHERE r.event_id   = _event_id
    AND r.status    <> 'cancelled'
    AND r.utm_source = _source
    AND coalesce(r.utm_medium,   '(none)') = _medium
    AND coalesce(r.utm_campaign, '(none)') = _campaign;
$$;


ALTER FUNCTION "public"."_utm_partner_stats"("_event_id" "uuid", "_source" "text", "_medium" "text", "_campaign" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_validate_person_title"() RETURNS "trigger"
    LANGUAGE "plpgsql"
