BEGIN IF NEW.title IS NOT NULL AND NEW.title NOT IN('Mr','Ms','Mrs','Prefer not to say') THEN RAISE EXCEPTION 'Invalid title: %', NEW.title; END IF; RETURN NEW; END;
$$;


ALTER FUNCTION "public"."_validate_person_title"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_whatsapp_recipient_update"("_recipient_id" "uuid", "_status" "text", "_error" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF _status NOT IN ('pending','sending','sent','delivered','read','failed') THEN
    RAISE EXCEPTION 'Invalid whatsapp status: %', _status;
  END IF;

  UPDATE communication_recipients
     SET whatsapp_status      = _status,
         whatsapp_sent_at     = CASE WHEN _status = 'sent'      AND whatsapp_sent_at      IS NULL THEN now() ELSE whatsapp_sent_at      END,
         whatsapp_delivered_at = CASE WHEN _status = 'delivered' AND whatsapp_delivered_at IS NULL THEN now() ELSE whatsapp_delivered_at END,
         whatsapp_read_at     = CASE WHEN _status = 'read'      AND whatsapp_read_at      IS NULL THEN now() ELSE whatsapp_read_at      END,
         error_message        = COALESCE(_error, error_message)
   WHERE id = _recipient_id;
END;
$$;


ALTER FUNCTION "public"."_whatsapp_recipient_update"("_recipient_id" "uuid", "_status" "text", "_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_org_invitation"("_token" "uuid") RETURNS TABLE("accepted_org_id" "uuid", "assigned_role" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  invitation    record;
  caller_email  text;
  _current_role text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Must be signed in to accept an invitation';
  END IF;

  SELECT lower(u.email) INTO caller_email
    FROM auth.users u
   WHERE u.id = auth.uid() AND u.email_confirmed_at IS NOT NULL;
  IF caller_email IS NULL THEN
    RAISE EXCEPTION 'Verify your email address before accepting an invitation';
  END IF;

  SELECT i.id, i.org_id, i.email, i.role, i.status, i.expires_at
    INTO invitation
    FROM public.org_invitations i
   WHERE i.token = _token
   LIMIT 1
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invitation not found';
  END IF;
  IF invitation.status = 'revoked' THEN
    RAISE EXCEPTION 'This invitation was withdrawn. Ask the workspace admin to send a new one.';
  END IF;
  IF caller_email <> lower(invitation.email) THEN
    RAISE EXCEPTION 'Signed-in email does not match the invitation';
  END IF;

  SELECT m.role INTO _current_role
    FROM public.org_members m
   WHERE m.org_id = invitation.org_id AND m.user_id = auth.uid();

  IF invitation.status = 'accepted' THEN
    IF _current_role IS NULL THEN
      RAISE EXCEPTION 'This invitation has already been used. Ask the workspace admin to send a new one.';
    END IF;
    accepted_org_id := invitation.org_id;
    assigned_role   := _current_role;
    RETURN NEXT;
    RETURN;
  END IF;

  IF invitation.expires_at <= now() THEN
    RAISE EXCEPTION 'This invitation has expired. Ask the workspace admin to send a new one.';
  END IF;

  IF _current_role IS NULL THEN
    INSERT INTO public.org_members (org_id, user_id, role)
         VALUES (invitation.org_id, auth.uid(), invitation.role)
    ON CONFLICT (org_id, user_id) DO NOTHING;
    SELECT m.role INTO _current_role
      FROM public.org_members m
     WHERE m.org_id = invitation.org_id AND m.user_id = auth.uid();
  END IF;

  UPDATE public.org_invitations
     SET status      = 'accepted',
         accepted_at = now(),
         accepted_by = auth.uid(),
         claimed_at  = NULL,
         updated_at  = now()
   WHERE id = invitation.id;

  accepted_org_id := invitation.org_id;
  assigned_role   := _current_role;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."accept_org_invitation"("_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_quote"("p_quote_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_quote quotes%ROWTYPE;
  v_rfq rfqs%ROWTYPE;
  v_vendor vendors%ROWTYPE;
  v_booking_id uuid;
  v_commission bigint;
BEGIN
  -- Lock and fetch the quote
  SELECT * INTO v_quote FROM quotes WHERE id = p_quote_id FOR UPDATE;
  IF v_quote IS NULL THEN
    RAISE EXCEPTION 'Quote not found';
  END IF;
  IF v_quote.status != 'sent' THEN
    RAISE EXCEPTION 'Quote is not in sent status';
  END IF;

  -- Fetch related RFQ
  SELECT * INTO v_rfq FROM rfqs WHERE id = v_quote.rfq_id;

  -- Fetch vendor for commission rate
  SELECT * INTO v_vendor FROM vendors WHERE id = v_quote.vendor_id;

  -- Calculate commission
  v_commission := ROUND(v_quote.total * (v_vendor.commission_rate / 100));

  -- Create the booking
  INSERT INTO vendor_bookings (
    quote_id, rfq_id, org_id, vendor_id, event_id,
    total, currency, commission_amount, commission_rate,
    status, deposit_status, event_date
  ) VALUES (
    v_quote.id, v_quote.rfq_id, v_rfq.org_id, v_quote.vendor_id, v_rfq.event_id,
    v_quote.total, v_quote.currency, v_commission, v_vendor.commission_rate,
    'pending', 'pending', v_rfq.event_date
  ) RETURNING id INTO v_booking_id;

  -- Create default milestones (30/40/30 split)
  INSERT INTO booking_milestones (booking_id, label, amount, sort_order) VALUES
    (v_booking_id, 'Deposit (30%)', ROUND(v_quote.total * 0.3), 1),
    (v_booking_id, 'Midway Payment (40%)', ROUND(v_quote.total * 0.4), 2),
    (v_booking_id, 'Final Payment (30%)', v_quote.total - ROUND(v_quote.total * 0.3) - ROUND(v_quote.total * 0.4), 3);

  -- Mark event date as booked in availability (if date is set)
  IF v_rfq.event_date IS NOT NULL THEN
    INSERT INTO vendor_availability (vendor_id, date, status, booking_id)
    VALUES (v_quote.vendor_id, v_rfq.event_date, 'booked', v_booking_id)
    ON CONFLICT (vendor_id, date)
    DO UPDATE SET status = 'booked', booking_id = v_booking_id;
  END IF;

  -- Update quote status
  UPDATE quotes SET status = 'accepted', updated_at = now() WHERE id = p_quote_id;

  -- Update RFQ status
  UPDATE rfqs SET status = 'accepted' WHERE id = v_quote.rfq_id;

  RETURN v_booking_id;
END;
$$;


ALTER FUNCTION "public"."accept_quote"("p_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_quote"("p_quote_id" "uuid", "p_actor_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_quote quotes%ROWTYPE;
  v_rfq rfqs%ROWTYPE;
  v_vendor vendors%ROWTYPE;
  v_booking_id uuid;
  v_commission bigint;
  v_deposit bigint;
  v_midway bigint;
  v_final bigint;
BEGIN
  -- Lock and fetch the quote
  SELECT * INTO v_quote FROM quotes WHERE id = p_quote_id FOR UPDATE;
  IF v_quote IS NULL THEN
    RAISE EXCEPTION 'Quote not found';
  END IF;
  IF v_quote.status != 'sent' THEN
    RAISE EXCEPTION 'Quote must be in "sent" status to accept (current: %)', v_quote.status;
  END IF;

  -- Fetch related RFQ
  SELECT * INTO v_rfq FROM rfqs WHERE id = v_quote.rfq_id;
  IF v_rfq IS NULL THEN
    RAISE EXCEPTION 'RFQ not found for quote';
  END IF;

  -- Fetch vendor for commission rate
  SELECT * INTO v_vendor FROM vendors WHERE id = v_quote.vendor_id;

  -- Calculate commission
  v_commission := ROUND(v_quote.total * (v_vendor.commission_rate / 100));

  -- Calculate milestone split (30/40/30)
  v_deposit := ROUND(v_quote.total * 0.3);
  v_midway := ROUND(v_quote.total * 0.4);
  v_final := v_quote.total - v_deposit - v_midway;

  -- 1. Create the booking
  INSERT INTO vendor_bookings (
    quote_id, rfq_id, org_id, vendor_id, event_id,
    total, currency, commission_amount, commission_rate,
    status, deposit_status, event_date
  ) VALUES (
    v_quote.id, v_quote.rfq_id, v_rfq.org_id, v_quote.vendor_id, v_rfq.event_id,
    v_quote.total, v_quote.currency, v_commission, v_vendor.commission_rate,
    'pending', 'pending', v_rfq.event_date
  ) RETURNING id INTO v_booking_id;

  -- 2. Create milestones (30/40/30)
  INSERT INTO booking_milestones (booking_id, label, amount, sort_order, status)
  VALUES
    (v_booking_id, 'Deposit (30%)', v_deposit, 1, 'pending'),
    (v_booking_id, 'Midway Payment (40%)', v_midway, 2, 'pending'),
    (v_booking_id, 'Final Payment (30%)', v_final, 3, 'pending');

  -- 3. Mark event date as booked in availability (conflict check via trigger)
  IF v_rfq.event_date IS NOT NULL THEN
    INSERT INTO vendor_availability (vendor_id, date, status, booking_id, note)
    VALUES (v_quote.vendor_id, v_rfq.event_date, 'booked', v_booking_id, 'Auto-booked from quote acceptance')
    ON CONFLICT (vendor_id, date)
    DO UPDATE SET status = 'booked', booking_id = v_booking_id,
                  note = 'Auto-booked from quote acceptance';
  END IF;

  -- 4. Update quote status
  UPDATE quotes SET status = 'accepted', updated_at = now() WHERE id = p_quote_id;

  -- 5. Update RFQ status
  UPDATE rfqs SET status = 'accepted' WHERE id = v_quote.rfq_id;

  -- 6. Mark invitee as responded
  UPDATE rfq_invitees
  SET responded_at = now()
  WHERE rfq_id = v_quote.rfq_id AND vendor_id = v_quote.vendor_id;

  -- 7. Audit log entry
  INSERT INTO vendor_audit_log (actor_id, action, entity_type, entity_id, metadata)
  VALUES (
    p_actor_id, 'quote_accepted', 'vendor_bookings', v_booking_id,
    jsonb_build_object(
      'quote_id', p_quote_id,
      'rfq_id', v_quote.rfq_id,
      'total', v_quote.total,
      'commission', v_commission
    )
  );

  RETURN v_booking_id;
END;
$$;


ALTER FUNCTION "public"."accept_quote"("p_quote_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_sponsor_invite"("_token" "text") RETURNS TABLE("sponsor_id" "uuid", "sponsor_name" "text", "result" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  _m     sponsor_members%ROWTYPE;
  _uid   uuid := auth.uid();
  _email text;
  _name  text;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Sign in first.' USING ERRCODE = '42501'; END IF;
  IF _token IS NULL OR length(btrim(_token)) < 8 THEN
    RAISE EXCEPTION 'INVITE_INVALID' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO _m FROM sponsor_members sm WHERE sm.invite_token = btrim(_token) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'INVITE_INVALID' USING ERRCODE = 'P0002'; END IF;

  SELECT s.name INTO _name FROM sponsors s WHERE s.id = _m.sponsor_id;

  -- Organisers share the link; they don't join the sponsor's team.
  IF public._organises_sponsor_event(_m.sponsor_id, _uid) THEN
    RAISE EXCEPTION 'INVITE_ORGANISER' USING ERRCODE = '42501';
  END IF;

  IF _m.user_id = _uid AND _m.accepted_at IS NOT NULL THEN
    sponsor_id := _m.sponsor_id; sponsor_name := _name; result := 'already_yours';
    RETURN NEXT; RETURN;
  END IF;

  -- Taken by someone else — unless an organiser claimed it by mistake.
  IF _m.user_id IS NOT NULL AND _m.user_id <> _uid
     AND NOT public._organises_sponsor_event(_m.sponsor_id, _m.user_id) THEN
    RAISE EXCEPTION 'INVITE_CLAIMED' USING ERRCODE = '42501';
  END IF;

  UPDATE sponsor_members sm
     SET user_id = _uid, accepted_at = now()
   WHERE sm.id = _m.id;

  SELECT u.email INTO _email FROM auth.users u WHERE u.id = _uid;
  INSERT INTO audit_logs (actor_id, actor_email, action, target_type, target_id, details)
  VALUES (_uid, _email, 'sponsor_invite.accepted', 'sponsor_member', _m.id::text,
          jsonb_build_object('sponsor_id', _m.sponsor_id, 'invited_email', _m.email,
                             'replaced_organiser_claim', _m.user_id IS NOT NULL));

  sponsor_id := _m.sponsor_id; sponsor_name := _name; result := 'accepted';
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."accept_sponsor_invite"("_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_sponsor_invite_as"("_token" "text", "_user_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _m     sponsor_members%ROWTYPE;
  _email text;
BEGIN
  IF _token IS NULL OR length(btrim(_token)) < 8 OR _user_id IS NULL THEN RETURN 'invalid'; END IF;
  SELECT * INTO _m FROM sponsor_members sm WHERE sm.invite_token = btrim(_token) FOR UPDATE;
  IF NOT FOUND THEN RETURN 'invalid'; END IF;

  SELECT lower(u.email) INTO _email FROM auth.users u WHERE u.id = _user_id AND u.email_confirmed_at IS NOT NULL;
  IF _email IS NULL OR _email <> lower(btrim(_m.email)) THEN RETURN 'email_mismatch'; END IF;

  IF public._organises_sponsor_event(_m.sponsor_id, _user_id) THEN RETURN 'organiser'; END IF;
  IF _m.user_id = _user_id AND _m.accepted_at IS NOT NULL THEN RETURN 'already_yours'; END IF;
  IF _m.user_id IS NOT NULL AND _m.user_id <> _user_id
     AND NOT public._organises_sponsor_event(_m.sponsor_id, _m.user_id) THEN
    RETURN 'claimed';
  END IF;

  UPDATE sponsor_members sm SET user_id = _user_id, accepted_at = now() WHERE sm.id = _m.id;
  INSERT INTO audit_logs (actor_id, actor_email, action, target_type, target_id, details)
  VALUES (_user_id, _email, 'sponsor_invite.accepted', 'sponsor_member', _m.id::text,
          jsonb_build_object('sponsor_id', _m.sponsor_id, 'invited_email', _m.email, 'via', 'account_setup_link'));
  RETURN 'accepted';
END;
$$;


ALTER FUNCTION "public"."accept_sponsor_invite_as"("_token" "text", "_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_vendor_quote"("p_quote_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  q_row public.quotes%ROWTYPE;
  r_row public.rfqs%ROWTYPE;
  v_commission_rate numeric;
  v_commission_amount bigint;
  new_booking_id uuid;
BEGIN
  SELECT * INTO q_row FROM public.quotes WHERE id = p_quote_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Quote not found'; END IF;
  IF q_row.status <> 'sent' THEN
    RAISE EXCEPTION 'Quote is not in a state that can be accepted (status=%)', q_row.status;
  END IF;

  SELECT * INTO r_row FROM public.rfqs WHERE id = q_row.rfq_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'RFQ not found'; END IF;

  -- Authorization: caller must have access to the organizer side of this RFQ.
  IF NOT public.vendor_can_read_org(r_row.org_id) THEN
    RAISE EXCEPTION 'Not authorized to accept quotes on this RFQ';
  END IF;

  -- Copy commission from the vendor row so bookings capture the rate that
  -- was in effect at accept-time.
  SELECT commission_rate INTO v_commission_rate
    FROM public.vendors WHERE id = q_row.vendor_id;
  v_commission_rate := COALESCE(v_commission_rate, 10.00);
  v_commission_amount := ROUND(q_row.total::numeric * v_commission_rate / 100)::bigint;

  -- Winning quote
  UPDATE public.quotes
     SET status = 'accepted', updated_at = now()
   WHERE id = p_quote_id;

  -- Siblings on the same RFQ → expired
  UPDATE public.quotes
     SET status = 'expired', updated_at = now()
   WHERE rfq_id = q_row.rfq_id
     AND id <> p_quote_id
     AND status IN ('draft', 'sent');

  -- Close the RFQ
  UPDATE public.rfqs
     SET status = 'accepted'
   WHERE id = q_row.rfq_id;

  -- Create the booking
  INSERT INTO public.vendor_bookings (
    quote_id, rfq_id, org_id, vendor_id, event_id,
    total, currency, commission_rate, commission_amount,
    event_date, status
  ) VALUES (
    q_row.id, q_row.rfq_id, r_row.org_id, q_row.vendor_id, r_row.event_id,
    q_row.total, q_row.currency, v_commission_rate, v_commission_amount,
    r_row.event_date, 'pending'
  ) RETURNING id INTO new_booking_id;

  -- Seed the standard milestone checklist (30/70 default split).
  -- Values are in the same minor-unit basis as `total`.
  INSERT INTO public.booking_milestones (booking_id, label, amount, sort_order)
  VALUES
    (new_booking_id, 'Deposit',        ROUND(q_row.total::numeric * 0.30)::bigint, 1),
    (new_booking_id, 'Balance',        ROUND(q_row.total::numeric * 0.70)::bigint, 2),
    (new_booking_id, 'Event delivered',                                    0,      3);

  RETURN new_booking_id;
END;
$$;


ALTER FUNCTION "public"."accept_vendor_quote"("p_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_ban_user"("_user_id" "uuid", "_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  IF _user_id = auth.uid() THEN
    RAISE EXCEPTION 'Cannot ban yourself';
  END IF;

  UPDATE public.profiles
     SET banned_at     = now(),
         banned_reason = _reason,
         updated_at    = now()
   WHERE user_id = _user_id;

  -- Trigger on profiles will fire, but we also write an explicit user.banned
  -- entry so the activity feed surfaces the ban as its own primary verb.
  INSERT INTO public.audit_logs(actor_id, actor_email, action, target_type, target_id, details)
  VALUES (auth.uid(), public._audit_actor_email(auth.uid()), 'user.banned', 'profiles',
          _user_id::text, jsonb_build_object('reason', _reason));
END;
$$;


ALTER FUNCTION "public"."admin_ban_user"("_user_id" "uuid", "_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_delete_org"("_oid" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ BEGIN IF NOT has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Unauthorized'; END IF; DELETE FROM subscriptions WHERE org_id=_oid; DELETE FROM org_members WHERE org_id=_oid; DELETE FROM events WHERE org_id=_oid; DELETE FROM organizations WHERE id=_oid; END; $$;


ALTER FUNCTION "public"."admin_delete_org"("_oid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_delete_plan"("_key" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _n int;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'Unauthorized'; END IF;
  IF _key = 'free' THEN RAISE EXCEPTION 'The free plan cannot be deleted'; END IF;
  SELECT count(*) INTO _n FROM public.organizations WHERE plan = _key;
  IF _n > 0 THEN RAISE EXCEPTION '% organisation(s) are on this plan. Move them to another plan first.', _n; END IF;
  DELETE FROM public.plans WHERE key = _key;
  PERFORM public._plan_audit('plan.delete', 'plan', _key, '{}'::jsonb);
END; $$;


ALTER FUNCTION "public"."admin_delete_plan"("_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_delete_user"("_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_admin_count int;
  v_target_is_admin boolean;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  IF _user_id = auth.uid() THEN
    RAISE EXCEPTION 'Cannot delete yourself';
  END IF;

  SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = 'admin')
    INTO v_target_is_admin;

  IF v_target_is_admin THEN
    SELECT count(*) INTO v_admin_count FROM public.user_roles WHERE role = 'admin';
    IF v_admin_count <= 1 THEN
      RAISE EXCEPTION 'Cannot delete the last super admin';
    END IF;
  END IF;

  INSERT INTO public.audit_logs(actor_id, actor_email, action, target_type, target_id, details)
  VALUES (auth.uid(), public._audit_actor_email(auth.uid()), 'user.deleted', 'auth.users',
          _user_id::text, jsonb_build_object('was_admin', v_target_is_admin));

  DELETE FROM auth.users WHERE id = _user_id;
END;
$$;


ALTER FUNCTION "public"."admin_delete_user"("_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_event_force_delete"("_event_id" "uuid", "_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  UPDATE public.events
     SET deleted_at = now(),
         status     = 'cancelled',
         published  = false,
         updated_at = now()
   WHERE id = _event_id;

  INSERT INTO public.audit_logs(actor_id, actor_email, action, target_type, target_id, details)
  VALUES (auth.uid(), public._audit_actor_email(auth.uid()), 'event.force_deleted',
          'events', _event_id::text, jsonb_build_object('reason', _reason));
END;
$$;


