    AS $$ SELECT p.user_id,p.display_name,p.avatar_url,p.onboarding_completed,p.created_at,o.name,o.plan,EXISTS(SELECT 1 FROM user_roles ur WHERE ur.user_id=p.user_id AND ur.role='admin') FROM profiles p LEFT JOIN org_members om ON om.user_id=p.user_id LEFT JOIN organizations o ON o.id=om.org_id WHERE has_role(auth.uid(),'admin') ORDER BY p.created_at DESC; $$;


