CREATE OR REPLACE FUNCTION "public"."admin_recent_activity"("_limit" integer DEFAULT 100, "_action_filter" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "actor_id" "uuid", "actor_email" "text", "action" "text", "target_type" "text", "target_id" "text", "details" "jsonb", "created_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_total bigint;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  SELECT count(*) INTO v_total
  FROM public.audit_logs a
  WHERE (_action_filter IS NULL OR a.action ILIKE _action_filter || '%');

  RETURN QUERY
  SELECT a.id, a.actor_id, a.actor_email, a.action,
         a.target_type, a.target_id, a.details, a.created_at,
         v_total
  FROM public.audit_logs a
  WHERE (_action_filter IS NULL OR a.action ILIKE _action_filter || '%')
  ORDER BY a.created_at DESC
  LIMIT GREATEST(1, LEAST(_limit, 500));
END;
$$;


ALTER FUNCTION "public"."admin_recent_activity"("_limit" integer, "_action_filter" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_revenue_summary"() RETURNS TABLE("gross_revenue" numeric, "platform_fees" numeric, "refunds_issued" numeric, "net_revenue" numeric, "mrr" numeric, "ticket_count_paid" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_gross  numeric;
  v_refunds numeric;
  v_fees   numeric;
  v_net    numeric;
  v_mrr    numeric;
  v_count  bigint;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  SELECT
    COALESCE(SUM(amount_paid) FILTER (WHERE status IN ('confirmed','paid')), 0)::numeric,
    COALESCE(SUM(amount_paid) FILTER (WHERE status = 'refunded'), 0)::numeric,
    COALESCE(count(*) FILTER (WHERE status IN ('confirmed','paid') AND amount_paid > 0), 0)::bigint
  INTO v_gross, v_refunds, v_count
  FROM public.registrations;

  v_fees := (v_gross * 0.02)::numeric;
  v_net  := (v_gross - v_refunds - v_fees)::numeric;

  -- Simple plan-to-MRR map. Edit alongside pricing changes in
  -- src/lib/billing/plan-meta.ts.
  SELECT COALESCE(SUM(
    CASE plan
      WHEN 'starter'   THEN 29
      WHEN 'pro'       THEN 99
      WHEN 'business'  THEN 299
      ELSE 0
    END
  ), 0)::numeric
  INTO v_mrr
  FROM public.subscriptions
  WHERE status = 'active';

  RETURN QUERY SELECT v_gross, v_fees, v_refunds, v_net, v_mrr, v_count;
END;
$$;


ALTER FUNCTION "public"."admin_revenue_summary"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_save_plan"("_key" "text", "_name" "text", "_description" "text", "_sort_order" integer, "_is_public" boolean, "_limits" "jsonb", "_features" "text"[], "_pricing" "jsonb" DEFAULT NULL::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  _k        text;
  _clean    jsonb := '{}'::jsonb;
  _monthly  numeric;
  _yearly   numeric;
  _currency text;
  _cur      public.plans%ROWTYPE;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'Unauthorized'; END IF;
  IF _key IS NULL OR _key !~ '^[a-z][a-z0-9_]{1,31}$' THEN RAISE EXCEPTION 'Invalid plan key'; END IF;
  FOREACH _k IN ARRAY ARRAY['max_events','max_attendees_per_event','max_team_members'] LOOP
    IF jsonb_typeof(_limits -> _k) IS DISTINCT FROM 'number' OR (_limits ->> _k)::numeric < -1 THEN
      RAISE EXCEPTION 'Limit % must be a number (-1 for unlimited)', _k;
    END IF;
    _clean := _clean || jsonb_build_object(_k, floor((_limits ->> _k)::numeric)::int);
  END LOOP;

  SELECT * INTO _cur FROM public.plans WHERE key = _key;

  IF _pricing IS NULL THEN
    -- Not given: keep what the plan has (a new plan starts as "Custom").
    _monthly  := _cur.price_monthly;
    _yearly   := _cur.price_yearly;
    _currency := COALESCE(_cur.currency, 'USD');
  ELSE
    IF jsonb_typeof(_pricing) IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'Pricing must be an object';
    END IF;
    FOREACH _k IN ARRAY ARRAY['monthly','yearly'] LOOP
      IF jsonb_typeof(_pricing -> _k) NOT IN ('number', 'null')
         OR (jsonb_typeof(_pricing -> _k) = 'number'
             AND ((_pricing ->> _k)::numeric < 0 OR (_pricing ->> _k)::numeric > 9999999999)) THEN
        RAISE EXCEPTION 'The % price must be empty or a number from 0 up', _k;
      END IF;
    END LOOP;
    _monthly  := round((_pricing ->> 'monthly')::numeric, 2);
    _yearly   := round((_pricing ->> 'yearly')::numeric, 2);
    _currency := upper(btrim(COALESCE(_pricing ->> 'currency', _cur.currency, 'USD')));
    IF _currency !~ '^[A-Z]{3}$' THEN RAISE EXCEPTION 'Currency must be a three-letter code such as INR'; END IF;
  END IF;

  INSERT INTO public.plans (key, name, description, sort_order, is_public, limits, features, price_monthly, price_yearly, currency)
  VALUES (_key, btrim(_name), COALESCE(_description, ''), COALESCE(_sort_order, 0), COALESCE(_is_public, true),
          _clean, (SELECT COALESCE(array_agg(DISTINCT f ORDER BY f), '{}') FROM unnest(COALESCE(_features, '{}')) f),
          _monthly, _yearly, _currency)
  ON CONFLICT (key) DO UPDATE SET
    name = EXCLUDED.name, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order,
    is_public = EXCLUDED.is_public, limits = EXCLUDED.limits, features = EXCLUDED.features,
    price_monthly = EXCLUDED.price_monthly, price_yearly = EXCLUDED.price_yearly, currency = EXCLUDED.currency;

  -- Keep the legacy per-organisation snapshot in step.
  UPDATE public.organizations o
     SET plan_limits = p.limits || jsonb_build_object('features', to_jsonb(p.features))
    FROM public.plans p
   WHERE p.key = _key AND o.plan = _key;

  PERFORM public._plan_audit('plan.save', 'plan', _key,
    jsonb_build_object('name', _name, 'limits', _clean, 'features', to_jsonb(COALESCE(_features, '{}')),
                       'pricing', jsonb_build_object('monthly', _monthly, 'yearly', _yearly, 'currency', _currency)));
END; $_$;


ALTER FUNCTION "public"."admin_save_plan"("_key" "text", "_name" "text", "_description" "text", "_sort_order" integer, "_is_public" boolean, "_limits" "jsonb", "_features" "text"[], "_pricing" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_org_features"("_oid" "uuid", "_overrides" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _e record;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'Unauthorized'; END IF;
  IF jsonb_typeof(COALESCE(_overrides, '{}'::jsonb)) <> 'object' THEN RAISE EXCEPTION 'Overrides must be an object'; END IF;
  FOR _e IN SELECT * FROM jsonb_each(COALESCE(_overrides, '{}'::jsonb)) LOOP
    IF jsonb_typeof(_e.value) <> 'boolean' THEN
      RAISE EXCEPTION 'Override % must be true or false', _e.key;
    END IF;
  END LOOP;
  UPDATE public.organizations SET feature_overrides = COALESCE(_overrides, '{}'::jsonb), updated_at = now() WHERE id = _oid;
  PERFORM public._plan_audit('org.features', 'organization', _oid::text, jsonb_build_object('overrides', _overrides));
END; $$;


ALTER FUNCTION "public"."admin_set_org_features"("_oid" "uuid", "_overrides" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_user_role"("_uid" "uuid", "_role" "public"."app_role", "_grant" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ BEGIN IF NOT has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF NOT _grant AND _role='admin' THEN IF(SELECT count(*) FROM user_roles WHERE role='admin')<=1 AND EXISTS(SELECT 1 FROM user_roles WHERE user_id=_uid AND role='admin') THEN RAISE EXCEPTION 'Last admin'; END IF; END IF; IF _grant THEN INSERT INTO user_roles(user_id,role) VALUES(_uid,_role) ON CONFLICT DO NOTHING; ELSE DELETE FROM user_roles WHERE user_id=_uid AND role=_role; END IF; END; $$;


ALTER FUNCTION "public"."admin_set_user_role"("_uid" "uuid", "_role" "public"."app_role", "_grant" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_ticket_stats"() RETURNS TABLE("total" bigint, "open_count" bigint, "pending_count" bigint, "awaiting_user_count" bigint, "resolved_count" bigint, "closed_count" bigint, "urgent_count" bigint, "high_count" bigint, "last_24h_count" bigint, "avg_resolution_hours" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Not authorised';
  END IF;
  RETURN QUERY
  SELECT
    count(*)::bigint AS total,
    count(*) FILTER (WHERE status = 'open')::bigint,
    count(*) FILTER (WHERE status = 'pending')::bigint,
    count(*) FILTER (WHERE status = 'awaiting_user')::bigint,
    count(*) FILTER (WHERE status = 'resolved')::bigint,
    count(*) FILTER (WHERE status = 'closed')::bigint,
    count(*) FILTER (WHERE priority = 'urgent')::bigint,
    count(*) FILTER (WHERE priority = 'high')::bigint,
    count(*) FILTER (WHERE created_at >= now() - interval '24 hours')::bigint,
    COALESCE(
      AVG(EXTRACT(EPOCH FROM (resolved_at - created_at)) / 3600.0)
        FILTER (WHERE resolved_at IS NOT NULL),
      0
    )::numeric
  FROM public.support_tickets;
END $$;


ALTER FUNCTION "public"."admin_ticket_stats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_unban_user"("_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _req uuid;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  SELECT id INTO _req FROM unban_requests
   WHERE user_id = _user_id AND scope = 'platform' AND status = 'pending'
   ORDER BY created_at DESC LIMIT 1;
  IF _req IS NULL THEN
    RAISE EXCEPTION 'This user has not asked to be unbanned. A ban is lifted only by approving their unban request.'
      USING ERRCODE = '42501';
  END IF;
  PERFORM public.review_unban_request(_req, true, NULL);
END;
$$;


ALTER FUNCTION "public"."admin_unban_user"("_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_update_org"("_oid" "uuid", "_name" "text" DEFAULT NULL::"text", "_subdomain" "text" DEFAULT NULL::"text", "_billing_email" "text" DEFAULT NULL::"text", "_plan" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'Unauthorized'; END IF;
  IF _plan IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.plans WHERE key = _plan) THEN
    RAISE EXCEPTION 'Unknown plan %', _plan;
  END IF;
  UPDATE public.organizations
     SET name = COALESCE(_name, name),
         subdomain = COALESCE(_subdomain, subdomain),
         billing_email = COALESCE(_billing_email, billing_email),
         updated_at = now()
   WHERE id = _oid;
  IF _plan IS NOT NULL THEN
    PERFORM public.admin_update_org_plan(_oid, _plan);
  END IF;
END; $$;


ALTER FUNCTION "public"."admin_update_org"("_oid" "uuid", "_name" "text", "_subdomain" "text", "_billing_email" "text", "_plan" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_update_org_plan"("_oid" "uuid", "_plan" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _p public.plans%ROWTYPE;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'Unauthorized'; END IF;
  SELECT * INTO _p FROM public.plans WHERE key = _plan;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown plan %', _plan; END IF;
  UPDATE public.organizations
     SET plan = _plan,
         plan_limits = _p.limits || jsonb_build_object('features', to_jsonb(_p.features)),
         updated_at = now()
   WHERE id = _oid;
  IF to_regclass('public.subscriptions') IS NOT NULL THEN
    UPDATE public.subscriptions SET plan = _plan, updated_at = now() WHERE org_id = _oid;
  END IF;
  PERFORM public._plan_audit('org.plan', 'organization', _oid::text, jsonb_build_object('plan', _plan));
END; $$;


ALTER FUNCTION "public"."admin_update_org_plan"("_oid" "uuid", "_plan" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_user_activity_feed"("_user_id" "uuid", "_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "actor_id" "uuid", "actor_email" "text", "action" "text", "target_type" "text", "target_id" "text", "details" "jsonb", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  RETURN QUERY
  SELECT a.id, a.actor_id, a.actor_email, a.action,
         a.target_type, a.target_id, a.details, a.created_at
  FROM public.audit_logs a
  WHERE a.actor_id = _user_id
     OR a.target_id = _user_id::text
  ORDER BY a.created_at DESC
  LIMIT GREATEST(1, LEAST(_limit, 500));
END;
$$;


ALTER FUNCTION "public"."admin_user_activity_feed"("_user_id" "uuid", "_limit" integer) OWNER TO "postgres";


