CREATE OR REPLACE FUNCTION "public"."cancel_booking"("p_booking_id" "uuid", "p_actor_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_booking vendor_bookings%ROWTYPE;
BEGIN
  SELECT * INTO v_booking FROM vendor_bookings WHERE id = p_booking_id FOR UPDATE;
  IF v_booking IS NULL THEN
    RAISE EXCEPTION 'Booking not found';
  END IF;
  IF v_booking.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'Cannot cancel a % booking', v_booking.status;
  END IF;

  -- 1. Cancel the booking
  UPDATE vendor_bookings
  SET status = 'cancelled', updated_at = now()
  WHERE id = p_booking_id;

  -- 2. Refund all held escrow
  UPDATE payment_escrow
  SET status = 'refunded', refunded_at = now(),
      notes = COALESCE(notes, '') || ' | Refunded due to cancellation'
  WHERE booking_id = p_booking_id AND status = 'held';

  -- 3. Free the calendar date
  DELETE FROM vendor_availability
  WHERE booking_id = p_booking_id AND status = 'booked';

  -- 4. Audit log
  INSERT INTO vendor_audit_log (actor_id, action, entity_type, entity_id, metadata)
  VALUES (
    p_actor_id, 'booking_cancelled', 'vendor_bookings', p_booking_id,
    jsonb_build_object(
      'previous_status', v_booking.status,
      'reason', COALESCE(p_reason, 'No reason provided')
    )
  );
END;
$$;


ALTER FUNCTION "public"."cancel_booking"("p_booking_id" "uuid", "p_actor_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."certificate_date_text"("_start" timestamp with time zone, "_end" timestamp with time zone, "_tz" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  z  text := coalesce(nullif(_tz, ''), 'UTC');
  s  timestamp;
  e  timestamp;
BEGIN
  IF _start IS NULL THEN RETURN ''; END IF;
  BEGIN
    s := _start AT TIME ZONE z;
    e := coalesce(_end, _start) AT TIME ZONE z;
  EXCEPTION WHEN OTHERS THEN
    s := _start AT TIME ZONE 'UTC';
    e := coalesce(_end, _start) AT TIME ZONE 'UTC';
  END;
  IF s::date = e::date THEN RETURN to_char(s, 'FMDD FMMonth YYYY'); END IF;
  IF to_char(s, 'YYYY-MM') = to_char(e, 'YYYY-MM') THEN RETURN to_char(s, 'FMDD') || '–' || to_char(e, 'FMDD FMMonth YYYY'); END IF;
  IF to_char(s, 'YYYY') = to_char(e, 'YYYY') THEN RETURN to_char(s, 'FMDD FMMonth') || ' – ' || to_char(e, 'FMDD FMMonth YYYY'); END IF;
  RETURN to_char(s, 'FMDD FMMonth YYYY') || ' – ' || to_char(e, 'FMDD FMMonth YYYY');
END;
$$;


ALTER FUNCTION "public"."certificate_date_text"("_start" timestamp with time zone, "_end" timestamp with time zone, "_tz" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."certificate_templates_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR current_setting('illuxus.certificate_publish', true) = 'on' THEN
    RETURN NEW;
  END IF;
  NEW.updated_at := now();
  IF TG_OP = 'INSERT' THEN
    NEW.created_by := auth.uid();
    NEW.status := CASE WHEN NEW.status = 'archived' THEN 'archived' ELSE 'draft' END;
    NEW.current_version := 0;
    NEW.published_version_id := NULL;
    NEW.published_at := NULL;
  ELSE
    NEW.org_id := OLD.org_id;
    NEW.created_by := OLD.created_by;
    NEW.created_at := OLD.created_at;
    NEW.current_version := OLD.current_version;
    NEW.published_version_id := OLD.published_version_id;
    NEW.published_at := OLD.published_at;
    IF NEW.status = 'published' AND OLD.status <> 'published' THEN
      NEW.status := CASE WHEN OLD.published_version_id IS NOT NULL THEN 'published' ELSE 'draft' END;
    END IF;
    IF NEW.status = 'draft' AND OLD.published_version_id IS NOT NULL THEN
      NEW.status := 'published';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."certificate_templates_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_vendor_availability"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.status = 'booked' THEN
    -- Check if already booked by a different booking
    IF EXISTS (
      SELECT 1 FROM vendor_availability
      WHERE vendor_id = NEW.vendor_id
        AND date = NEW.date
        AND status = 'booked'
        AND id != COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
    ) THEN
      RAISE EXCEPTION 'Vendor is already booked on %', NEW.date;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_vendor_availability"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_vendor_availability_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.status = 'booked' THEN
    IF EXISTS (
      SELECT 1 FROM vendor_availability
      WHERE vendor_id = NEW.vendor_id
        AND date = NEW.date
        AND status = 'booked'
        AND id IS DISTINCT FROM NEW.id
    ) THEN
      RAISE EXCEPTION 'Vendor already booked on % (double-booking prevented)', NEW.date;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_vendor_availability_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_join_session"("_jt" "text", "_sid" "text") RETURNS TABLE("registration_id" "uuid", "event_id" "uuid", "user_id" "uuid", "name" "text", "email" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _r registrations;
BEGIN SELECT * INTO _r FROM registrations WHERE join_token=_jt; IF _r.id IS NULL THEN RAISE EXCEPTION 'Invalid join link'; END IF;
  IF _r.user_id IS NOT NULL AND _r.user_id<>auth.uid() THEN RAISE EXCEPTION 'Belongs to another account'; END IF;
  UPDATE registrations SET active_session_id=_sid,active_session_started_at=now(),user_id=COALESCE(user_id,auth.uid()) WHERE id=_r.id;
  RETURN QUERY SELECT _r.id,_r.event_id,COALESCE(_r.user_id,auth.uid()),_r.name,_r.email;
END; $$;


ALTER FUNCTION "public"."claim_join_session"("_jt" "text", "_sid" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_person_for_verified_email"("_user_id" "uuid", "_email" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _key     text := public.norm_email(_email);
  _person  uuid;
  _mine    uuid;
  _owner   uuid;
  _name    text;
BEGIN
  IF _user_id IS NULL OR _key IS NULL THEN RETURN NULL; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('person_email:' || _key, 0));

  SELECT id INTO _mine FROM people WHERE user_id = _user_id;
  SELECT person_id INTO _person FROM person_emails WHERE email_key = _key;

  IF _person IS NULL THEN
    -- An address nobody had: it goes on the account's person.
    IF _mine IS NULL THEN
      SELECT NULLIF(btrim(COALESCE(first_name, '') || ' ' || COALESCE(last_name, '')), '')
        INTO _name FROM profiles WHERE user_id = _user_id;
      INSERT INTO people (user_id, display_name, name_key, created_via)
      VALUES (_user_id, _name, public.person_name_key(_name), 'signup')
      RETURNING id INTO _mine;
    END IF;
    INSERT INTO person_emails (person_id, email, email_key, verified_at, source)
    VALUES (_mine, public.norm_text(_email), _key, now(), 'auth');
    RETURN _mine;
  END IF;

  SELECT user_id INTO _owner FROM people WHERE id = _person;
  IF _owner IS NOT NULL AND _owner <> _user_id THEN
    INSERT INTO audit_logs (actor_id, action, target_type, target_id, details)
    VALUES (_user_id, 'identity.claim_conflict', 'person', _person::text,
            jsonb_build_object('email_key', _key, 'linked_account', _owner));
    RETURN NULL;
  END IF;

  IF _mine IS NOT NULL AND _mine <> _person THEN
    -- The account already has a person and this address has another: the
    -- address is proven, and the two records wait for review.
    UPDATE person_emails SET verified_at = COALESCE(verified_at, now()) WHERE email_key = _key;
    PERFORM public._queue_identity_candidate(_mine, _person, 'verified_email_same_account');
    RETURN _mine;
  END IF;

  IF _owner IS NULL THEN
    UPDATE people SET user_id = _user_id, updated_at = now() WHERE id = _person;
    INSERT INTO audit_logs (actor_id, action, target_type, target_id, details)
    VALUES (_user_id, 'identity.linked_account', 'person', _person::text, jsonb_build_object('email_key', _key));
  END IF;
  UPDATE person_emails SET verified_at = COALESCE(verified_at, now()) WHERE email_key = _key;
  RETURN _person;
END;
$$;


ALTER FUNCTION "public"."claim_person_for_verified_email"("_user_id" "uuid", "_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communications_diagnose"("_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  _row        RECORD;
  _result     jsonb;
  _err        text;
  _err_state  text;
BEGIN
  SELECT id, status, channels, recipient_filter, event_id, community_id,
         scheduled_for, sent_at, last_error
    INTO _row
    FROM communications
   WHERE id = _id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'communication not found', 'id', _id);
  END IF;

  BEGIN
    _result := _communications_dispatch_impl(_id);
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS _err_state = RETURNED_SQLSTATE;
    _err := SQLERRM;
    UPDATE communications
       SET status = 'failed', last_error = LEFT(_err, 1000), updated_at = now()
     WHERE id = _id;
    RETURN jsonb_build_object(
      'ok',         false,
      'id',         _id,
      'sqlstate',   _err_state,
      'error',      _err,
      'comm_state', to_jsonb(_row)
    );
  END;

  RETURN jsonb_build_object(
    'ok',         true,
    'id',         _id,
    'dispatch',   _result,
    'comm_state', to_jsonb(_row)
  );
END;
$$;


ALTER FUNCTION "public"."communications_diagnose"("_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communications_dispatch"("_communication_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _comm communications%ROWTYPE;
  _allowed boolean := false;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Must be signed in'; END IF;

  SELECT * INTO _comm FROM communications WHERE id = _communication_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Communication % not found', _communication_id;
  END IF;

  -- Org members can dispatch event-scoped comms; community managers can
  -- dispatch community-scoped comms; admins can dispatch anything.
  IF _comm.event_id IS NOT NULL THEN
    _allowed := EXISTS (
      SELECT 1 FROM org_members om
       WHERE om.org_id = _comm.org_id AND om.user_id = auth.uid()
    );
  ELSIF _comm.community_id IS NOT NULL THEN
    _allowed := can_moderate_community(auth.uid(), _comm.community_id);
  END IF;

  IF NOT _allowed AND NOT has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'Not authorised to dispatch this communication';
  END IF;

  RETURN _communications_dispatch_impl(_communication_id);
END;
$$;


ALTER FUNCTION "public"."communications_dispatch"("_communication_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communications_duplicate"("_communication_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _comm communications%ROWTYPE;
  _new_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Must be signed in'; END IF;
  SELECT * INTO _comm FROM communications WHERE id = _communication_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Communication % not found', _communication_id; END IF;

  IF NOT EXISTS (
    SELECT 1 FROM org_members om
     WHERE om.org_id = _comm.org_id AND om.user_id = auth.uid()
  ) AND NOT has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'Not authorised';
  END IF;

  INSERT INTO communications (
    org_id, event_id, community_id, channels, recipient_filter,
    subject, body_text, body_html, status, created_by
  )
  VALUES (
    _comm.org_id, _comm.event_id, _comm.community_id,
    _comm.channels, _comm.recipient_filter,
    'Copy of ' || _comm.subject,
    _comm.body_text, _comm.body_html,
    'draft', auth.uid()
  )
  RETURNING id INTO _new_id;

  RETURN _new_id;
END;
$$;


ALTER FUNCTION "public"."communications_duplicate"("_communication_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communications_recompute_email_counts"("_communication_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE communications
     SET sent_count   = (SELECT count(*)
                            FROM communication_recipients
                           WHERE communication_id = _communication_id
                             AND email_status IN ('sent','delivered','opened','clicked')),
         failed_count = (SELECT count(*)
                            FROM communication_recipients
                           WHERE communication_id = _communication_id
                             AND email_status IN ('bounced','failed')),
         updated_at   = now()
   WHERE id = _communication_id;
END;
$$;


ALTER FUNCTION "public"."communications_recompute_email_counts"("_communication_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communications_resolve_community_recipients"("_community_id" "uuid", "_filter" "jsonb") RETURNS TABLE("user_id" "uuid", "name" "text", "email" "text", "phone" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  _types     text[];
  _user_ids  uuid[];
BEGIN
  _types := COALESCE(
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(_filter -> 'types', '[]'::jsonb))),
    ARRAY[]::text[]
  );
  _user_ids := COALESCE(
    ARRAY(SELECT (jsonb_array_elements_text(COALESCE(_filter -> 'user_ids', '[]'::jsonb)))::uuid),
    ARRAY[]::uuid[]
  );

  -- No signed-in user: only the service role or an internal job (pg_cron,
  -- not an API request) may continue. The public anon key is neither.
  IF auth.uid() IS NULL AND NOT public._is_internal_caller() THEN
    RAISE EXCEPTION 'Sign in required' USING ERRCODE = '42501';
  END IF;

  IF auth.uid() IS NOT NULL AND NOT can_moderate_community(auth.uid(), _community_id) THEN
    RAISE EXCEPTION 'Not authorised to read community members';
  END IF;

  RETURN QUERY
  WITH base AS (
    SELECT cm.user_id,
           cm.role,
           COALESCE(
             NULLIF(trim(coalesce(p.first_name,'') || ' ' || coalesce(p.last_name,'')), ''),
             p.display_name,
             p.username,
             split_part(u.email,'@',1)
           ) AS name,
           lower(u.email) AS email,
           NULLIF(trim(coalesce(p.mobile_country_code,'') || ' ' || coalesce(p.mobile_number,'')), '') AS phone
      FROM community_members cm
      JOIN auth.users u ON u.id = cm.user_id
      LEFT JOIN profiles p ON p.user_id = cm.user_id
     WHERE cm.community_id = _community_id
       AND cm.status = 'active'
  ),
  filtered AS (
    SELECT b.user_id, b.name, b.email, b.phone, b.role
      FROM base b
     WHERE
       'all_members' = ANY(_types)
       OR ('managers'   = ANY(_types) AND b.role = 'manager'::community_role)
       OR ('moderators' = ANY(_types) AND b.role = 'moderator'::community_role)
       OR ('organizers' = ANY(_types) AND b.role = 'organizer'::community_role)
       OR ('mentors'    = ANY(_types) AND b.role = 'mentor'::community_role)
       OR ('speakers'   = ANY(_types) AND b.role = 'speaker'::community_role)
       OR ('sponsors'   = ANY(_types) AND b.role = 'sponsor'::community_role)
       OR ('custom'     = ANY(_types) AND b.user_id = ANY(_user_ids))
  )
  SELECT DISTINCT ON (lower(coalesce(f.email,'')))
         f.user_id, f.name, f.email, f.phone
    FROM filtered f
   WHERE f.email IS NOT NULL AND f.email <> ''
   ORDER BY lower(coalesce(f.email,'')), f.user_id NULLS LAST;
END;
$$;


ALTER FUNCTION "public"."communications_resolve_community_recipients"("_community_id" "uuid", "_filter" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communications_resolve_recipients"("_event_id" "uuid", "_filter" "jsonb") RETURNS TABLE("user_id" "uuid", "name" "text", "email" "text", "phone" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  _types     text[];
  _user_ids  uuid[];
  _emails    text[];
BEGIN
  _types := COALESCE(
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(_filter -> 'types', '[]'::jsonb))),
    ARRAY[]::text[]
  );
  _user_ids := COALESCE(
    ARRAY(SELECT (jsonb_array_elements_text(COALESCE(_filter -> 'user_ids', '[]'::jsonb)))::uuid),
    ARRAY[]::uuid[]
  );
  _emails := COALESCE(
    ARRAY(SELECT lower(jsonb_array_elements_text(COALESCE(_filter -> 'emails', '[]'::jsonb)))),
    ARRAY[]::text[]
  );

  -- No signed-in user: only the service role or an internal job (pg_cron,
  -- not an API request) may continue. The public anon key is neither.
  IF auth.uid() IS NULL AND NOT public._is_internal_caller() THEN
    RAISE EXCEPTION 'Sign in required' USING ERRCODE = '42501';
  END IF;

  IF auth.uid() IS NOT NULL AND _event_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
        FROM events e
        JOIN org_members om ON om.org_id = e.org_id
       WHERE e.id = _event_id AND om.user_id = auth.uid()
    ) AND NOT has_role(auth.uid(), 'admin'::app_role) THEN
      RAISE EXCEPTION 'Not authorised to read recipients for this event';
    END IF;
  END IF;

  RETURN QUERY
  WITH base AS (
    -- Orphan-user-id guard from migration 017 retained.
    SELECT CASE
             WHEN r.user_id IS NULL THEN NULL
             WHEN EXISTS (SELECT 1 FROM auth.users u WHERE u.id = r.user_id)
               THEN r.user_id
             ELSE NULL
           END AS user_id,
           COALESCE(NULLIF(trim(coalesce(r.first_name,'') || ' ' || coalesce(r.last_name,'')), ''),
                    r.name, split_part(r.email,'@',1)) AS name,
           lower(r.email) AS email,
           NULLIF(trim(coalesce(r.mobile_country_code,'') || ' ' || coalesce(r.mobile_number,'')), '') AS phone,
           COALESCE(r.attendance_state, 'never') AS attendance_state,
           COALESCE(r.amount_paid, 0)::numeric AS amount_paid
      FROM registrations r
     WHERE r.event_id = _event_id
       AND r.status <> 'cancelled'
       AND COALESCE(r.approval_status, 'approved') NOT IN ('declined','waitlisted')
  ),
  speakers_set AS (
    SELECT CASE
             WHEN s.user_id IS NULL THEN NULL
             WHEN EXISTS (SELECT 1 FROM auth.users u WHERE u.id = s.user_id)
               THEN s.user_id
             ELSE NULL
           END AS user_id,
           COALESCE(NULLIF(trim(coalesce(s.name,'')), ''), split_part(s.email,'@',1)) AS name,
           lower(s.email) AS email,
           NULL::text AS phone
      FROM event_speakers es
      JOIN speakers s ON s.id = es.speaker_id
     WHERE es.event_id = _event_id AND s.email IS NOT NULL
  ),
  sponsors_set AS (
    SELECT NULL::uuid AS user_id,
           COALESCE(NULLIF(trim(coalesce(s.name,'')), ''),
                    split_part(s.email,'@',1)) AS name,
           lower(s.email) AS email,
           NULL::text AS phone
      FROM event_sponsors es
      JOIN sponsors s ON s.id = es.sponsor_id
     WHERE es.event_id = _event_id AND s.email IS NOT NULL
  ),
  sponsor_contacts_set AS (
    -- The people listed under a sponsor (sponsor_members). The compose
    -- picker offers each of them, so a custom selection has to reach them,
    -- not only the sponsor's own email.
    SELECT CASE
             WHEN m.user_id IS NULL THEN NULL
             WHEN EXISTS (SELECT 1 FROM auth.users u WHERE u.id = m.user_id)
               THEN m.user_id
             ELSE NULL
           END AS user_id,
           COALESCE(NULLIF(trim(coalesce(m.display_name,'')), ''),
                    NULLIF(trim(coalesce(m.first_name,'') || ' ' || coalesce(m.last_name,'')), ''),
                    split_part(m.email,'@',1)) AS name,
           lower(m.email) AS email,
           NULLIF(trim(coalesce(m.mobile_country_code,'') || ' ' || coalesce(m.mobile_number,'')), '') AS phone
      FROM event_sponsors es
      JOIN sponsor_members m ON m.sponsor_id = es.sponsor_id
     WHERE es.event_id = _event_id AND m.email IS NOT NULL
  ),
  filtered_attendees AS (
    SELECT b.user_id, b.name, b.email, b.phone
      FROM base b
     WHERE
       (
         'all_attendees' = ANY(_types)
       )
       OR (
         'checked_in' = ANY(_types) AND b.attendance_state IN ('inside','outside')
       )
       OR (
         'paid' = ANY(_types) AND b.amount_paid > 0
       )
  ),
  custom_set AS (
    -- New: match by user_id OR email. Imported participants without an
    -- auth account (user_id NULL) still match via their email — which is
    -- always present because the form/import validation requires it.
    SELECT b.user_id, b.name, b.email, b.phone
      FROM base b
     WHERE 'custom' = ANY(_types)
       AND (
            (b.user_id IS NOT NULL AND b.user_id = ANY(_user_ids))
         OR (lower(b.email) = ANY(_emails))
       )
    UNION
    -- Speakers and sponsors in custom selection follow the same rule, so
    -- the organiser can pick a single speaker without bringing the whole
    -- speaker group along.
    SELECT s.user_id, s.name, s.email, s.phone
      FROM speakers_set s
     WHERE 'custom' = ANY(_types)
       AND (
            (s.user_id IS NOT NULL AND s.user_id = ANY(_user_ids))
         OR (lower(s.email) = ANY(_emails))
       )
    UNION
    SELECT sp.user_id, sp.name, sp.email, sp.phone
      FROM sponsors_set sp
     WHERE 'custom' = ANY(_types)
       AND lower(sp.email) = ANY(_emails)
    UNION
    SELECT sc.user_id, sc.name, sc.email, sc.phone
      FROM sponsor_contacts_set sc
     WHERE 'custom' = ANY(_types)
       AND (
            (sc.user_id IS NOT NULL AND sc.user_id = ANY(_user_ids))
         OR (sc.email = ANY(_emails))
       )
  ),
  all_recipients AS (
    SELECT user_id, name, email, phone FROM filtered_attendees
    UNION
    SELECT user_id, name, email, phone FROM custom_set
    UNION ALL
    SELECT user_id, name, email, phone FROM speakers_set
     WHERE 'speakers' = ANY(_types)
    UNION ALL
    SELECT user_id, name, email, phone FROM sponsors_set
     WHERE 'sponsors' = ANY(_types)
  )
  SELECT DISTINCT ON (lower(coalesce(ar.email,'')))
         ar.user_id, ar.name, ar.email, ar.phone
    FROM all_recipients ar
   WHERE ar.email IS NOT NULL AND ar.email <> ''
   ORDER BY lower(coalesce(ar.email,'')), ar.user_id NULLS LAST;
END;
$$;


ALTER FUNCTION "public"."communications_resolve_recipients"("_event_id" "uuid", "_filter" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."communications_resolve_recipients"("_event_id" "uuid", "_filter" "jsonb") IS 'Resolves event communication recipients. Custom selection matches by user_id OR email so imported participants without an auth account still receive the message, and reaches sponsor contacts (sponsor_members) as well as the sponsor''s own email. Auth / password state is never used as a filter — everyone with an addressable email on the registration row is eligible. Not executable by anon; a caller with no signed-in user must be the service role or an internal job.';



CREATE OR REPLACE FUNCTION "public"."communications_retry_failed"("_communication_id" "uuid", "_channel" "text" DEFAULT 'whatsapp'::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _comm communications%ROWTYPE;
  _allowed boolean := false;
  _reset int := 0;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Must be signed in'; END IF;
  IF _channel NOT IN ('email','whatsapp') THEN
    RAISE EXCEPTION 'Invalid channel: %', _channel;
  END IF;

  SELECT * INTO _comm FROM communications WHERE id = _communication_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Communication % not found', _communication_id; END IF;

  IF _comm.event_id IS NOT NULL THEN
    _allowed := EXISTS (
      SELECT 1 FROM org_members om
       WHERE om.org_id = _comm.org_id AND om.user_id = auth.uid()
    );
  ELSIF _comm.community_id IS NOT NULL THEN
    _allowed := can_moderate_community(auth.uid(), _comm.community_id);
  END IF;
  IF NOT _allowed AND NOT has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'Not authorised';
  END IF;

  IF _channel = 'whatsapp' THEN
    UPDATE communication_recipients
       SET whatsapp_status = 'pending', error_message = NULL
     WHERE communication_id = _communication_id
       AND whatsapp_status = 'failed';
    GET DIAGNOSTICS _reset = ROW_COUNT;
  ELSE
    UPDATE communication_recipients
       SET email_status = 'pending', error_message = NULL
     WHERE communication_id = _communication_id
       AND email_status = 'failed';
    GET DIAGNOSTICS _reset = ROW_COUNT;
  END IF;

  RETURN _reset;
END;
$$;


ALTER FUNCTION "public"."communications_retry_failed"("_communication_id" "uuid", "_channel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communications_run_scheduled"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  _comm        RECORD;
  _processed   INT := 0;
  _failed      INT := 0;
  _invoked     INT := 0;
  _last_error  text;
  _supabase_url text;
  _service_key  text;
BEGIN
  SELECT value INTO _supabase_url FROM public.app_settings WHERE key = 'supabase_url';
  SELECT value INTO _service_key  FROM public.app_settings WHERE key = 'service_role_key';

  FOR _comm IN
    SELECT id, channels
      FROM communications
     WHERE status = 'scheduled'
       AND scheduled_for <= now()
     ORDER BY scheduled_for
     LIMIT 50
  LOOP
    BEGIN
      PERFORM _communications_dispatch_impl(_comm.id);
      _processed := _processed + 1;

      IF _supabase_url IS NOT NULL AND _service_key IS NOT NULL THEN
        IF 'email' = ANY(_comm.channels) THEN
          PERFORM net.http_post(
            url     := _supabase_url || '/functions/v1/send-communication-email',
            headers := jsonb_build_object(
              'Authorization', 'Bearer ' || _service_key,
              'Content-Type',  'application/json'
            ),
            body    := jsonb_build_object('communication_id', _comm.id)
          );
          _invoked := _invoked + 1;
        END IF;

        IF 'whatsapp' = ANY(_comm.channels) THEN
          PERFORM net.http_post(
            url     := _supabase_url || '/functions/v1/send-whatsapp',
            headers := jsonb_build_object(
              'Authorization', 'Bearer ' || _service_key,
              'Content-Type',  'application/json'
            ),
            body    := jsonb_build_object('communication_id', _comm.id)
          );
          _invoked := _invoked + 1;
        END IF;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      _failed := _failed + 1;
      _last_error := SQLERRM;
      UPDATE communications
         SET status     = 'failed',
             last_error = LEFT(SQLERRM, 1000),
             updated_at = now()
       WHERE id = _comm.id;
      -- Also raise as a postgres LOG so it shows up in cron.job_run_details.
      RAISE LOG 'communications_run_scheduled failed for %: %', _comm.id, SQLERRM;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'processed',   _processed,
    'failed',      _failed,
    'invoked',     _invoked,
    'has_url',     _supabase_url IS NOT NULL,
    'has_key',     _service_key  IS NOT NULL,
    'last_error',  _last_error
  );
END;
$$;


ALTER FUNCTION "public"."communications_run_scheduled"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communications_schedule"("_communication_id" "uuid", "_scheduled_for" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _comm communications%ROWTYPE;
  _allowed boolean := false;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Must be signed in'; END IF;
  IF _scheduled_for IS NULL THEN RAISE EXCEPTION 'scheduled_for is required'; END IF;
  IF _scheduled_for <= now() THEN RAISE EXCEPTION 'scheduled_for must be in the future'; END IF;

  SELECT * INTO _comm FROM communications WHERE id = _communication_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Communication % not found', _communication_id; END IF;

  IF _comm.event_id IS NOT NULL THEN
    _allowed := EXISTS (
      SELECT 1 FROM org_members om
       WHERE om.org_id = _comm.org_id AND om.user_id = auth.uid()
    );
  ELSIF _comm.community_id IS NOT NULL THEN
    _allowed := can_moderate_community(auth.uid(), _comm.community_id);
  END IF;
  IF NOT _allowed AND NOT has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'Not authorised';
  END IF;

  IF _comm.status NOT IN ('draft', 'scheduled', 'failed') THEN
    RAISE EXCEPTION 'Communication is in % state and cannot be scheduled', _comm.status;
  END IF;

  UPDATE communications
     SET status = 'scheduled', scheduled_for = _scheduled_for, updated_at = now()
   WHERE id = _communication_id;
END;
$$;


ALTER FUNCTION "public"."communications_schedule"("_communication_id" "uuid", "_scheduled_for" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."communications_unschedule"("_communication_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _comm communications%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Must be signed in'; END IF;
  SELECT * INTO _comm FROM communications WHERE id = _communication_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Communication % not found', _communication_id; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM org_members om
     WHERE om.org_id = _comm.org_id AND om.user_id = auth.uid()
  ) AND NOT has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'Not authorised';
  END IF;

  IF _comm.status <> 'scheduled' THEN
    RAISE EXCEPTION 'Communication is not scheduled';
  END IF;

  UPDATE communications
     SET status        = 'draft',
         scheduled_for = NULL,
         updated_at    = now()
   WHERE id = _communication_id;
END;
$$;


ALTER FUNCTION "public"."communications_unschedule"("_communication_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_connect"("_target_id" "uuid", "_kind" "text" DEFAULT 'connect'::"text", "_community_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _id uuid; _status text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Must be signed in'; END IF;
  IF _kind NOT IN ('follow','connect') THEN RAISE EXCEPTION 'Invalid kind'; END IF;
  IF _target_id = auth.uid() THEN RAISE EXCEPTION 'Cannot connect with self'; END IF;

  -- Follows are auto-accepted; connects need approval
  _status := CASE WHEN _kind = 'follow' THEN 'accepted' ELSE 'pending' END;

  INSERT INTO community_connections (requester_id, target_id, kind, status, context_community_id, responded_at)
  VALUES (auth.uid(), _target_id, _kind, _status, _community_id, CASE WHEN _status='accepted' THEN now() ELSE NULL END)
  ON CONFLICT (requester_id, target_id, kind) DO UPDATE SET
    status = _status,
    responded_at = CASE WHEN _status='accepted' THEN now() ELSE community_connections.responded_at END
  RETURNING id INTO _id;
  RETURN _id;
END;
$$;


ALTER FUNCTION "public"."community_connect"("_target_id" "uuid", "_kind" "text", "_community_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_create_poll"("_community_id" "uuid", "_question" "text", "_options" "jsonb", "_multi" boolean DEFAULT false, "_closes_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _post_id uuid; _poll_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Must be signed in'; END IF;
  IF NOT is_community_member(auth.uid(), _community_id) THEN
    RAISE EXCEPTION 'Not a member';
  END IF;
  IF jsonb_array_length(_options) < 2 THEN
    RAISE EXCEPTION 'Need at least 2 options';
  END IF;

  INSERT INTO community_posts (community_id, author_id, type, title, body_md)
  VALUES (_community_id, auth.uid(), 'poll', _question, '')
  RETURNING id INTO _post_id;

  INSERT INTO community_polls (post_id, multi, options, closes_at)
  VALUES (_post_id, _multi, _options, _closes_at)
  RETURNING id INTO _poll_id;

  RETURN _post_id;
END;
$$;


ALTER FUNCTION "public"."community_create_poll"("_community_id" "uuid", "_question" "text", "_options" "jsonb", "_multi" boolean, "_closes_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_create_post"("_community_id" "uuid", "_type" "public"."community_post_type", "_title" "text", "_body_md" "text", "_attachments" "jsonb" DEFAULT '[]'::"jsonb", "_link_url" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _id uuid;
  _role community_role;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Must be signed in'; END IF;
  IF NOT is_community_member(auth.uid(), _community_id) THEN
    RAISE EXCEPTION 'Not a member of this community';
  END IF;
  IF _type = 'announcement' THEN
    _role := community_role_of(auth.uid(), _community_id);
    IF _role NOT IN ('organizer','moderator','manager') THEN
      RAISE EXCEPTION 'Only organizers, moderators, or managers can post announcements';
    END IF;
  END IF;

  INSERT INTO community_posts (community_id, author_id, type, title, body_md, attachments, link_url)
  VALUES (_community_id, auth.uid(), _type, NULLIF(trim(_title), ''), coalesce(_body_md, ''),
          COALESCE(_attachments, '[]'::jsonb), _link_url)
  RETURNING id INTO _id;
  RETURN _id;
END;
$$;


ALTER FUNCTION "public"."community_create_post"("_community_id" "uuid", "_type" "public"."community_post_type", "_title" "text", "_body_md" "text", "_attachments" "jsonb", "_link_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_join"("_community_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _id uuid;
  _kind community_kind;
  _status text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Must be signed in'; END IF;

  SELECT kind INTO _kind FROM public.communities WHERE id = _community_id;
  IF _kind = 'event' THEN
    RAISE EXCEPTION 'Event communities can only be joined by registering for the event.';
  END IF;

  SELECT status INTO _status FROM public.community_members
   WHERE community_id = _community_id AND user_id = auth.uid();
  IF _status IN ('banned', 'suspended') THEN
    RAISE EXCEPTION 'You were removed from this community. You can ask its organisers to let you back in from My Communities.'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO community_members (community_id, user_id, role, status, auto)
  VALUES (_community_id, auth.uid(), 'member', 'active', false)
  ON CONFLICT (community_id, user_id) DO UPDATE
    SET status = 'active', joined_at = excluded.joined_at
  RETURNING id INTO _id;
  RETURN _id;
END;
$$;


ALTER FUNCTION "public"."community_join"("_community_id" "uuid") OWNER TO "postgres";


