CREATE OR REPLACE FUNCTION "public"."community_resync_from_previous"("_event_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _community_id uuid;
  _previous uuid;
  _copied int := 0;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Must be signed in'; END IF;

  SELECT id INTO _community_id FROM communities WHERE event_id = _event_id;
  IF _community_id IS NULL THEN RAISE EXCEPTION 'No community for this event'; END IF;

  IF NOT can_moderate_community(auth.uid(), _community_id) THEN
    RAISE EXCEPTION 'Not authorised';
  END IF;

  SELECT previous_event_id INTO _previous FROM events WHERE id = _event_id;
  IF _previous IS NULL THEN RETURN 0; END IF;

  _copied := _copy_community_members_from_previous(_community_id, _previous);
  RETURN _copied;
END;
$$;


ALTER FUNCTION "public"."community_resync_from_previous"("_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_role_of"("_user_id" "uuid", "_community_id" "uuid") RETURNS "public"."community_role"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT role FROM public.community_members
  WHERE community_id = _community_id AND user_id = _user_id AND status = 'active'
  LIMIT 1;
$$;


ALTER FUNCTION "public"."community_role_of"("_user_id" "uuid", "_community_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_search"("_q" "text", "_community_id" "uuid" DEFAULT NULL::"uuid", "_limit" integer DEFAULT 30) RETURNS TABLE("kind" "text", "id" "uuid", "community_id" "uuid", "title" "text", "snippet" "text", "score" real, "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT 'post'::text, p.id, p.community_id,
         COALESCE(p.title, substring(p.body_md from 1 for 60)) AS title,
         substring(p.body_md from 1 for 200) AS snippet,
         ts_rank(p.ts_search, websearch_to_tsquery('simple', _q)) AS score,
         p.created_at
  FROM community_posts p
  WHERE (NOT p.hidden)
    AND p.ts_search @@ websearch_to_tsquery('simple', _q)
    AND (_community_id IS NULL OR p.community_id = _community_id)
    AND (
      is_community_member(auth.uid(), p.community_id)
      OR has_role(auth.uid(),'admin'::app_role)
    )
  UNION ALL
  SELECT 'community'::text, c.id, c.id,
         c.name, COALESCE(c.description,''),
         similarity(lower(c.name), lower(_q)),
         c.created_at
  FROM communities c
  WHERE (c.visibility = 'public' OR is_community_member(auth.uid(), c.id))
    AND (lower(c.name) LIKE '%' || lower(_q) || '%' OR lower(coalesce(c.description,'')) LIKE '%' || lower(_q) || '%')
  ORDER BY score DESC NULLS LAST, created_at DESC
  LIMIT _limit;
$$;


ALTER FUNCTION "public"."community_search"("_q" "text", "_community_id" "uuid", "_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_set_member_role"("_community_id" "uuid", "_user_id" "uuid", "_role" "public"."community_role") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _viewer_role community_role;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Must be signed in'; END IF;

  _viewer_role := community_role_of(auth.uid(), _community_id);
  IF _viewer_role IS DISTINCT FROM 'manager' AND NOT has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'Only managers can change member roles';
  END IF;
  IF _user_id = auth.uid() THEN
    RAISE EXCEPTION 'Use the leave action to change your own role';
  END IF;

  UPDATE community_members
     SET role = _role
   WHERE community_id = _community_id AND user_id = _user_id;

  PERFORM _record_audit(
    'community.member.role',
    'community_member',
    _user_id::text,
    jsonb_build_object('community_id', _community_id, 'role', _role::text)
  );
END;
$$;


ALTER FUNCTION "public"."community_set_member_role"("_community_id" "uuid", "_user_id" "uuid", "_role" "public"."community_role") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_set_member_status"("_community_id" "uuid", "_user_id" "uuid", "_status" "text", "_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Must be signed in'; END IF;
  IF _status NOT IN ('active','suspended','banned') THEN
    RAISE EXCEPTION 'Invalid status';
  END IF;
  IF NOT can_moderate_community(auth.uid(), _community_id) THEN
    RAISE EXCEPTION 'Not a moderator';
  END IF;
  IF _status <> 'banned' AND EXISTS (
       SELECT 1 FROM community_members
        WHERE community_id = _community_id AND user_id = _user_id AND status = 'banned') THEN
    RAISE EXCEPTION 'This member is banned. A ban is lifted only by approving their unban request.'
      USING ERRCODE = '42501';
  END IF;
  UPDATE community_members SET status = _status
  WHERE community_id = _community_id AND user_id = _user_id;

  PERFORM _record_audit(
    'community.member.' || _status,
    'community_member',
    _user_id::text,
    jsonb_build_object('community_id', _community_id, 'reason', _reason)
  );
END;
$$;


ALTER FUNCTION "public"."community_set_member_status"("_community_id" "uuid", "_user_id" "uuid", "_status" "text", "_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_slugify"("_input" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT trim(both '-' from
    regexp_replace(
      regexp_replace(lower(coalesce(_input, '')), '[^a-z0-9]+', '-', 'g'),
      '-+', '-', 'g'
    )
  );
$$;


ALTER FUNCTION "public"."community_slugify"("_input" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_vote"("_poll_id" "uuid", "_option_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _multi boolean; _closes_at timestamptz;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Must be signed in'; END IF;
  SELECT multi, closes_at INTO _multi, _closes_at FROM community_polls WHERE id = _poll_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Poll not found'; END IF;
  IF _closes_at IS NOT NULL AND _closes_at < now() THEN
    RAISE EXCEPTION 'Poll closed';
  END IF;

  IF NOT _multi THEN
    DELETE FROM community_poll_votes WHERE poll_id = _poll_id AND user_id = auth.uid();
  END IF;

  INSERT INTO community_poll_votes (poll_id, user_id, option_id)
  VALUES (_poll_id, auth.uid(), _option_id)
  ON CONFLICT DO NOTHING;
END;
$$;


ALTER FUNCTION "public"."community_vote"("_poll_id" "uuid", "_option_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."company_candidates"("_name" "text" DEFAULT NULL::"text", "_website" "text" DEFAULT NULL::"text", "_email" "text" DEFAULT NULL::"text") RETURNS TABLE("company_id" "uuid", "name" "text", "website" "text", "verification_status" "text", "reasons" "text"[])
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _domain text := public.norm_website_domain(_website);
  _mail   text := public.email_domain(_email);
  _key    text := public.company_name_key(_name);
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sign in to look companies up' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  WITH hits AS (
    SELECT d.company_id AS cid, 'website_domain'::text AS why FROM company_domains d WHERE _domain IS NOT NULL AND d.domain = _domain
    UNION ALL
    SELECT d.company_id, 'email_domain' FROM company_domains d
     WHERE _mail IS NOT NULL AND d.domain = _mail
       AND NOT EXISTS (SELECT 1 FROM personal_email_domains x WHERE x.domain = _mail)
    UNION ALL
    SELECT c.id, 'name' FROM companies c WHERE _key <> '' AND c.name_key = _key
    UNION ALL
    SELECT a.company_id, 'alias' FROM company_aliases a WHERE _key <> '' AND a.alias_key = _key
  )
  SELECT c.id, c.name, c.website, c.verification_status, ARRAY_AGG(DISTINCT h.why ORDER BY h.why)
    FROM hits h JOIN companies c ON c.id = h.cid
   WHERE c.verification_status <> 'rejected' AND c.merged_into IS NULL
   GROUP BY c.id
   ORDER BY bool_or(h.why IN ('website_domain','email_domain')) DESC, (c.verification_status = 'verified') DESC, c.name
   LIMIT 25;
END;
$$;


ALTER FUNCTION "public"."company_candidates"("_name" "text", "_website" "text", "_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."company_name_key"("_raw" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $$
DECLARE
  _k        text;
  _s        text;
  _stripped boolean := true;
  _suffixes text[] := ARRAY['private limited','incorporated','corporation','limited','company','pvt ltd',
                            'sarl','gmbh','pvt','ltd','llp','llc','inc','corp','plc','pte','pty','srl','spa',
                            'co','ag','sa','bv','nv','oy','ab','as','kk'];
BEGIN
  _k := btrim(regexp_replace(
          regexp_replace(replace(public.fold_text(_raw), '&', ' and '), '[.''’`]', '', 'g'),
          '[!-/:-@\[-`{-~\u00A0-\u00BF\u2010-\u2027\u2030-\u205E\s]+', ' ', 'g'));
  WHILE _stripped LOOP
    _stripped := false;
    FOREACH _s IN ARRAY _suffixes LOOP
      IF right(_k, length(_s) + 1) = ' ' || _s AND length(_k) > length(_s) + 1 THEN
        _k := btrim(left(_k, length(_k) - length(_s) - 1));
        _stripped := true;
        EXIT;
      END IF;
    END LOOP;
  END LOOP;
  RETURN regexp_replace(_k, '^the ', '');
END;
$$;


ALTER FUNCTION "public"."company_name_key"("_raw" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_org_invitation"("_invitation_id" "uuid", "_user_id" "uuid", "_new_account" boolean DEFAULT false) RETURNS TABLE("accepted_org_id" "uuid", "assigned_role" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  inv     record;
  _email  text;
  _role   text;
BEGIN
  SELECT i.id, i.org_id, i.email, i.role, i.status, i.expires_at
    INTO inv
    FROM public.org_invitations i
   WHERE i.id = _invitation_id
   FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'invitation_not_found'; END IF;
  IF inv.status <> 'pending' THEN RAISE EXCEPTION 'invitation_not_pending'; END IF;
  IF inv.expires_at <= now() THEN RAISE EXCEPTION 'invitation_expired'; END IF;

  SELECT lower(u.email) INTO _email FROM auth.users u WHERE u.id = _user_id;
  IF _email IS NULL OR _email <> lower(inv.email) THEN
    RAISE EXCEPTION 'email_mismatch';
  END IF;

  INSERT INTO public.org_members (org_id, user_id, role)
       VALUES (inv.org_id, _user_id, inv.role)
  ON CONFLICT (org_id, user_id) DO NOTHING;

  SELECT m.role INTO _role
    FROM public.org_members m
   WHERE m.org_id = inv.org_id AND m.user_id = _user_id;

  UPDATE public.org_invitations
     SET status      = 'accepted',
         accepted_at = now(),
         accepted_by = _user_id,
         claimed_at  = NULL,
         updated_at  = now()
   WHERE id = inv.id;

  IF _new_account THEN
    UPDATE public.profiles SET profile_completed = true WHERE user_id = _user_id;
  END IF;

  accepted_org_id := inv.org_id;
  assigned_role   := _role;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."complete_org_invitation"("_invitation_id" "uuid", "_user_id" "uuid", "_new_account" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."complete_org_invitation"("_invitation_id" "uuid", "_user_id" "uuid", "_new_account" boolean) IS 'Adds the invited user to the workspace with the invitation''s role and marks the invitation accepted, in one transaction. service_role only (team-invitation edge function).';



CREATE OR REPLACE FUNCTION "public"."create_my_workspace"("_name" "text", "_slug" "text", "_subdomain" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid   uuid := auth.uid();
  _email text;
  _org   uuid;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Sign in to create a workspace' USING ERRCODE = '42501';
  END IF;
  IF _name IS NULL OR btrim(_name) = '' THEN
    RAISE EXCEPTION 'Enter a workspace name' USING ERRCODE = '22023';
  END IF;
  IF _slug IS NULL OR btrim(_slug) = '' THEN
    RAISE EXCEPTION 'Missing workspace slug' USING ERRCODE = '22023';
  END IF;

  SELECT public._auth_user_email() INTO _email;

  INSERT INTO public.organizations (name, slug, subdomain, owner_id, plan, billing_email)
  VALUES (btrim(_name), _slug, NULLIF(btrim(COALESCE(_subdomain, '')), ''), _uid, 'free', _email)
  RETURNING id INTO _org;

  INSERT INTO public.org_members (org_id, user_id, role)
  VALUES (_org, _uid, 'owner')
  ON CONFLICT (org_id, user_id) DO UPDATE SET role = 'owner';

  INSERT INTO public.subscriptions (org_id, plan, status)
  VALUES (_org, 'free', 'active')
  ON CONFLICT (org_id) DO NOTHING;

  RETURN _org;
END;
$$;


ALTER FUNCTION "public"."create_my_workspace"("_name" "text", "_slug" "text", "_subdomain" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_my_workspace"("_name" "text", "_slug" "text", "_subdomain" "text") IS 'Onboarding: creates the caller''s organisation, their owner membership and the Free subscription in one transaction. Runs as the caller, so row security and the plan guard apply.';



CREATE OR REPLACE FUNCTION "public"."create_provisional_company"("_name" "text", "_website" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid    uuid := auth.uid();
  _domain text := public.norm_website_domain(_website);
  _id     uuid;
BEGIN
  IF NOT public._is_organiser(_uid) THEN
    RAISE EXCEPTION 'Only organisers can add companies' USING ERRCODE = '42501';
  END IF;
  IF public.company_name_key(_name) = '' THEN
    RAISE EXCEPTION 'Enter a company name' USING ERRCODE = '22023';
  END IF;
  IF _domain IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('company_domain:' || _domain, 0));
    SELECT company_id INTO _id FROM company_domains WHERE domain = _domain;
    IF _id IS NOT NULL THEN RETURN _id; END IF;
  END IF;
  INSERT INTO companies (name, name_key, website, source, created_by)
  VALUES (public.norm_text(_name), public.company_name_key(_name),
          CASE WHEN _domain IS NOT NULL THEN 'https://' || _domain END, 'user_entered', _uid)
  RETURNING id INTO _id;
  IF _domain IS NOT NULL THEN
    INSERT INTO company_domains (company_id, domain, kind) VALUES (_id, _domain, 'website');
  END IF;
  INSERT INTO audit_logs (actor_id, action, target_type, target_id, details)
  VALUES (_uid, 'company.created_provisional', 'company', _id::text, jsonb_build_object('name', _name, 'domain', _domain));
  RETURN _id;
END;
$$;


ALTER FUNCTION "public"."create_provisional_company"("_name" "text", "_website" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_vendor_business"("p_business_name" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  uid            uuid := auth.uid();
  new_vendor_id  uuid;
  v_venue_cat_id uuid;
  _caller_email  text;
begin
  if uid is null then
    raise exception 'Not authenticated';
  end if;

  if p_business_name is null or length(trim(p_business_name)) < 2 then
    raise exception 'Business name is required';
  end if;

  if exists (select 1 from public.vendor_members where user_id = uid) then
    raise exception 'You already belong to a vendor business';
  end if;

  -- ── ALLOWLIST GATE (migration 105) ──
  select lower(email) into _caller_email
    from auth.users
   where id = uid;
  if not exists (
    select 1 from public.vendor_email_allowlist a
    where lower(a.email) = _caller_email
  ) then
    raise exception
      'Vendor portal access is invite-only. Contact support if you should have access.'
      using errcode = '42501';
  end if;

  insert into public.vendors (business_name)
  values (trim(p_business_name))
  returning id into new_vendor_id;

  insert into public.vendor_members (vendor_id, user_id, role)
  values (new_vendor_id, uid, 'owner');

  select id into v_venue_cat_id
    from public.vendor_categories
   where slug = 'venue';
  if v_venue_cat_id is not null then
    insert into public.vendor_category_map (vendor_id, category_id)
    values (new_vendor_id, v_venue_cat_id)
    on conflict do nothing;
  end if;

  return new_vendor_id;
end;
$$;


ALTER FUNCTION "public"."create_vendor_business"("p_business_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_utm_tracking"("_event_id" "uuid", "_utm_source" "text", "_utm_medium" "text", "_utm_campaign" "text", "_utm_content" "text" DEFAULT NULL::"text", "_utm_term" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_content  text := NULLIF(btrim(_utm_content), '');
  v_term     text := NULLIF(btrim(_utm_term), '');
  v_links    int := 0;
  v_clicks   int := 0;
  v_regs     int := 0;
  v_partners int := 0;
  r          record;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.events e
    WHERE e.id = _event_id
      AND (
        e.user_id = auth.uid()
        OR public.has_role(auth.uid(), 'admin')
        OR public.is_org_member(auth.uid(), e.org_id)
      )
  ) THEN
    RAISE EXCEPTION 'Not authorised' USING ERRCODE = '42501';
  END IF;

  IF coalesce(trim(_utm_source), '') IN ('', '(direct)') THEN
    RAISE EXCEPTION 'Direct traffic is not a tracked link' USING ERRCODE = '22023';
  END IF;

  DELETE FROM public.utm_links l
   WHERE l.event_id     = _event_id
     AND l.utm_source   = _utm_source
     AND l.utm_medium   = _utm_medium
     AND l.utm_campaign = _utm_campaign
     AND l.utm_content IS NOT DISTINCT FROM v_content
     AND l.utm_term    IS NOT DISTINCT FROM v_term;
  GET DIAGNOSTICS v_links = ROW_COUNT;

  DELETE FROM public.utm_clicks c
   WHERE c.event_id   = _event_id
     AND c.utm_source = _utm_source
     AND coalesce(c.utm_medium,   '(none)') = coalesce(_utm_medium,   '(none)')
     AND coalesce(c.utm_campaign, '(none)') = coalesce(_utm_campaign, '(none)')
     AND NULLIF(btrim(c.utm_content), '') IS NOT DISTINCT FROM v_content
     AND NULLIF(btrim(c.utm_term), '')    IS NOT DISTINCT FROM v_term;
  GET DIAGNOSTICS v_clicks = ROW_COUNT;

  -- Shares cover the whole campaign: end them only when its last saved link goes.
  IF NOT EXISTS (
    SELECT 1 FROM public.utm_links l
     WHERE l.event_id     = _event_id
       AND l.utm_source   = _utm_source
       AND l.utm_medium   = _utm_medium
       AND l.utm_campaign = _utm_campaign
  ) THEN
    FOR r IN
      DELETE FROM public.utm_partner_access a
       WHERE a.event_id     = _event_id
         AND a.utm_source   = _utm_source
         AND a.utm_medium   = coalesce(_utm_medium,   '(none)')
         AND a.utm_campaign = coalesce(_utm_campaign, '(none)')
      RETURNING a.id, a.invited_email, a.status
    LOOP
      v_partners := v_partners + 1;
      PERFORM public._utm_partner_audit('utm_partner.removed', r.id,
        jsonb_build_object('email', r.invited_email, 'previous_status', r.status, 'reason', 'link deleted'));
    END LOOP;
  END IF;

  SELECT count(*) INTO v_regs
    FROM public.registrations r2
   WHERE r2.event_id   = _event_id
     AND r2.status    <> 'cancelled'
     AND r2.utm_source = _utm_source
     AND coalesce(r2.utm_medium,   '(none)') = coalesce(_utm_medium,   '(none)')
     AND coalesce(r2.utm_campaign, '(none)') = coalesce(_utm_campaign, '(none)')
     AND NULLIF(btrim(r2.utm_content), '') IS NOT DISTINCT FROM v_content
     AND NULLIF(btrim(r2.utm_term), '')    IS NOT DISTINCT FROM v_term;

  RETURN jsonb_build_object(
    'links_deleted',      v_links,
    'clicks_deleted',     v_clicks,
    'registrations_kept', v_regs,
    'partners_removed',   v_partners
  );
END;
$$;


ALTER FUNCTION "public"."delete_utm_tracking"("_event_id" "uuid", "_utm_source" "text", "_utm_medium" "text", "_utm_campaign" "text", "_utm_content" "text", "_utm_term" "text") OWNER TO "postgres";


