CREATE OR REPLACE FUNCTION "public"."enforce_instant_book_verification"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_status text;
BEGIN
  IF NEW.is_instant_book = true THEN
    SELECT verification_status INTO v_status
    FROM vendors WHERE id = NEW.vendor_id;

    IF v_status != 'verified' THEN
      RAISE EXCEPTION 'Only verified vendors can enable instant booking';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_instant_book_verification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_plan_feature"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _feature text := TG_ARGV[0];
  _row     jsonb := to_jsonb(NEW);
  _org     uuid;
BEGIN
  IF auth.uid() IS NULL OR public.has_role(auth.uid(), 'admin') THEN
    RETURN NEW;
  END IF;
  IF _row ? 'org_id' AND NULLIF(_row ->> 'org_id', '') IS NOT NULL THEN
    _org := (_row ->> 'org_id')::uuid;
  ELSIF _row ? 'event_id' AND NULLIF(_row ->> 'event_id', '') IS NOT NULL THEN
    SELECT e.org_id INTO _org FROM public.events e WHERE e.id = (_row ->> 'event_id')::uuid;
  END IF;
  IF _org IS NULL THEN
    RETURN NEW;
  END IF;
  IF NOT public.org_has_feature(_org, _feature) THEN
    RAISE EXCEPTION 'Your plan does not include this feature (%). Ask us to upgrade your plan.', _feature
      USING ERRCODE = 'P0001', HINT = 'plan_feature:' || _feature;
  END IF;
  RETURN NEW;
END; $$;


ALTER FUNCTION "public"."enforce_plan_feature"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_quote_limits"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_status text;
  v_active_count int;
  v_limit int;
BEGIN
  IF NEW.status IN ('draft', 'sent') THEN
    SELECT verification_status INTO v_status
    FROM vendors WHERE id = NEW.vendor_id;

    -- Set limit based on verification
    v_limit := CASE v_status
      WHEN 'verified' THEN 50
      WHEN 'pending' THEN 10
      ELSE 5
    END;

    -- Count active quotes
    SELECT COUNT(*) INTO v_active_count
    FROM quotes
    WHERE vendor_id = NEW.vendor_id
      AND status IN ('draft', 'sent')
      AND id != NEW.id;

    IF v_active_count >= v_limit THEN
      RAISE EXCEPTION 'Active quote limit reached (% for % vendors)', v_limit, v_status;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_quote_limits"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_vendor_email_allowlist"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  _email text;
begin
  select lower(email) into _email
    from auth.users
   where id = new.user_id;

  if _email is null then
    raise exception
      'Cannot create vendor_members row: auth user % not found.', new.user_id
      using errcode = '23503';  -- foreign_key_violation-flavored
  end if;

  if not exists (
    select 1 from public.vendor_email_allowlist a
    where lower(a.email) = _email
  ) then
    raise exception
      'Vendor portal access is invite-only. Email % is not on the allowlist. '
      'Add it via INSERT INTO public.vendor_email_allowlist (email) VALUES (...) if intentional.',
      _email
      using errcode = '42501';  -- insufficient_privilege
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_vendor_email_allowlist"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_vendor_email_allowlist"() IS 'BEFORE INSERT trigger on vendor_members: rejects any row whose user_id resolves to an auth.users email not present in vendor_email_allowlist.';



CREATE OR REPLACE FUNCTION "public"."ensure_contact_person"("_email" "text", "_name" "text" DEFAULT NULL::"text", "_phone_cc" "text" DEFAULT NULL::"text", "_phone" "text" DEFAULT NULL::"text", "_linkedin" "text" DEFAULT NULL::"text", "_company" "text" DEFAULT NULL::"text", "_company_id" "uuid" DEFAULT NULL::"uuid", "_designation" "text" DEFAULT NULL::"text", "_source" "text" DEFAULT 'unknown'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _key      text := public.norm_email(_email);
  _person   uuid;
  _created  boolean := false;
  _e164     text := public.norm_phone(_phone_cc, _phone);
  _li       text := public.linkedin_key(_linkedin);
  _other    uuid;
BEGIN
  IF _key IS NULL THEN RETURN NULL; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('person_email:' || _key, 0));

  SELECT person_id INTO _person FROM person_emails WHERE email_key = _key;
  IF _person IS NULL THEN
    INSERT INTO people (display_name, name_key, created_via)
    VALUES (NULLIF(public.norm_text(_name), ''), public.person_name_key(_name),
            CASE WHEN _source IN ('signup','registration','speaker','sponsor_contact','import','manual','backfill')
                 THEN _source ELSE 'unknown' END)
    RETURNING id INTO _person;
    INSERT INTO person_emails (person_id, email, email_key, source)
    VALUES (_person, public.norm_text(_email), _key, _source);
    _created := true;
  END IF;

  IF _e164 IS NOT NULL THEN
    INSERT INTO person_phones (person_id, country_code, number, phone_e164, source)
    VALUES (_person, NULLIF(public.norm_text(_phone_cc), ''), public.norm_text(_phone), _e164, _source)
    ON CONFLICT (person_id, phone_e164) DO NOTHING;
    FOR _other IN SELECT DISTINCT pp.person_id FROM person_phones pp WHERE pp.phone_e164 = _e164 AND pp.person_id <> _person LOOP
      PERFORM public._queue_identity_candidate(_person, _other, 'phone');
    END LOOP;
  END IF;

  IF _li IS NOT NULL THEN
    INSERT INTO person_links (person_id, kind, url, url_key)
    VALUES (_person, 'linkedin', public.norm_text(_linkedin), _li)
    ON CONFLICT (person_id, kind, url_key) DO NOTHING;
    FOR _other IN SELECT DISTINCT pl.person_id FROM person_links pl
                   WHERE pl.kind = 'linkedin' AND pl.url_key = _li AND pl.person_id <> _person LOOP
      PERFORM public._queue_identity_candidate(_person, _other, 'linkedin');
    END LOOP;
  END IF;

  IF _company_id IS NOT NULL THEN
    INSERT INTO person_company_affiliations (person_id, company_id, designation, designation_key, source)
    VALUES (_person, _company_id, NULLIF(public.norm_text(_designation), ''), lower(public.norm_text(_designation)), _source)
    ON CONFLICT (person_id, company_id, designation_key) DO NOTHING;
  END IF;

  -- A new contact with the same name at the same company as someone else.
  IF _created AND public.person_name_key(_name) <> '' AND public.company_name_key(_company) <> '' THEN
    FOR _other IN
      SELECT DISTINCT p.id
        FROM people p
        JOIN registrations r ON r.person_id = p.id
       WHERE p.id <> _person
         AND p.name_key = public.person_name_key(_name)
         AND public.company_name_key(r.company) = public.company_name_key(_company)
       LIMIT 20
    LOOP
      PERFORM public._queue_identity_candidate(_person, _other, 'name_company');
    END LOOP;
  END IF;

  RETURN _person;
END;
$$;


ALTER FUNCTION "public"."ensure_contact_person"("_email" "text", "_name" "text", "_phone_cc" "text", "_phone" "text", "_linkedin" "text", "_company" "text", "_company_id" "uuid", "_designation" "text", "_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_event_community"("_event_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _existing uuid;
  _evt RECORD;
  _parent_id uuid;
  _new_id uuid;
  _slug text;
  _base_slug text;
  _i int := 0;
BEGIN
  SELECT id INTO _existing FROM communities WHERE event_id = _event_id LIMIT 1;
  IF _existing IS NOT NULL THEN RETURN _existing; END IF;

  SELECT e.id, e.title, e.slug, e.org_id, e.user_id,
         COALESCE(e.community_category, 'other')::text AS category_text
    INTO _evt
  FROM events e WHERE e.id = _event_id;
  IF NOT FOUND THEN RETURN NULL; END IF;

  _parent_id := ensure_parent_community(_map_event_category_to_community(_evt.category_text));

  _base_slug := community_slugify(_evt.slug || '-community');
  IF _base_slug IS NULL OR _base_slug = '' THEN _base_slug := 'event-' || _evt.id::text; END IF;
  _slug := _base_slug;
  WHILE EXISTS (SELECT 1 FROM communities WHERE slug = _slug) LOOP
    _i := _i + 1;
    _slug := _base_slug || '-' || _i;
  END LOOP;

  INSERT INTO communities (
    kind, parent_id, event_id, org_id, slug, name, description, visibility, created_by
  ) VALUES (
    'event', _parent_id, _evt.id, _evt.org_id, _slug,
    _evt.title || ' — Community',
    'Discussion space for attendees, speakers and sponsors of ' || _evt.title || '.',
    'public', -- This makes it discoverable!
    _evt.user_id
  ) RETURNING id INTO _new_id;

  INSERT INTO community_members (community_id, user_id, role, status, auto)
  VALUES (_new_id, _evt.user_id, 'manager', 'active', true)
  ON CONFLICT (community_id, user_id) DO NOTHING;

  UPDATE communities SET member_count = member_count + 1 WHERE id = _new_id;

  RETURN _new_id;
END;
$$;


ALTER FUNCTION "public"."ensure_event_community"("_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_parent_community"("_category" "public"."community_category") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _id uuid;
  _name text;
  _slug text;
BEGIN
  SELECT id INTO _id FROM communities WHERE kind='parent' AND category=_category LIMIT 1;
  IF _id IS NOT NULL THEN RETURN _id; END IF;

  _name := initcap(replace(_category::text, '_', ' ')) || ' Community';
  _slug := community_slugify(_name);

  INSERT INTO communities (kind, category, slug, name, description, visibility, created_by)
  VALUES ('parent', _category, _slug,
          _name,
          'Industry hub for ' || lower(replace(_category::text,'_',' ')) || ' events and discussions.',
          'public',
          NULL)
  RETURNING id INTO _id;
  RETURN _id;
END;
$$;


ALTER FUNCTION "public"."ensure_parent_community"("_category" "public"."community_category") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."event_attendance_audit"("_event_id" "uuid", "_limit" integer DEFAULT 200) RETURNS TABLE("id" "uuid", "actor_email" "text", "action" "text", "target_id" "uuid", "details" "jsonb", "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    ae.id,
    u.email                             AS actor_email,
    CASE ae.kind
      WHEN 'in'       THEN 'attendance.check_in'
      WHEN 'out'      THEN 'attendance.check_out'
      WHEN 'auto_out' THEN 'attendance.auto_check_out'
      ELSE 'attendance.' || ae.kind
    END                                 AS action,
    ae.registration_id                  AS target_id,
    jsonb_strip_nulls(jsonb_build_object(
      'method',            ae.method,
      'registration_name', COALESCE(NULLIF(r.name, ''), r.email),
      'ticket_type',       r.ticket_type,
      'event_day',         ae.event_day
    ))                                  AS details,
    ae.occurred_at                      AS created_at
  FROM public.attendance_events ae
  LEFT JOIN public.registrations r ON r.id = ae.registration_id
  LEFT JOIN auth.users u           ON u.id = ae.actor_id
  WHERE ae.event_id = _event_id
    AND (
      -- Event owner OR platform admin can read everything for this event.
      EXISTS (SELECT 1 FROM public.events e WHERE e.id = _event_id AND e.user_id = auth.uid())
      OR public.has_role(auth.uid(), 'admin'::public.app_role)
    )
  ORDER BY ae.occurred_at DESC
  LIMIT LEAST(GREATEST(COALESCE(_limit, 200), 1), 1000);
$$;


