CREATE OR REPLACE FUNCTION "public"."event_meeting_interests"("_eid" "uuid") RETURNS TABLE("registration_id" "uuid", "speaker_id" "uuid", "speaker_email" "text", "sponsor_id" "uuid", "sponsor_name" "text", "created_at" timestamp with time zone, "status" "text", "scheduled_at" timestamp with time zone, "location" "text", "met_at" timestamp with time zone, "status_reason" "text", "note" "text", "status_by_side" "text", "status_changed_at" timestamp with time zone, "status_cause" "text", "ever_progressed" boolean, "outcome_at" timestamp with time zone, "dispute_status" "text", "dispute_reason" "text", "dispute_requested_status" "text", "disputed_at" timestamp with time zone, "dispute_resolution" "text", "dispute_note" "text", "resolved_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT smi.registration_id, smi.speaker_id, lower(NULLIF(sp.email, '')), smi.sponsor_id, s.name, smi.created_at,
         smi.status, smi.scheduled_at, smi.location, smi.met_at, smi.status_reason, smi.note,
         smi.status_by_side, smi.status_changed_at,
         smi.status_cause, smi.ever_progressed, smi.outcome_at,
         smi.dispute_status, smi.dispute_reason, smi.dispute_requested_status, smi.disputed_at,
         smi.dispute_resolution, smi.dispute_note, smi.resolved_at
    FROM sponsor_meeting_interests smi
    JOIN sponsors s ON s.id = smi.sponsor_id
    LEFT JOIN speakers sp ON sp.id = smi.speaker_id
   WHERE smi.event_id = _eid AND public._can_view_event_registrations(_eid)
   ORDER BY s.name, smi.created_at;
$$;


