    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.tier IS NULL THEN
    SELECT s.tier, s.tier_label INTO NEW.tier, NEW.tier_label FROM sponsors s WHERE s.id = NEW.sponsor_id;
  END IF;
  RETURN NEW;
END;
$$;


