    AS $$
  SELECT d.virtual_url FROM public.event_private_details d
   WHERE d.event_id = _event_id
     AND auth.uid() IS NOT NULL
     AND (public._can_manage_event(auth.uid(), _event_id)
          OR public.is_event_approved_attendee(auth.uid(), _event_id)
          OR public.is_event_speaker(auth.uid(), _event_id));
$$;


ALTER FUNCTION "public"."get_event_join_url"("_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_event_og"("_event_slug" "text" DEFAULT NULL::"text", "_org_slug" "text" DEFAULT NULL::"text", "_event_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "title" "text", "description" "text", "date" timestamp with time zone, "end_date" timestamp with time zone, "venue" "text", "location" "text", "banner_landscape_url" "text", "image_url" "text", "slug" "text", "timezone" "text", "event_format" "text", "status" "text", "price" numeric, "currency" "text", "virtual_url" "text", "org_id" "uuid", "org_name" "text", "org_slug" "text", "org_subdomain" "text", "org_logo_url" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    e.id,
    e.title,
    e.description,
    e.date,
    e.end_date,
    e.venue,
    e.location,
    e.banner_landscape_url,
    e.image_url,
    e.slug,
    e.timezone,
    e.event_format,
    e.status,
    e.price,
    e.currency,
    e.virtual_url,
    o.id          AS org_id,
    o.name        AS org_name,
    o.slug        AS org_slug,
    o.subdomain   AS org_subdomain,
    o.logo_url    AS org_logo_url
    FROM public.events e
    LEFT JOIN public.organizations o ON o.id = e.org_id
   WHERE e.status = 'published'
     AND (
          (_event_id IS NOT NULL AND e.id = _event_id)
       OR (
            _event_id IS NULL
            AND _event_slug IS NOT NULL
            AND e.slug = _event_slug
            AND (
                 _org_slug IS NULL
              OR o.slug      = _org_slug
              OR o.subdomain = _org_slug
            )
          )
        )
   ORDER BY e.created_at DESC NULLS LAST
   LIMIT 1;
$$;


ALTER FUNCTION "public"."get_event_og"("_event_slug" "text", "_org_slug" "text", "_event_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_event_og"("_event_slug" "text", "_org_slug" "text", "_event_id" "uuid") IS 'Public-safe lookup for per-event share previews. Returns one row containing the event + org identity fields needed to render an OG card. Only published events are ever returned. Callable by anon.';



CREATE OR REPLACE FUNCTION "public"."get_marketplace_vendors"("p_category_slug" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_min_rating" numeric DEFAULT NULL::numeric, "p_limit" integer DEFAULT 24, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "business_name" "text", "tagline" "text", "city" "text", "country" "text", "logo_url" "text", "cover_url" "text", "rating_avg" numeric, "rating_count" integer, "default_currency" "text", "verification_status" "text", "response_time_hours" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    v.id, v.business_name, v.tagline, v.city, v.country,
    v.logo_url, v.cover_url, v.rating_avg, v.rating_count,
    v.default_currency, v.verification_status, v.response_time_hours
  FROM public.vendors v
  LEFT JOIN public.vendor_category_map m ON m.vendor_id = v.id
  LEFT JOIN public.vendor_categories   c ON c.id        = m.category_id
  WHERE (p_category_slug IS NULL OR c.slug = p_category_slug)
    AND (p_city          IS NULL OR v.city ILIKE '%' || p_city || '%')
    AND (p_min_rating    IS NULL OR COALESCE(v.rating_avg, 0) >= p_min_rating)
  GROUP BY v.id
  ORDER BY (v.verification_status = 'verified') DESC,
           COALESCE(v.rating_avg, 0) DESC,
           v.rating_count DESC
  LIMIT  GREATEST(1, LEAST(p_limit, 100))
  OFFSET GREATEST(0, p_offset);
$$;


ALTER FUNCTION "public"."get_marketplace_vendors"("p_category_slug" "text", "p_city" "text", "p_min_rating" numeric, "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


