CREATE OR REPLACE FUNCTION "public"."get_webinar_analytics"("_sid" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _eid uuid; _r jsonb;
BEGIN SELECT event_id INTO _eid FROM webinar_sessions WHERE id=_sid; IF _eid IS NULL THEN RAISE EXCEPTION 'Not found'; END IF;
  IF NOT is_event_owner(auth.uid(),_eid) THEN RAISE EXCEPTION 'Forbidden'; END IF;
  WITH a AS(SELECT * FROM webinar_attendance WHERE session_id=_sid),
  k AS(SELECT(SELECT viewer_peak FROM webinar_sessions WHERE id=_sid) pk,COUNT(DISTINCT identity) uv,COALESCE(AVG(EXTRACT(EPOCH FROM(COALESCE(left_at,now())-joined_at))/60),0) aw,(SELECT count(*) FROM webinar_chat WHERE session_id=_sid AND deleted=false) cc,(SELECT count(*) FROM webinar_qa WHERE session_id=_sid) qc,(SELECT count(*) FROM webinar_polls WHERE session_id=_sid) pc,(SELECT count(*) FROM webinar_reactions WHERE session_id=_sid) rc,(SELECT count(*) FROM webinar_announcements WHERE session_id=_sid) ac FROM a),
  ta AS(SELECT a.identity,COALESCE(p.display_name,a.display_name,'Guest') n,ROUND(SUM(EXTRACT(EPOCH FROM(COALESCE(a.left_at,now())-a.joined_at))/60)::numeric,1) m FROM a LEFT JOIN profiles p ON p.user_id=a.user_id GROUP BY a.identity,p.display_name,a.display_name ORDER BY m DESC LIMIT 50)
  SELECT jsonb_build_object('kpis',(SELECT to_jsonb(k) FROM k),'top_attendees',COALESCE((SELECT jsonb_agg(to_jsonb(ta)) FROM ta),'[]')) INTO _r;
  RETURN _r;
END; $$;


ALTER FUNCTION "public"."get_webinar_analytics"("_sid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_community_member_ban"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF OLD.status = 'banned' AND NEW.status IS DISTINCT FROM 'banned'
     AND COALESCE(current_setting('illuxus.unban_approved', true), '') <> 'on' THEN
    IF current_user IN ('authenticated', 'anon') THEN
      RAISE EXCEPTION 'A ban is lifted only by approving the member''s unban request'
        USING ERRCODE = '42501';
    END IF;
    -- Server paths that re-add people (event registration auto-join) keep
    -- the ban in place rather than failing the whole operation.
    NEW.status := OLD.status;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_community_member_ban"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_org_plan_columns"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _free public.plans%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR public.has_role(auth.uid(), 'admin') THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    SELECT * INTO _free FROM public.plans WHERE key = 'free';
    NEW.plan := 'free';
    NEW.addons := '{}';
    NEW.feature_overrides := '{}'::jsonb;
    IF FOUND THEN
      NEW.plan_limits := _free.limits || jsonb_build_object('features', to_jsonb(_free.features));
    END IF;
  ELSE
    NEW.plan := OLD.plan;
    NEW.plan_limits := OLD.plan_limits;
    NEW.addons := OLD.addons;
    NEW.feature_overrides := OLD.feature_overrides;
  END IF;
  RETURN NEW;
END; $$;


ALTER FUNCTION "public"."guard_org_plan_columns"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_profile_ban_columns"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.banned_at IS DISTINCT FROM OLD.banned_at
     OR NEW.banned_reason IS DISTINCT FROM OLD.banned_reason THEN
    -- Not SECURITY DEFINER: current_user is the caller's role, so a direct
    -- API update ('authenticated') is told apart from the admin functions.
    IF current_user IN ('authenticated', 'anon') THEN
      RAISE EXCEPTION 'Only a platform admin can change a ban' USING ERRCODE = '42501';
    END IF;
    IF OLD.banned_at IS NOT NULL AND NEW.banned_at IS NULL
       AND COALESCE(current_setting('illuxus.unban_approved', true), '') <> 'on' THEN
      RAISE EXCEPTION 'A ban is lifted only by approving the user''s unban request'
        USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_profile_ban_columns"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_subscription_plan"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR public.has_role(auth.uid(), 'admin') THEN
    RETURN NEW;
  END IF;
  SELECT o.plan INTO NEW.plan FROM public.organizations o WHERE o.id = NEW.org_id;
  NEW.plan := COALESCE(NEW.plan, 'free');
  RETURN NEW;
END; $$;


ALTER FUNCTION "public"."guard_subscription_plan"() OWNER TO "postgres";


