     AND public._caller_may_look_up(_user_id);
$$;


ALTER FUNCTION "public"."has_role"("_user_id" "uuid", "_role" "public"."app_role") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."identity_candidates"("_email" "text" DEFAULT NULL::"text", "_phone_cc" "text" DEFAULT NULL::"text", "_phone" "text" DEFAULT NULL::"text", "_linkedin" "text" DEFAULT NULL::"text", "_name" "text" DEFAULT NULL::"text", "_company" "text" DEFAULT NULL::"text") RETURNS TABLE("person_id" "uuid", "reasons" "text"[], "has_account" boolean, "visible" boolean, "display_name" "text", "email_hint" "text", "company" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid  uuid := auth.uid();
  _key  text := public.norm_email(_email);
  _e164 text := public.norm_phone(_phone_cc, _phone);
  _li   text := public.linkedin_key(_linkedin);
  _nk   text := public.person_name_key(_name);
  _ck   text := public.company_name_key(_company);
BEGIN
  IF NOT public._is_organiser(_uid) THEN
    RAISE EXCEPTION 'Only organisers can look people up' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH hits AS (
    SELECT pe.person_id AS pid, 'email'::text AS why FROM person_emails pe WHERE _key IS NOT NULL AND pe.email_key = _key
    UNION ALL
    SELECT pp.person_id, 'phone' FROM person_phones pp WHERE _e164 IS NOT NULL AND pp.phone_e164 = _e164
    UNION ALL
    SELECT pl.person_id, 'linkedin' FROM person_links pl WHERE _li IS NOT NULL AND pl.kind = 'linkedin' AND pl.url_key = _li
    UNION ALL
    SELECT DISTINCT p.id, 'name_company' FROM people p JOIN registrations r ON r.person_id = p.id
     WHERE p.merged_into IS NULL AND _nk <> '' AND _ck <> '' AND p.name_key = _nk AND public.company_name_key(r.company) = _ck
  ), grouped AS (
    SELECT h.pid, ARRAY_AGG(DISTINCT h.why ORDER BY h.why) AS why FROM hits h GROUP BY h.pid LIMIT 25
  ), shown AS (
    SELECT g.pid, g.why, public._person_visible_to(_uid, g.pid) AS ok FROM grouped g
  )
  SELECT s.pid,
         s.why,
         p.user_id IS NOT NULL,
         s.ok,
         CASE WHEN s.ok THEN p.display_name END,
         (SELECT CASE WHEN s.ok THEN pe.email
                      ELSE left(pe.email_key, 1) || '•••@' || split_part(pe.email_key, '@', 2) END
            FROM person_emails pe WHERE pe.person_id = s.pid
           ORDER BY (pe.email_key = _key) DESC NULLS LAST, pe.verified_at IS NULL, pe.created_at LIMIT 1),
         CASE WHEN s.ok THEN
           (SELECT r.company FROM registrations r WHERE r.person_id = s.pid AND r.company IS NOT NULL
             ORDER BY r.created_at DESC LIMIT 1) END
    FROM shown s JOIN people p ON p.id = s.pid
   ORDER BY ('email' = ANY (s.why)) DESC, array_length(s.why, 1) DESC, s.pid;
END;
$$;


ALTER FUNCTION "public"."identity_candidates"("_email" "text", "_phone_cc" "text", "_phone" "text", "_linkedin" "text", "_name" "text", "_company" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."instant_book_service"("p_service_id" "uuid", "p_org_id" "uuid", "p_event_id" "uuid", "p_event_date" "date", "p_actor_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_service vendor_services%ROWTYPE;
  v_vendor vendors%ROWTYPE;
  v_booking_id uuid;
  v_commission bigint;
  v_deposit bigint;
  v_midway bigint;
  v_final bigint;
  v_conflict_count int;
BEGIN
  -- Fetch service
  SELECT * INTO v_service FROM vendor_services WHERE id = p_service_id;
  IF v_service IS NULL THEN
    RAISE EXCEPTION 'Service not found';
  END IF;
  IF NOT v_service.is_instant_book THEN
    RAISE EXCEPTION 'Service does not support instant booking';
  END IF;

  -- Fetch vendor + check verification
  SELECT * INTO v_vendor FROM vendors WHERE id = v_service.vendor_id;
  IF v_vendor.verification_status != 'verified' THEN
    RAISE EXCEPTION 'Vendor must be verified for instant booking';
  END IF;

  -- Hard conflict check: is the date already booked?
  SELECT COUNT(*) INTO v_conflict_count
  FROM vendor_availability
  WHERE vendor_id = v_service.vendor_id
    AND date = p_event_date
    AND status = 'booked';

  IF v_conflict_count > 0 THEN
    RAISE EXCEPTION 'Vendor is already booked on %', p_event_date;
  END IF;

  -- Calculate commission
  v_commission := ROUND(v_service.base_price * (v_vendor.commission_rate / 100));

  -- Milestone split (30/40/30)
  v_deposit := ROUND(v_service.base_price * 0.3);
  v_midway := ROUND(v_service.base_price * 0.4);
  v_final := v_service.base_price - v_deposit - v_midway;

  -- Create booking (status: confirmed for instant-book)
  INSERT INTO vendor_bookings (
    org_id, vendor_id, event_id, total, currency,
    commission_amount, commission_rate, status, deposit_status, event_date
  ) VALUES (
    p_org_id, v_service.vendor_id, p_event_id, v_service.base_price,
    v_service.currency, v_commission, v_vendor.commission_rate,
    'confirmed', 'pending', p_event_date
  ) RETURNING id INTO v_booking_id;

  -- Create milestones
  INSERT INTO booking_milestones (booking_id, label, amount, sort_order, status)
  VALUES
    (v_booking_id, 'Deposit (30%)', v_deposit, 1, 'pending'),
    (v_booking_id, 'Midway Payment (40%)', v_midway, 2, 'pending'),
    (v_booking_id, 'Final Payment (30%)', v_final, 3, 'pending');

  -- Mark date as booked
  INSERT INTO vendor_availability (vendor_id, date, status, booking_id, note)
  VALUES (v_service.vendor_id, p_event_date, 'booked', v_booking_id, 'Instant book')
  ON CONFLICT (vendor_id, date)
  DO UPDATE SET status = 'booked', booking_id = v_booking_id, note = 'Instant book';

  -- Audit log
  INSERT INTO vendor_audit_log (actor_id, action, entity_type, entity_id, metadata)
  VALUES (
    p_actor_id, 'instant_book', 'vendor_bookings', v_booking_id,
    jsonb_build_object(
      'service_id', p_service_id,
      'total', v_service.base_price,
      'commission', v_commission,
      'event_date', p_event_date
    )
  );

  RETURN v_booking_id;
END;
$$;


ALTER FUNCTION "public"."instant_book_service"("p_service_id" "uuid", "p_org_id" "uuid", "p_event_id" "uuid", "p_event_date" "date", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_approve_all_safe"("_entity" "text" DEFAULT NULL::"text", "_kind" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM public._require_super_admin();
  RETURN public.intel_bulk_approve_safe(ARRAY(
    SELECT id FROM correction_suggestions
     WHERE status = 'open' AND safe AND (_entity IS NULL OR entity_type = _entity) AND (_kind IS NULL OR kind = _kind)));
END;
$$;


ALTER FUNCTION "public"."intel_approve_all_safe"("_entity" "text", "_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_audit_history"("_entity" "text" DEFAULT NULL::"text", "_entity_id" "uuid" DEFAULT NULL::"uuid", "_action" "text" DEFAULT NULL::"text", "_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "_limit" integer DEFAULT 25, "_offset" integer DEFAULT 0, "_merge_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _lim integer := LEAST(GREATEST(COALESCE(_limit, 25), 1), 200);
  _off integer := GREATEST(COALESCE(_offset, 0), 0);
BEGIN
  PERFORM public._require_super_admin();
  RETURN (
    WITH ev AS (
      SELECT a.* FROM audit_logs a
       WHERE (a.action LIKE 'intel.%' OR a.action LIKE 'identity.%' OR a.action LIKE 'company.%')
         AND (_entity IS NULL OR a.target_type = _entity)
         AND (_entity_id IS NULL OR a.target_id = _entity_id::text)
         AND (_action IS NULL OR a.action = _action)
         AND (_from IS NULL OR a.created_at >= _from) AND (_to IS NULL OR a.created_at < _to)
    ), evp AS (SELECT * FROM ev ORDER BY ev.created_at DESC, ev.id LIMIT _lim OFFSET _off),
    mo AS (
      SELECT m.* FROM merge_operations m
       WHERE (_entity IS NULL OR m.entity_type = _entity)
         AND (_entity_id IS NULL OR m.survivor_id = _entity_id OR _entity_id = ANY (m.merged_ids))
    )
    SELECT jsonb_build_object(
      'total', (SELECT count(*) FROM ev),
      'events', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', a.id, 'action', a.action, 'target_type', a.target_type, 'target_id', a.target_id,
                  'details', a.details, 'actor_id', a.actor_id,
                  'actor', COALESCE(a.actor_email, (SELECT u.email FROM auth.users u WHERE u.id = a.actor_id)),
                  'created_at', a.created_at) ORDER BY a.created_at DESC, a.id) FROM evp a), '[]'::jsonb),
      'merges_total', (SELECT count(*) FROM mo),
      'merges', COALESCE((SELECT jsonb_agg(row) FROM (
         SELECT jsonb_build_object('id', m.id, 'entity_type', m.entity_type, 'survivor_id', m.survivor_id, 'merged_ids', m.merged_ids,
                  'reason', m.reason, 'created_at', m.created_at, 'reverted_at', m.reverted_at,
                  'survivor', CASE m.entity_type WHEN 'person' THEN (SELECT display_name FROM people WHERE id = m.survivor_id)
                                                  WHEN 'sponsor' THEN (SELECT name FROM sponsors WHERE id = m.survivor_id)
                                                  ELSE (SELECT name FROM companies WHERE id = m.survivor_id) END) row
           FROM mo m ORDER BY m.created_at DESC, m.id LIMIT 10 OFFSET GREATEST(COALESCE(_merge_offset, 0), 0)) x), '[]'::jsonb))
  );
END;
$$;


ALTER FUNCTION "public"."intel_audit_history"("_entity" "text", "_entity_id" "uuid", "_action" "text", "_from" timestamp with time zone, "_to" timestamp with time zone, "_limit" integer, "_offset" integer, "_merge_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_bulk_approve_safe"("_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _id uuid;
  _n  integer := 0;
BEGIN
  PERFORM public._require_super_admin();
  FOR _id IN SELECT id FROM correction_suggestions WHERE id = ANY (_ids) AND status = 'open' AND safe LOOP
    BEGIN
      PERFORM public.intel_review_correction(_id, true, NULL, 'Bulk-approved formatting fix');
      _n := _n + 1;
    EXCEPTION WHEN SQLSTATE '40001' THEN NULL;  -- changed meanwhile: left for individual review
    END;
  END LOOP;
  RETURN _n;
END;
$$;


ALTER FUNCTION "public"."intel_bulk_approve_safe"("_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_combine_all_sponsor_repeats"("_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  c        uuid;
  r        jsonb;
  _merged  integer := 0;
  _skipped jsonb := '[]'::jsonb;
BEGIN
  PERFORM public._require_super_admin();
  FOR c IN SELECT company_id FROM sponsors WHERE company_id IS NOT NULL AND merged_into IS NULL GROUP BY company_id HAVING count(*) > 1 LOOP
    r := public.intel_consolidate_company_sponsors(c, COALESCE(_reason, 'Combined repeat sponsor records'));
    _merged := _merged + (r ->> 'merged')::int;
    _skipped := _skipped || (r -> 'skipped');
  END LOOP;
  RETURN jsonb_build_object('merged', _merged, 'skipped', _skipped);
END;
$$;


ALTER FUNCTION "public"."intel_combine_all_sponsor_repeats"("_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_company_detail"("_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE c companies%ROWTYPE;
BEGIN
  PERFORM public._require_super_admin();
  SELECT * INTO c FROM companies WHERE id = _id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Company not found' USING ERRCODE = 'P0002'; END IF;
  RETURN jsonb_build_object(
    'company', to_jsonb(c) || jsonb_build_object('parent_name', (SELECT name FROM companies WHERE id = c.parent_company_id)),
    'aliases', COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a.alias) FROM company_aliases a WHERE a.company_id = _id), '[]'),
    'domains', COALESCE((SELECT jsonb_agg(to_jsonb(d) ORDER BY d.domain) FROM company_domains d WHERE d.company_id = _id), '[]'),
    'identifiers', COALESCE((SELECT jsonb_agg(to_jsonb(i)) FROM company_identifiers i WHERE i.company_id = _id), '[]'),
    'subsidiaries', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', s.id, 'name', s.name)) FROM companies s WHERE s.parent_company_id = _id AND s.merged_into IS NULL), '[]'),
    'contacts', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', p.id, 'name', p.display_name, 'designation', p.designation)) FROM (
                  SELECT * FROM people WHERE current_company_id = _id AND merged_into IS NULL ORDER BY display_name LIMIT 200) p), '[]'),
    'registrations', (SELECT count(*) FROM registrations WHERE company_id = _id),
    'sponsors', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', s.id, 'name', s.name, 'website', s.website,
                  'owner', (SELECT u.email FROM auth.users u WHERE u.id = s.user_id),
                  'events', (SELECT count(*) FROM event_sponsors es WHERE es.sponsor_id = s.id)))
                  FROM sponsors s WHERE s.company_id = _id AND s.merged_into IS NULL), '[]'),
    'event_sponsorships', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', es.id, 'event_id', e.id, 'event', e.title, 'date', e.date,
                  'tier', es.tier, 'tier_label', es.tier_label, 'sponsor_id', s.id, 'sponsor', s.name,
                  'owner', (SELECT u.email FROM auth.users u WHERE u.id = s.user_id),
                  'package', d.package, 'status', COALESCE(d.status, 'confirmed'), 'commercial_value', d.commercial_value, 'currency', d.currency,
                  'contacts', COALESCE((SELECT jsonb_agg(COALESCE(m.display_name, m.email)) FROM event_sponsor_contacts a JOIN sponsor_members m ON m.id = a.member_id WHERE a.event_sponsor_id = es.id), '[]'::jsonb))
                  ORDER BY e.date DESC NULLS LAST)
                  FROM sponsors s JOIN event_sponsors es ON es.sponsor_id = s.id JOIN events e ON e.id = es.event_id
                  LEFT JOIN event_sponsorship_details d ON d.event_sponsor_id = es.id
                 WHERE s.company_id = _id), '[]'),
    'sponsor_team', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', m.id, 'person_id', m.person_id, 'name', COALESCE(m.display_name, m.email), 'email', m.email,
                  'designation', m.designation, 'sponsor', s.name, 'accepted_at', m.accepted_at,
                  'events', (SELECT count(*) FROM event_sponsor_contacts a WHERE a.member_id = m.id)) ORDER BY lower(COALESCE(m.display_name, m.email)))
                  FROM sponsor_members m JOIN sponsors s ON s.id = m.sponsor_id WHERE s.company_id = _id AND s.merged_into IS NULL), '[]'),
    'merged_from', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', m.id, 'name', m.name)) FROM companies m WHERE m.merged_into = _id), '[]'),
    'history', COALESCE((SELECT jsonb_agg(to_jsonb(h) ORDER BY h.created_at DESC) FROM (
                  SELECT * FROM intel_field_history WHERE entity_type = 'company' AND entity_id = _id ORDER BY created_at DESC LIMIT 100) h), '[]'),
    'suggestions', COALESCE((SELECT jsonb_agg(to_jsonb(s)) FROM correction_suggestions s
                  WHERE s.entity_type = 'company' AND s.entity_id = _id AND s.status = 'open'), '[]')
  );
END;
$$;


ALTER FUNCTION "public"."intel_company_detail"("_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_company_identifier"("_id" "uuid", "_op" "text", "_value" "text", "_kind" "text" DEFAULT NULL::"text", "_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid uuid := public._require_super_admin();
  _dom text;
  _other uuid;
BEGIN
  PERFORM 1 FROM companies WHERE id = _id AND merged_into IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Company not found or merged' USING ERRCODE = 'P0002'; END IF;
  IF _op = 'add_alias' THEN
    IF public.company_name_key(_value) = '' THEN RAISE EXCEPTION 'Enter the alias' USING ERRCODE = '22023'; END IF;
    INSERT INTO company_aliases (company_id, alias, alias_key, kind)
    VALUES (_id, public.norm_text(_value), public.company_name_key(_value), COALESCE(NULLIF(_kind, ''), 'alternate'))
    ON CONFLICT (company_id, alias_key) DO NOTHING;
  ELSIF _op = 'remove_alias' THEN
    DELETE FROM company_aliases WHERE company_id = _id AND alias_key = public.company_name_key(_value);
  ELSIF _op = 'add_domain' THEN
    _dom := public.norm_website_domain(_value);
    IF _dom IS NULL THEN RAISE EXCEPTION 'Not a valid domain' USING ERRCODE = '22023'; END IF;
    SELECT company_id INTO _other FROM company_domains WHERE domain = _dom;
    IF _other IS NOT NULL AND _other <> _id THEN
      RAISE EXCEPTION 'That domain belongs to another company — merge them instead' USING ERRCODE = '23505';
    END IF;
    INSERT INTO company_domains (company_id, domain, kind) VALUES (_id, _dom, COALESCE(NULLIF(_kind, ''), 'website'))
    ON CONFLICT (domain) DO NOTHING;
  ELSIF _op = 'remove_domain' THEN
    DELETE FROM company_domains WHERE company_id = _id AND domain = public.norm_website_domain(_value);
  ELSIF _op = 'add_identifier' THEN
    IF _kind NOT IN ('CIN','GSTIN','LEI','DUNS','VAT','EIN','CRN','OTHER') OR NULLIF(btrim(_value), '') IS NULL THEN
      RAISE EXCEPTION 'Choose the identifier type and enter its value' USING ERRCODE = '22023';
    END IF;
    SELECT company_id INTO _other FROM company_identifiers WHERE scheme = _kind AND value = upper(btrim(_value));
    IF _other IS NOT NULL AND _other <> _id THEN
      RAISE EXCEPTION 'That identifier belongs to another company' USING ERRCODE = '23505';
    END IF;
    INSERT INTO company_identifiers (company_id, scheme, value) VALUES (_id, _kind, upper(btrim(_value)))
    ON CONFLICT (scheme, value) DO NOTHING;
  ELSIF _op = 'remove_identifier' THEN
    DELETE FROM company_identifiers WHERE company_id = _id AND scheme = _kind AND value = upper(btrim(_value));
  ELSE
    RAISE EXCEPTION 'Unknown operation %', _op USING ERRCODE = '22023';
  END IF;
  INSERT INTO intel_field_history (entity_type, entity_id, field, old_value, new_value, source, reason, actor_id)
  VALUES ('company', _id, split_part(_op, '_', 2) || 's', CASE WHEN _op LIKE 'remove%' THEN _value END,
          CASE WHEN _op LIKE 'add%' THEN _value END, 'manual', COALESCE(_reason, _op), _uid);
  INSERT INTO audit_logs (actor_id, action, target_type, target_id, details)
  VALUES (_uid, 'intel.company_' || _op, 'company', _id::text, jsonb_build_object('value', _value, 'kind', _kind, 'reason', _reason));
END;
$$;


ALTER FUNCTION "public"."intel_company_identifier"("_id" "uuid", "_op" "text", "_value" "text", "_kind" "text", "_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_connect_sponsor"("_sponsor" "uuid", "_company" "uuid", "_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid uuid := public._require_super_admin();
  _old uuid;
BEGIN
  SELECT company_id INTO _old FROM sponsors WHERE id = _sponsor FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Sponsor not found' USING ERRCODE = 'P0002'; END IF;
  IF _company IS NOT NULL THEN
    PERFORM 1 FROM companies WHERE id = _company AND merged_into IS NULL;
    IF NOT FOUND THEN RAISE EXCEPTION 'Unknown company' USING ERRCODE = '22023'; END IF;
  END IF;
  UPDATE sponsors SET company_id = _company WHERE id = _sponsor;
  INSERT INTO audit_logs (actor_id, action, target_type, target_id, details)
  VALUES (_uid, 'intel.sponsor_connected', 'sponsor', _sponsor::text,
          jsonb_build_object('from', _old, 'to', _company, 'reason', _reason));
END;
$$;


ALTER FUNCTION "public"."intel_connect_sponsor"("_sponsor" "uuid", "_company" "uuid", "_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_consolidate_company_sponsors"("_company" "uuid", "_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  g        record;
  _pass    integer;
  _merged  integer := 0;
  _skipped jsonb := '[]'::jsonb;
BEGIN
  PERFORM public._require_super_admin();
  FOR _pass IN 1..2 LOOP
    FOR g IN
      SELECT (ARRAY_AGG(x.id ORDER BY x.n DESC, x.created_at, x.id)) AS ids, max(x.name) AS name
        FROM (SELECT s.id, s.name, s.created_at, (SELECT count(*) FROM event_sponsors es WHERE es.sponsor_id = s.id) AS n,
                     CASE _pass WHEN 1 THEN public._sponsor_scope(s.id) ELSE s.user_id::text END AS grp
                FROM sponsors s WHERE s.company_id = _company AND s.merged_into IS NULL) x
       GROUP BY x.grp HAVING count(*) > 1
    LOOP
      BEGIN
        PERFORM public.intel_merge_sponsors(g.ids[1], g.ids[2:], COALESCE(_reason, 'Company merged'));
        _merged := _merged + array_length(g.ids, 1) - 1;
      EXCEPTION WHEN unique_violation OR insufficient_privilege THEN
        IF _pass = 2 OR NOT _skipped @> jsonb_build_array(jsonb_build_object('ids', g.ids)) THEN
          _skipped := _skipped || jsonb_build_object('ids', g.ids, 'name', g.name, 'reason', SQLERRM);
        END IF;
      END;
    END LOOP;
  END LOOP;
  RETURN jsonb_build_object('merged', _merged, 'skipped', _skipped);
END;
$$;


ALTER FUNCTION "public"."intel_consolidate_company_sponsors"("_company" "uuid", "_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_contact_detail"("_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE p people%ROWTYPE;
BEGIN
  PERFORM public._require_super_admin();
  SELECT * INTO p FROM people WHERE id = _id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Contact not found' USING ERRCODE = 'P0002'; END IF;
  RETURN jsonb_build_object(
    'person', to_jsonb(p) || jsonb_build_object('company_name', (SELECT name FROM companies WHERE id = p.current_company_id)),
    'merged_into', p.merged_into,
    'emails', COALESCE((SELECT jsonb_agg(to_jsonb(e) ORDER BY e.created_at) FROM person_emails e WHERE e.person_id = _id), '[]'),
    'phones', COALESCE((SELECT jsonb_agg(to_jsonb(ph) ORDER BY ph.created_at) FROM person_phones ph WHERE ph.person_id = _id), '[]'),
    'links', COALESCE((SELECT jsonb_agg(to_jsonb(l) ORDER BY l.created_at) FROM person_links l WHERE l.person_id = _id), '[]'),
    'affiliations', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', a.id, 'company_id', a.company_id, 'company', c.name,
                     'designation', a.designation, 'is_current', a.is_current, 'source', a.source, 'created_at', a.created_at) ORDER BY a.created_at DESC)
                     FROM person_company_affiliations a JOIN companies c ON c.id = a.company_id WHERE a.person_id = _id), '[]'),
    'registrations', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', r.id, 'event_id', r.event_id, 'event', e.title, 'date', e.date,
                     'name', r.name, 'email', r.email, 'company', r.company, 'designation', r.designation,
                     'approval_status', r.approval_status, 'checked_in', r.checked_in, 'created_at', r.created_at) ORDER BY r.created_at DESC)
                     FROM registrations r LEFT JOIN events e ON e.id = r.event_id WHERE r.person_id = _id), '[]'),
    'speakers', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', s.id, 'name', s.name, 'email', s.email, 'company', s.company,
                     'designation', s.designation, 'events', (SELECT COALESCE(jsonb_agg(ev.title), '[]') FROM event_speakers es JOIN events ev ON ev.id = es.event_id WHERE es.speaker_id = s.id)))
                     FROM speakers s WHERE s.person_id = _id), '[]'),
    'sponsor_contacts', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', m.id, 'sponsor', sp.name, 'email', m.email,
                     'designation', m.designation, 'accepted_at', m.accepted_at))
                     FROM sponsor_members m JOIN sponsors sp ON sp.id = m.sponsor_id WHERE m.person_id = _id), '[]'),
    'organisations', COALESCE((SELECT jsonb_agg(jsonb_build_object('org', o.name, 'role', om.role))
                     FROM org_members om JOIN organizations o ON o.id = om.org_id WHERE p.user_id IS NOT NULL AND om.user_id = p.user_id), '[]'),
    'history', COALESCE((SELECT jsonb_agg(to_jsonb(h) ORDER BY h.created_at DESC) FROM (
                     SELECT * FROM intel_field_history WHERE entity_type = 'person' AND entity_id = _id ORDER BY created_at DESC LIMIT 100) h), '[]'),
    'suggestions', COALESCE((SELECT jsonb_agg(to_jsonb(s)) FROM correction_suggestions s
                     WHERE s.entity_type = 'person' AND s.entity_id = _id AND s.status = 'open'), '[]')
  );
END;
$$;


ALTER FUNCTION "public"."intel_contact_detail"("_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_contact_identifier"("_id" "uuid", "_op" "text", "_value" "text", "_country_code" "text" DEFAULT NULL::"text", "_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid  uuid := public._require_super_admin();
  _key  text;
  _e164 text;
  _li   text;
  _owner uuid;
  _user uuid;
BEGIN
  SELECT user_id INTO _user FROM people WHERE id = _id AND merged_into IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Contact not found or merged' USING ERRCODE = 'P0002'; END IF;

  IF _op IN ('add_email','remove_email','verify_email','unverify_email') THEN
    _key := public.norm_email(_value);
    IF _key IS NULL THEN RAISE EXCEPTION 'Not a valid email address' USING ERRCODE = '22023'; END IF;
    SELECT person_id INTO _owner FROM person_emails WHERE email_key = _key;
    IF _op = 'add_email' THEN
      IF _owner IS NOT NULL AND _owner <> _id THEN
        RAISE EXCEPTION 'That address belongs to another contact — merge them instead' USING ERRCODE = '23505';
      END IF;
      INSERT INTO person_emails (person_id, email, email_key, source) VALUES (_id, public.norm_text(_value), _key, 'manual')
      ON CONFLICT (email_key) DO NOTHING;
    ELSE
      IF _owner IS DISTINCT FROM _id THEN RAISE EXCEPTION 'That address is not on this contact' USING ERRCODE = '22023'; END IF;
      IF _op = 'remove_email' THEN
        IF _user IS NOT NULL AND EXISTS (SELECT 1 FROM auth.users u WHERE u.id = _user AND lower(u.email) = _key) THEN
          RAISE EXCEPTION 'This address signs in to the contact''s account and cannot be removed here' USING ERRCODE = '42501';
        END IF;
        DELETE FROM person_emails WHERE email_key = _key;
      ELSIF _op = 'verify_email' THEN
        UPDATE person_emails SET verified_at = COALESCE(verified_at, now()) WHERE email_key = _key;
      ELSE
        IF _user IS NOT NULL AND EXISTS (SELECT 1 FROM auth.users u WHERE u.id = _user AND lower(u.email) = _key) THEN
          RAISE EXCEPTION 'This address was verified by the contact''s own sign-in' USING ERRCODE = '42501';
        END IF;
        UPDATE person_emails SET verified_at = NULL WHERE email_key = _key;
      END IF;
    END IF;
  ELSIF _op IN ('add_phone','remove_phone','verify_phone','unverify_phone') THEN
    _e164 := public.norm_phone(_country_code, _value);
    IF _e164 IS NULL THEN RAISE EXCEPTION 'Not a valid phone number' USING ERRCODE = '22023'; END IF;
    IF _op = 'add_phone' THEN
      INSERT INTO person_phones (person_id, country_code, number, phone_e164, source)
      VALUES (_id, public.norm_country_code(_country_code), public.norm_text(_value), _e164, 'manual')
      ON CONFLICT (person_id, phone_e164) DO NOTHING;
    ELSIF _op = 'remove_phone' THEN
      DELETE FROM person_phones WHERE person_id = _id AND phone_e164 = _e164;
    ELSE
      UPDATE person_phones SET verified_at = CASE WHEN _op = 'verify_phone' THEN COALESCE(verified_at, now()) END
       WHERE person_id = _id AND phone_e164 = _e164;
    END IF;
  ELSIF _op IN ('add_linkedin','remove_linkedin') THEN
    _li := public.linkedin_key(_value);
    IF _li IS NULL THEN RAISE EXCEPTION 'Not a LinkedIn profile URL' USING ERRCODE = '22023'; END IF;
    IF _op = 'add_linkedin' THEN
      INSERT INTO person_links (person_id, kind, url, url_key)
      VALUES (_id, 'linkedin', 'https://www.linkedin.com/in/' || _li, _li)
      ON CONFLICT (person_id, kind, url_key) DO NOTHING;
    ELSE
      DELETE FROM person_links WHERE person_id = _id AND kind = 'linkedin' AND url_key = _li;
    END IF;
  ELSE
    RAISE EXCEPTION 'Unknown operation %', _op USING ERRCODE = '22023';
  END IF;

  INSERT INTO intel_field_history (entity_type, entity_id, field, old_value, new_value, source, reason, actor_id)
  VALUES ('person', _id, split_part(_op, '_', 2) || 's', CASE WHEN _op LIKE 'remove%' OR _op LIKE 'unverify%' THEN _value END,
          CASE WHEN _op LIKE 'add%' OR _op LIKE 'verify%' THEN _value END, 'manual', COALESCE(_reason, _op), _uid);
  INSERT INTO audit_logs (actor_id, action, target_type, target_id, details)
  VALUES (_uid, 'intel.contact_' || _op, 'person', _id::text, jsonb_build_object('value', _value, 'reason', _reason));
END;
$$;


ALTER FUNCTION "public"."intel_contact_identifier"("_id" "uuid", "_op" "text", "_value" "text", "_country_code" "text", "_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_corrections"("_status" "text" DEFAULT 'open'::"text", "_entity" "text" DEFAULT NULL::"text", "_kind" "text" DEFAULT NULL::"text", "_limit" integer DEFAULT 25, "_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM public._require_super_admin();
  RETURN (
    WITH q AS (
      SELECT s.* FROM correction_suggestions s
       WHERE s.status = COALESCE(_status, 'open')
         AND (_entity IS NULL OR s.entity_type = _entity)
         AND (_kind IS NULL OR s.kind = _kind)
    ), page AS (
      SELECT * FROM q ORDER BY q.safe DESC, q.confidence DESC, q.created_at, q.id
       LIMIT LEAST(GREATEST(COALESCE(_limit, 25), 1), 200) OFFSET GREATEST(COALESCE(_offset, 0), 0)
    )
    SELECT jsonb_build_object(
      'total', (SELECT count(*) FROM q),
      'safe_total', (SELECT count(*) FROM q WHERE q.safe),
      'rows', COALESCE((SELECT jsonb_agg(to_jsonb(p) || jsonb_build_object('label',
             CASE p.entity_type WHEN 'person' THEN (SELECT display_name FROM people WHERE id = p.entity_id)
                                ELSE (SELECT name FROM companies WHERE id = p.entity_id) END)
             ORDER BY p.safe DESC, p.confidence DESC, p.created_at, p.id) FROM page p), '[]'::jsonb))
  );
END;
$$;


ALTER FUNCTION "public"."intel_corrections"("_status" "text", "_entity" "text", "_kind" "text", "_limit" integer, "_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_duplicate_queue"("_entity" "text", "_status" "text" DEFAULT 'open'::"text", "_min_score" integer DEFAULT 0, "_limit" integer DEFAULT 25, "_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _lim integer := LEAST(GREATEST(COALESCE(_limit, 25), 1), 200);
  _off integer := GREATEST(COALESCE(_offset, 0), 0);
BEGIN
  PERFORM public._require_super_admin();
  IF _entity = 'person' THEN
    RETURN (
      WITH q AS (
        SELECT m.* FROM identity_match_candidates m
          JOIN people a ON a.id = m.person_a AND a.merged_into IS NULL
          JOIN people b ON b.id = m.person_b AND b.merged_into IS NULL
         WHERE m.status = COALESCE(_status, 'open') AND m.score >= COALESCE(_min_score, 0)
      ), page AS (SELECT * FROM q ORDER BY q.score DESC, q.id LIMIT _lim OFFSET _off)
      SELECT jsonb_build_object('total', (SELECT count(*) FROM q), 'rows', COALESCE((
        SELECT jsonb_agg(jsonb_build_object('id', p.id, 'score', p.score, 'reasons', p.reasons, 'status', p.status,
                 'a', public._intel_person_card(p.person_a), 'b', public._intel_person_card(p.person_b)) ORDER BY p.score DESC, p.id)
          FROM page p), '[]'::jsonb)));
  ELSIF _entity = 'company' THEN
    RETURN (
      WITH q AS (
        SELECT m.* FROM company_match_candidates m
          JOIN companies a ON a.id = m.company_a AND a.merged_into IS NULL
          JOIN companies b ON b.id = m.company_b AND b.merged_into IS NULL
         WHERE m.status = COALESCE(_status, 'open') AND m.score >= COALESCE(_min_score, 0)
      ), page AS (SELECT * FROM q ORDER BY q.score DESC, q.id LIMIT _lim OFFSET _off)
      SELECT jsonb_build_object('total', (SELECT count(*) FROM q), 'rows', COALESCE((
        SELECT jsonb_agg(jsonb_build_object('id', p.id, 'score', p.score, 'reasons', p.reasons, 'status', p.status,
                 'a', public._intel_company_card(p.company_a), 'b', public._intel_company_card(p.company_b)) ORDER BY p.score DESC, p.id)
          FROM page p), '[]'::jsonb)));
  END IF;
  RAISE EXCEPTION 'Unknown record type' USING ERRCODE = '22023';
END;
$$;


ALTER FUNCTION "public"."intel_duplicate_queue"("_entity" "text", "_status" "text", "_min_score" integer, "_limit" integer, "_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_generate_corrections"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  p   record;
  c   record;
  f   text;
  v   text;
  fix text;
  pre jsonb;
  _n  integer;
BEGIN
  PERFORM public._require_super_admin();

  FOR p IN SELECT * FROM people WHERE merged_into IS NULL LOOP
    FOREACH f IN ARRAY ARRAY['first_name','last_name','designation','department','city'] LOOP
      v := to_jsonb(p) ->> f;
      CONTINUE WHEN v IS NULL;
      IF v <> public.norm_text(v) THEN
        PERFORM public._intel_suggest('person', p.id, f, 'spacing', v, public.norm_text(v),
          'Extra or unusual spaces', 95, 'Formatting rule', true);
      ELSIF f IN ('first_name','last_name','city') AND public._intel_name_case(v) IS NOT NULL AND public._intel_name_case(v) <> v THEN
        PERFORM public._intel_suggest('person', p.id, f, 'capitalisation', v, public._intel_name_case(v),
          'Written in all capitals or all lower case', 90, 'Formatting rule', true);
      END IF;
    END LOOP;

    -- Swapped names: the person's own registration has them the other way round.
    IF p.first_name IS NOT NULL AND p.last_name IS NOT NULL AND EXISTS (
         SELECT 1 FROM registrations r WHERE r.person_id = p.id
            AND public.person_name_key(r.first_name) = public.person_name_key(p.last_name)
            AND public.person_name_key(r.last_name)  = public.person_name_key(p.first_name)) THEN
      PERFORM public._intel_suggest('person', p.id, 'first_name', 'swapped_names', p.first_name, p.last_name,
        'First and last name look swapped', 60,
        'A registration by this person has them the other way round', false);
    END IF;

    -- Missing details that the person's own records hold.
    v := NULL;
    IF p.first_name IS NULL OR p.last_name IS NULL OR p.designation IS NULL THEN
      SELECT e.email INTO v FROM person_emails e WHERE e.person_id = p.id ORDER BY e.verified_at IS NULL, e.created_at LIMIT 1;
    END IF;
    IF v IS NOT NULL THEN
      pre := public.invitation_prefill(v, false);
      FOREACH f IN ARRAY ARRAY['first_name','last_name','designation'] LOOP
        IF to_jsonb(p) ->> f IS NULL AND NULLIF(pre ->> f, '') IS NOT NULL THEN
          PERFORM public._intel_suggest('person', p.id, f, 'missing', NULL, pre ->> f,
            'Missing from the profile', 75, 'Newest registration, speaker or sponsor-contact record', false);
        END IF;
      END LOOP;
    END IF;

    -- Designations that disagree between the person's records.
    SELECT string_agg(DISTINCT public.norm_text(d), ' | ') INTO v
      FROM (SELECT r.designation d FROM registrations r WHERE r.person_id = p.id
            UNION ALL SELECT s.designation FROM speakers s WHERE s.person_id = p.id
            UNION ALL SELECT m.designation FROM sponsor_members m WHERE m.person_id = p.id) x
     WHERE NULLIF(btrim(d), '') IS NOT NULL;
    IF v LIKE '%|%' THEN
      SELECT public.norm_text(d) INTO fix FROM (
        SELECT r.designation d, r.created_at t FROM registrations r WHERE r.person_id = p.id
        UNION ALL SELECT s.designation, s.updated_at FROM speakers s WHERE s.person_id = p.id
        UNION ALL SELECT m.designation, m.updated_at FROM sponsor_members m WHERE m.person_id = p.id) x
       WHERE NULLIF(btrim(d), '') IS NOT NULL ORDER BY t DESC LIMIT 1;
      IF fix IS DISTINCT FROM p.designation THEN
        PERFORM public._intel_suggest('person', p.id, 'designation', 'conflicting', p.designation, fix,
          'Records disagree on the designation; this is the newest', 50, 'Seen: ' || v, false);
      END IF;
    END IF;
  END LOOP;

  FOR c IN SELECT * FROM companies WHERE merged_into IS NULL AND verification_status <> 'rejected' LOOP
    IF c.name <> public.norm_text(c.name) THEN
      PERFORM public._intel_suggest('company', c.id, 'name', 'spacing', c.name, public.norm_text(c.name),
        'Extra or unusual spaces', 95, 'Formatting rule', true);
    END IF;
    -- Website from the work-email domain most of its people share.
    IF c.website IS NULL AND NOT EXISTS (SELECT 1 FROM company_domains d WHERE d.company_id = c.id) THEN
      SELECT x.dom INTO fix FROM (
        SELECT public.email_domain(e.email) dom, count(*) n
          FROM company_mentions m JOIN person_emails e ON e.person_id = m.person_id
         WHERE m.company_id = c.id
         GROUP BY 1) x
       WHERE x.dom IS NOT NULL AND NOT EXISTS (SELECT 1 FROM personal_email_domains pd WHERE pd.domain = x.dom)
         AND NOT EXISTS (SELECT 1 FROM company_domains d WHERE d.domain = x.dom)
       ORDER BY x.n DESC LIMIT 1;
      IF fix IS NOT NULL THEN
        PERFORM public._intel_suggest('company', c.id, 'website', 'missing_domain', NULL, 'https://' || fix,
          'No website or domain on record', 55, 'Work-email domain of people who entered this company', false);
      ELSE
        PERFORM public._intel_suggest('company', c.id, 'website', 'missing_domain', NULL, NULL,
          'No website or domain on record', 40, 'No work-email domain to suggest', false);
      END IF;
    END IF;
    IF c.industry IS NULL THEN
      PERFORM public._intel_suggest('company', c.id, 'industry', 'incomplete', NULL, NULL,
        'Industry missing', 40, NULL, false);
    END IF;
  END LOOP;

  -- Suggestions whose field has changed since are no longer valid.
  UPDATE correction_suggestions s SET status = 'stale'
   WHERE s.status = 'open' AND s.current_value IS DISTINCT FROM (
     CASE s.entity_type
       WHEN 'person'  THEN (SELECT to_jsonb(x) ->> s.field FROM people x WHERE x.id = s.entity_id)
       WHEN 'company' THEN (SELECT to_jsonb(x) ->> s.field FROM companies x WHERE x.id = s.entity_id)
     END);

  SELECT count(*) INTO _n FROM correction_suggestions WHERE status = 'open';
  RETURN _n;
END;
$$;


ALTER FUNCTION "public"."intel_generate_corrections"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_merge_companies"("_survivor" "uuid", "_others" "uuid"[], "_choices" "jsonb" DEFAULT '{}'::"jsonb", "_reason" "text" DEFAULT NULL::"text", "_allow_distinct" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid     uuid := public._require_super_admin();
  _surv    companies%ROWTYPE;
  _op      uuid := gen_random_uuid();
  _moved   jsonb := '[]'::jsonb;
  _removed jsonb := '[]'::jsonb;
  _all     uuid[];
  _n       integer;
  k        text;
  r        record;
BEGIN
  IF _others IS NULL OR array_length(_others, 1) IS NULL OR _survivor = ANY (_others) THEN
    RAISE EXCEPTION 'Choose a surviving company and at least one other' USING ERRCODE = '22023';
  END IF;
  _all := _others || _survivor;
  SELECT * INTO _surv FROM companies WHERE id = _survivor AND merged_into IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'The surviving company no longer exists' USING ERRCODE = 'P0002'; END IF;
  SELECT count(*) INTO _n FROM companies WHERE id = ANY (_others) AND merged_into IS NULL;
  IF _n <> array_length(_others, 1) THEN RAISE EXCEPTION 'A company to merge no longer exists or was already merged' USING ERRCODE = 'P0002'; END IF;
  PERFORM 1 FROM companies WHERE id = ANY (_others) FOR UPDATE;

  IF NOT _allow_distinct AND (
       EXISTS (SELECT 1 FROM company_identifiers i1 JOIN company_identifiers i2 ON i1.scheme = i2.scheme AND i1.value <> i2.value
                WHERE i1.company_id = ANY (_all) AND i2.company_id = ANY (_all))
    OR EXISTS (SELECT 1 FROM companies c WHERE c.id = ANY (_all) AND c.parent_company_id = ANY (_all))) THEN
    RAISE EXCEPTION 'These look like separate legal entities (different registry identifiers, or parent and subsidiary). Confirm explicitly to merge them.'
      USING ERRCODE = '42501';
  END IF;

  FOR r IN SELECT * FROM person_company_affiliations x WHERE x.company_id = ANY (_others) LOOP
    IF EXISTS (SELECT 1 FROM person_company_affiliations s WHERE s.company_id = _survivor AND s.person_id = r.person_id AND s.designation_key = r.designation_key) THEN
      _removed := _removed || jsonb_build_object('table', 'person_company_affiliations', 'row', to_jsonb(r));
      DELETE FROM person_company_affiliations WHERE id = r.id;
    ELSE
      _moved := _moved || jsonb_build_object('table', 'person_company_affiliations', 'id', r.id, 'from', r.company_id);
      UPDATE person_company_affiliations SET company_id = _survivor WHERE id = r.id;
    END IF;
  END LOOP;
  FOR r IN SELECT * FROM company_mentions x WHERE x.company_id = ANY (_others) LOOP
    IF EXISTS (SELECT 1 FROM company_mentions s WHERE s.company_id = _survivor AND s.person_id = r.person_id) THEN
      _removed := _removed || jsonb_build_object('table', 'company_mentions', 'row', to_jsonb(r));
      DELETE FROM company_mentions WHERE company_id = r.company_id AND person_id = r.person_id;
    ELSE
      _moved := _moved || jsonb_build_object('table', 'company_mentions', 'person_id', r.person_id, 'from', r.company_id);
      UPDATE company_mentions SET company_id = _survivor WHERE company_id = r.company_id AND person_id = r.person_id;
    END IF;
  END LOOP;
  FOR r IN SELECT * FROM company_aliases x WHERE x.company_id = ANY (_others) LOOP
    IF EXISTS (SELECT 1 FROM company_aliases s WHERE s.company_id = _survivor AND s.alias_key = r.alias_key) THEN
      _removed := _removed || jsonb_build_object('table', 'company_aliases', 'row', to_jsonb(r));
      DELETE FROM company_aliases WHERE id = r.id;
    ELSE
      _moved := _moved || jsonb_build_object('table', 'company_aliases', 'id', r.id, 'from', r.company_id);
      UPDATE company_aliases SET company_id = _survivor WHERE id = r.id;
    END IF;
  END LOOP;
  FOR r IN SELECT 'company_domains' t, id, company_id FROM company_domains WHERE company_id = ANY (_others)
           UNION ALL SELECT 'company_identifiers', id, company_id FROM company_identifiers WHERE company_id = ANY (_others)
           UNION ALL SELECT 'company_locations', id, company_id FROM company_locations WHERE company_id = ANY (_others)
           UNION ALL SELECT 'company_source_records', id, company_id FROM company_source_records WHERE company_id = ANY (_others)
           UNION ALL SELECT 'registrations', id, company_id FROM registrations WHERE company_id = ANY (_others)
           UNION ALL SELECT 'people', id, current_company_id FROM people WHERE current_company_id = ANY (_others)
           UNION ALL SELECT 'sponsors', id, company_id FROM sponsors WHERE company_id = ANY (_others)
           UNION ALL SELECT 'companies', id, parent_company_id FROM companies WHERE parent_company_id = ANY (_others) AND id <> _survivor LOOP
    _moved := _moved || jsonb_build_object('table', r.t, 'id', r.id, 'from', r.company_id);
  END LOOP;
  UPDATE company_domains SET company_id = _survivor WHERE company_id = ANY (_others);
  UPDATE company_identifiers SET company_id = _survivor WHERE company_id = ANY (_others);
  UPDATE company_locations SET company_id = _survivor WHERE company_id = ANY (_others);
  UPDATE company_source_records SET company_id = _survivor WHERE company_id = ANY (_others);
  UPDATE registrations SET company_id = _survivor WHERE company_id = ANY (_others);
  UPDATE people SET current_company_id = _survivor WHERE current_company_id = ANY (_others);
  UPDATE sponsors SET company_id = _survivor WHERE company_id = ANY (_others);
  UPDATE companies SET parent_company_id = _survivor WHERE parent_company_id = ANY (_others) AND id <> _survivor;
  IF _surv.parent_company_id = ANY (_others) THEN
    _moved := _moved || jsonb_build_object('table', 'companies_parent_of_survivor', 'id', _survivor, 'from', _surv.parent_company_id);
    UPDATE companies SET parent_company_id = NULL WHERE id = _survivor;
  END IF;

  -- The others' names stay findable, as former names of the survivor.
  FOR r IN SELECT id, name, name_key FROM companies WHERE id = ANY (_others) LOOP
    IF r.name_key <> _surv.name_key AND NOT EXISTS (SELECT 1 FROM company_aliases WHERE company_id = _survivor AND alias_key = r.name_key) THEN
      INSERT INTO company_aliases (company_id, alias, alias_key, kind) VALUES (_survivor, r.name, r.name_key, 'former')
      RETURNING id INTO k;
      _moved := _moved || jsonb_build_object('table', 'company_aliases_added', 'id', k);
    END IF;
  END LOOP;

  INSERT INTO merge_operations (id, entity_type, survivor_id, merged_ids, field_choices, moved, removed, survivor_before, reason, actor_id)
  VALUES (_op, 'company', _survivor, _others, COALESCE(_choices, '{}'::jsonb), _moved, _removed, to_jsonb(_surv), _reason, _uid);

  FOR k IN SELECT jsonb_object_keys(COALESCE(_choices, '{}'::jsonb)) LOOP
    PERFORM public._intel_set_field('company', _survivor, k, _choices ->> k, 'merge', COALESCE(_reason, 'Merge'), _uid, _op);
  END LOOP;

  UPDATE companies SET merged_into = _survivor, updated_at = now() WHERE id = ANY (_others);
  UPDATE companies SET entry_count = (SELECT count(*) FROM company_mentions WHERE company_id = _survivor) WHERE id = _survivor;
  UPDATE company_match_candidates SET status = 'merged', reviewed_by = _uid, reviewed_at = now()
   WHERE company_a = ANY (_all) AND company_b = ANY (_all);
  INSERT INTO audit_logs (actor_id, action, target_type, target_id, details)
  VALUES (_uid, 'intel.companies_merged', 'company', _survivor::text,
          jsonb_build_object('merge_id', _op, 'merged', _others, 'choices', _choices, 'reason', _reason,
                             'distinct_entities_confirmed', _allow_distinct, 'moved', jsonb_array_length(_moved)));
  RETURN _op;
END;
$$;


ALTER FUNCTION "public"."intel_merge_companies"("_survivor" "uuid", "_others" "uuid"[], "_choices" "jsonb", "_reason" "text", "_allow_distinct" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_merge_people"("_survivor" "uuid", "_others" "uuid"[], "_choices" "jsonb" DEFAULT '{}'::"jsonb", "_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid     uuid := public._require_super_admin();
  _surv    people%ROWTYPE;
  _op      uuid := gen_random_uuid();
  _moved   jsonb := '[]'::jsonb;
  _removed jsonb := '[]'::jsonb;
  _n       integer;
  k        text;
  r        record;
BEGIN
  IF _others IS NULL OR array_length(_others, 1) IS NULL OR _survivor = ANY (_others) THEN
    RAISE EXCEPTION 'Choose a surviving contact and at least one other' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO _surv FROM people WHERE id = _survivor AND merged_into IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'The surviving contact no longer exists' USING ERRCODE = 'P0002'; END IF;
  SELECT count(*) INTO _n FROM people WHERE id = ANY (_others) AND merged_into IS NULL;
  IF _n <> array_length(_others, 1) THEN RAISE EXCEPTION 'A contact to merge no longer exists or was already merged' USING ERRCODE = 'P0002'; END IF;
  PERFORM 1 FROM people WHERE id = ANY (_others) FOR UPDATE;
  IF EXISTS (SELECT 1 FROM people WHERE id = ANY (_others) AND user_id IS NOT NULL) THEN
    IF _surv.user_id IS NOT NULL THEN
      RAISE EXCEPTION 'These contacts belong to two different login accounts; accounts are never merged' USING ERRCODE = '42501';
    END IF;
    RAISE EXCEPTION 'Keep the contact that has a login account as the surviving record' USING ERRCODE = '42501';
  END IF;

  -- Rows the survivor already has the same value for are removed (kept here
  -- for rollback); everything else moves.
  FOR r IN SELECT * FROM person_phones x WHERE x.person_id = ANY (_others) LOOP
    IF EXISTS (SELECT 1 FROM person_phones s WHERE s.person_id = _survivor AND s.phone_e164 = r.phone_e164) THEN
      _removed := _removed || jsonb_build_object('table', 'person_phones', 'row', to_jsonb(r));
      DELETE FROM person_phones WHERE id = r.id;
    ELSE
      _moved := _moved || jsonb_build_object('table', 'person_phones', 'id', r.id, 'from', r.person_id);
      UPDATE person_phones SET person_id = _survivor WHERE id = r.id;
    END IF;
  END LOOP;
  FOR r IN SELECT * FROM person_links x WHERE x.person_id = ANY (_others) LOOP
    IF EXISTS (SELECT 1 FROM person_links s WHERE s.person_id = _survivor AND s.kind = r.kind AND s.url_key = r.url_key) THEN
      _removed := _removed || jsonb_build_object('table', 'person_links', 'row', to_jsonb(r));
      DELETE FROM person_links WHERE id = r.id;
    ELSE
      _moved := _moved || jsonb_build_object('table', 'person_links', 'id', r.id, 'from', r.person_id);
      UPDATE person_links SET person_id = _survivor WHERE id = r.id;
    END IF;
  END LOOP;
  FOR r IN SELECT * FROM person_company_affiliations x WHERE x.person_id = ANY (_others) LOOP
    IF EXISTS (SELECT 1 FROM person_company_affiliations s WHERE s.person_id = _survivor AND s.company_id = r.company_id AND s.designation_key = r.designation_key) THEN
      _removed := _removed || jsonb_build_object('table', 'person_company_affiliations', 'row', to_jsonb(r));
      DELETE FROM person_company_affiliations WHERE id = r.id;
    ELSE
      _moved := _moved || jsonb_build_object('table', 'person_company_affiliations', 'id', r.id, 'from', r.person_id);
      UPDATE person_company_affiliations SET person_id = _survivor WHERE id = r.id;
    END IF;
  END LOOP;
  FOR r IN SELECT * FROM company_mentions x WHERE x.person_id = ANY (_others) LOOP
    IF EXISTS (SELECT 1 FROM company_mentions s WHERE s.person_id = _survivor AND s.company_id = r.company_id) THEN
      _removed := _removed || jsonb_build_object('table', 'company_mentions', 'row', to_jsonb(r));
      DELETE FROM company_mentions WHERE company_id = r.company_id AND person_id = r.person_id;
      UPDATE companies SET entry_count = GREATEST(entry_count - 1, 0) WHERE id = r.company_id;
    ELSE
      _moved := _moved || jsonb_build_object('table', 'company_mentions', 'company_id', r.company_id, 'from', r.person_id);
      UPDATE company_mentions SET person_id = _survivor WHERE company_id = r.company_id AND person_id = r.person_id;
    END IF;
  END LOOP;
  -- One person per address: every address moves.
  FOR r IN SELECT id, person_id FROM person_emails WHERE person_id = ANY (_others) LOOP
    _moved := _moved || jsonb_build_object('table', 'person_emails', 'id', r.id, 'from', r.person_id);
  END LOOP;
  UPDATE person_emails SET person_id = _survivor WHERE person_id = ANY (_others);
  -- Records that refer to the person; their own contents are untouched.
  FOR r IN SELECT 'registrations' t, id, person_id FROM registrations WHERE person_id = ANY (_others)
           UNION ALL SELECT 'speakers', id, person_id FROM speakers WHERE person_id = ANY (_others)
           UNION ALL SELECT 'sponsor_members', id, person_id FROM sponsor_members WHERE person_id = ANY (_others)
           UNION ALL SELECT 'account_activation_tokens', id, person_id FROM account_activation_tokens WHERE person_id = ANY (_others) LOOP
    _moved := _moved || jsonb_build_object('table', r.t, 'id', r.id, 'from', r.person_id);
  END LOOP;
  UPDATE registrations SET person_id = _survivor WHERE person_id = ANY (_others);
  UPDATE speakers SET person_id = _survivor WHERE person_id = ANY (_others);
  UPDATE sponsor_members SET person_id = _survivor WHERE person_id = ANY (_others);
  UPDATE account_activation_tokens SET person_id = _survivor WHERE person_id = ANY (_others);

  INSERT INTO merge_operations (id, entity_type, survivor_id, merged_ids, field_choices, moved, removed, survivor_before, reason, actor_id)
  VALUES (_op, 'person', _survivor, _others, COALESCE(_choices, '{}'::jsonb), _moved, _removed, to_jsonb(_surv), _reason, _uid);

  FOR k IN SELECT jsonb_object_keys(COALESCE(_choices, '{}'::jsonb)) LOOP
    PERFORM public._intel_set_field('person', _survivor, k, _choices ->> k, 'merge', COALESCE(_reason, 'Merge'), _uid, _op);
  END LOOP;

  UPDATE people SET merged_into = _survivor, updated_at = now() WHERE id = ANY (_others);
  UPDATE identity_match_candidates SET status = 'merged', reviewed_by = _uid, reviewed_at = now()
   WHERE (person_a = _survivor AND person_b = ANY (_others)) OR (person_b = _survivor AND person_a = ANY (_others))
      OR (person_a = ANY (_others) AND person_b = ANY (_others));
  INSERT INTO audit_logs (actor_id, action, target_type, target_id, details)
  VALUES (_uid, 'intel.contacts_merged', 'person', _survivor::text,
          jsonb_build_object('merge_id', _op, 'merged', _others, 'choices', _choices, 'reason', _reason,
                             'moved', jsonb_array_length(_moved), 'deduplicated', jsonb_array_length(_removed)));
  RETURN _op;
END;
$$;


ALTER FUNCTION "public"."intel_merge_people"("_survivor" "uuid", "_others" "uuid"[], "_choices" "jsonb", "_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_merge_preview"("_entity" "text", "_survivor" "uuid", "_others" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _all uuid[] := _others;
BEGIN
  PERFORM public._require_super_admin();
  IF _entity = 'person' THEN
    RETURN jsonb_build_object(
      'registrations',    (SELECT count(*) FROM registrations WHERE person_id = ANY (_all)),
      'events',           (SELECT count(DISTINCT event_id) FROM registrations WHERE person_id = ANY (_all)),
      'speaker_records',  (SELECT count(*) FROM speakers WHERE person_id = ANY (_all)),
      'sponsor_contacts', (SELECT count(*) FROM sponsor_members WHERE person_id = ANY (_all)),
      'emails',           (SELECT count(*) FROM person_emails WHERE person_id = ANY (_all)),
      'phones',           (SELECT count(*) FROM person_phones WHERE person_id = ANY (_all)),
      'affiliations',     (SELECT count(*) FROM person_company_affiliations WHERE person_id = ANY (_all)),
      'accounts',         (SELECT count(*) FROM people WHERE id = ANY (_all) AND user_id IS NOT NULL),
      'survivor_has_account', (SELECT user_id IS NOT NULL FROM people WHERE id = _survivor));
  ELSIF _entity = 'company' THEN
    RETURN jsonb_build_object(
      'contacts',      (SELECT count(*) FROM people WHERE current_company_id = ANY (_all) AND merged_into IS NULL),
      'affiliations',  (SELECT count(*) FROM person_company_affiliations WHERE company_id = ANY (_all)),
      'registrations', (SELECT count(*) FROM registrations WHERE company_id = ANY (_all)),
      'events',        (SELECT count(DISTINCT event_id) FROM registrations WHERE company_id = ANY (_all)),
      'sponsorships',  (SELECT count(*) FROM event_sponsors es JOIN sponsors s ON s.id = es.sponsor_id WHERE s.company_id = ANY (_all)),
      'sponsors',      (SELECT count(*) FROM sponsors WHERE company_id = ANY (_all) AND merged_into IS NULL),
      'subsidiaries',  (SELECT count(*) FROM companies WHERE parent_company_id = ANY (_all) AND merged_into IS NULL),
      'domains',       (SELECT count(*) FROM company_domains WHERE company_id = ANY (_all)),
      'identifiers',   (SELECT count(*) FROM company_identifiers WHERE company_id = ANY (_all)),
      'distinct_legal_entities', EXISTS (
         SELECT 1 FROM company_identifiers i1 JOIN company_identifiers i2 ON i1.scheme = i2.scheme AND i1.value <> i2.value
          WHERE i1.company_id = ANY (_all || _survivor) AND i2.company_id = ANY (_all || _survivor)),
      'parent_child', EXISTS (
         SELECT 1 FROM companies c WHERE c.id = ANY (_all || _survivor) AND c.parent_company_id = ANY (_all || _survivor)));
  END IF;
  RAISE EXCEPTION 'Unknown record type' USING ERRCODE = '22023';
END;
$$;


ALTER FUNCTION "public"."intel_merge_preview"("_entity" "text", "_survivor" "uuid", "_others" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_merge_sponsors"("_survivor" "uuid", "_others" "uuid"[], "_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid     uuid := public._require_super_admin();
  _surv    sponsors%ROWTYPE;
  _op      uuid := gen_random_uuid();
  _moved   jsonb := '[]'::jsonb;
  _removed jsonb := '[]'::jsonb;
  _n       integer;
  r        record;
  a        record;
  t        sponsor_members%ROWTYPE;
  l        event_sponsors%ROWTYPE;
  d        event_sponsorship_details%ROWTYPE;
BEGIN
  IF _others IS NULL OR array_length(_others, 1) IS NULL OR _survivor = ANY (_others) THEN
    RAISE EXCEPTION 'Choose a surviving sponsor record and at least one other' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO _surv FROM sponsors WHERE id = _survivor AND merged_into IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'The surviving record no longer exists' USING ERRCODE = 'P0002'; END IF;
  SELECT count(*) INTO _n FROM sponsors WHERE id = ANY (_others) AND merged_into IS NULL;
  IF _n <> array_length(_others, 1) THEN RAISE EXCEPTION 'A record to merge no longer exists or was already merged' USING ERRCODE = 'P0002'; END IF;
  PERFORM 1 FROM sponsors WHERE id = ANY (_others) FOR UPDATE;
  IF EXISTS (SELECT 1 FROM sponsors WHERE id = ANY (_others) AND user_id IS DISTINCT FROM _surv.user_id
              AND public._sponsor_scope(id) IS DISTINCT FROM public._sponsor_scope(_survivor)) THEN
    RAISE EXCEPTION 'These records belong to different organisations. A sponsor''s team sees every event of its record, so they stay separate, under one company.' USING ERRCODE = '42501';
  END IF;
  IF _surv.company_id IS NULL OR EXISTS (SELECT 1 FROM sponsors WHERE id = ANY (_others) AND company_id IS DISTINCT FROM _surv.company_id) THEN
    RAISE EXCEPTION 'Connect these records to the same company before merging them' USING ERRCODE = '22023';
  END IF;

  -- Team. An address on both teams stays once, keeping whichever access exists.
  FOR r IN SELECT * FROM sponsor_members WHERE sponsor_id = ANY (_others) ORDER BY created_at LOOP
    SELECT * INTO t FROM sponsor_members WHERE sponsor_id = _survivor AND lower(email) = lower(r.email) LIMIT 1;
    IF NOT FOUND THEN
      _moved := _moved || jsonb_build_object('table', 'sponsor_members', 'id', r.id, 'from', r.sponsor_id);
      UPDATE sponsor_members SET sponsor_id = _survivor WHERE id = r.id;
      CONTINUE;
    END IF;
    IF t.user_id IS NOT NULL AND r.user_id IS NOT NULL AND t.user_id <> r.user_id THEN
      RAISE EXCEPTION '% is linked to two different accounts on these records; resolve that first', r.email USING ERRCODE = '42501';
    END IF;
    IF (r.user_id IS NOT NULL AND t.user_id IS NULL) OR (r.accepted_at IS NOT NULL AND t.accepted_at IS NULL) THEN
      _moved := _moved || jsonb_build_object('table', 'member_access', 'id', t.id, 'user_id', t.user_id, 'accepted_at', t.accepted_at);
      UPDATE sponsor_members SET user_id = COALESCE(t.user_id, r.user_id), accepted_at = COALESCE(t.accepted_at, r.accepted_at) WHERE id = t.id;
    END IF;
    FOR a IN SELECT * FROM event_sponsor_contacts WHERE member_id = r.id LOOP
      IF EXISTS (SELECT 1 FROM event_sponsor_contacts x WHERE x.event_sponsor_id = a.event_sponsor_id AND x.member_id = t.id) THEN
        _removed := _removed || jsonb_build_object('table', 'event_sponsor_contacts', 'row', to_jsonb(a));
      ELSE
        _moved := _moved || jsonb_build_object('table', 'contact_member', 'id', a.id, 'from', a.member_id);
        UPDATE event_sponsor_contacts SET member_id = t.id WHERE id = a.id;
      END IF;
    END LOOP;
    _removed := _removed || jsonb_build_object('table', 'sponsor_members', 'row', to_jsonb(r));
    DELETE FROM sponsor_members WHERE id = r.id;
  END LOOP;

  -- Events.
  FOR r IN SELECT es.*, s.logo_url AS sponsor_logo FROM event_sponsors es JOIN sponsors s ON s.id = es.sponsor_id
            WHERE es.sponsor_id = ANY (_others) ORDER BY es.created_at LOOP
    SELECT * INTO l FROM event_sponsors WHERE event_id = r.event_id AND sponsor_id = _survivor;
    IF NOT FOUND THEN
      _moved := _moved || jsonb_build_object('table', 'event_sponsors', 'id', r.id, 'from', r.sponsor_id, 'logo_url', r.logo_url);
      -- The event keeps showing the logo it showed.
      UPDATE event_sponsors
         SET sponsor_id = _survivor,
             logo_url = CASE WHEN r.logo_url IS NULL AND r.sponsor_logo IS DISTINCT FROM _surv.logo_url THEN r.sponsor_logo ELSE r.logo_url END
       WHERE id = r.id;
    ELSE
      IF public._sponsorship_title(l.tier, l.tier_label) <> public._sponsorship_title(r.tier, r.tier_label) THEN
        RAISE EXCEPTION 'These records hold different titles on "%". Those may be separate agreements, so they were not merged. Nothing was changed.',
          (SELECT title FROM events WHERE id = r.event_id) USING ERRCODE = '23505';
      END IF;
      -- The same sponsorship entered twice: its details and contacts join the one that stays.
      SELECT * INTO d FROM event_sponsorship_details WHERE event_sponsor_id = r.id;
      IF FOUND THEN
        IF EXISTS (SELECT 1 FROM event_sponsorship_details WHERE event_sponsor_id = l.id) THEN
          _removed := _removed || jsonb_build_object('table', 'event_sponsorship_details', 'row', to_jsonb(d));
        ELSE
          _moved := _moved || jsonb_build_object('table', 'details_link', 'id', l.id, 'from', r.id);
          UPDATE event_sponsorship_details SET event_sponsor_id = l.id WHERE event_sponsor_id = r.id;
        END IF;
      END IF;
      FOR a IN SELECT * FROM event_sponsor_contacts WHERE event_sponsor_id = r.id LOOP
        IF EXISTS (SELECT 1 FROM event_sponsor_contacts x WHERE x.event_sponsor_id = l.id AND x.member_id = a.member_id) THEN
          _removed := _removed || jsonb_build_object('table', 'event_sponsor_contacts', 'row', to_jsonb(a));
        ELSE
          _moved := _moved || jsonb_build_object('table', 'contact_link', 'id', a.id, 'from', a.event_sponsor_id);
          UPDATE event_sponsor_contacts SET event_sponsor_id = l.id WHERE id = a.id;
        END IF;
      END LOOP;
      _removed := _removed || jsonb_build_object('table', 'event_sponsors',
        'row', to_jsonb((SELECT x FROM event_sponsors x WHERE x.id = r.id)));
      DELETE FROM event_sponsors WHERE id = r.id;
    END IF;
  END LOOP;

  -- Meetings and creatives. The append-only meeting history keeps the ids it recorded.
  FOR r IN SELECT * FROM sponsor_meeting_interests WHERE sponsor_id = ANY (_others) LOOP
    IF EXISTS (SELECT 1 FROM sponsor_meeting_interests x WHERE x.sponsor_id = _survivor AND x.event_id = r.event_id
                AND x.registration_id IS NOT DISTINCT FROM r.registration_id AND x.speaker_id IS NOT DISTINCT FROM r.speaker_id) THEN
      _removed := _removed || jsonb_build_object('table', 'sponsor_meeting_interests', 'row', to_jsonb(r));
      DELETE FROM sponsor_meeting_interests WHERE id = r.id;
    ELSE
      _moved := _moved || jsonb_build_object('table', 'sponsor_meeting_interests', 'id', r.id, 'from', r.sponsor_id);
      UPDATE sponsor_meeting_interests SET sponsor_id = _survivor WHERE id = r.id;
    END IF;
  END LOOP;
  FOR r IN SELECT id, sponsor_id FROM event_creatives WHERE sponsor_id = ANY (_others) LOOP
    _moved := _moved || jsonb_build_object('table', 'event_creatives', 'id', r.id, 'from', r.sponsor_id);
    UPDATE event_creatives SET sponsor_id = _survivor WHERE id = r.id;
  END LOOP;

  INSERT INTO merge_operations (id, entity_type, survivor_id, merged_ids, moved, removed, survivor_before, reason, actor_id)
  VALUES (_op, 'sponsor', _survivor, _others, _moved, _removed, to_jsonb(_surv), _reason, _uid);

  -- Details the survivor lacks; nothing it has is replaced.
  UPDATE sponsors s
     SET email = COALESCE(s.email, o.email), logo_url = COALESCE(s.logo_url, o.logo_url), description = COALESCE(s.description, o.description)
    FROM (SELECT max(email) AS email, max(logo_url) AS logo_url, max(description) AS description FROM sponsors WHERE id = ANY (_others)) o
   WHERE s.id = _survivor;
  UPDATE sponsors SET merged_into = _survivor WHERE id = ANY (_others);

  INSERT INTO audit_logs (actor_id, action, target_type, target_id, details)
  VALUES (_uid, 'intel.sponsors_merged', 'sponsor', _survivor::text,
          jsonb_build_object('merge_id', _op, 'merged', _others, 'reason', _reason, 'moved', jsonb_array_length(_moved), 'deduplicated', jsonb_array_length(_removed)));
  RETURN _op;
END;
$$;


ALTER FUNCTION "public"."intel_merge_sponsors"("_survivor" "uuid", "_others" "uuid"[], "_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_move_sponsorship"("_event_sponsor" "uuid", "_company" "uuid", "_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid    uuid := public._require_super_admin();
  l       event_sponsors%ROWTYPE;
  s       sponsors%ROWTYPE;
  c       companies%ROWTYPE;
  _target uuid;
  r       record;
  _mid    uuid;
BEGIN
  SELECT * INTO l FROM event_sponsors WHERE id = _event_sponsor FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Sponsorship not found' USING ERRCODE = 'P0002'; END IF;
  SELECT * INTO s FROM sponsors WHERE id = l.sponsor_id;
  SELECT * INTO c FROM companies WHERE id = _company AND merged_into IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown company' USING ERRCODE = '22023'; END IF;
  IF s.company_id = _company THEN RAISE EXCEPTION 'This sponsorship is already with that company' USING ERRCODE = '22023'; END IF;

  SELECT id INTO _target FROM sponsors WHERE user_id = s.user_id AND company_id = _company AND merged_into IS NULL ORDER BY created_at LIMIT 1;
  IF _target IS NULL THEN
    INSERT INTO sponsors (user_id, name, website, tier, tier_label, company_id)
    VALUES (s.user_id, c.name, c.website, COALESCE(l.tier, s.tier, 'bronze'), l.tier_label, _company)
    RETURNING id INTO _target;
  END IF;
  IF EXISTS (SELECT 1 FROM event_sponsors WHERE event_id = l.event_id AND sponsor_id = _target) THEN
    RAISE EXCEPTION 'That company already has a sponsorship on this event; review the two together' USING ERRCODE = '23505';
  END IF;

  UPDATE event_sponsors SET sponsor_id = _target, logo_url = COALESCE(logo_url, s.logo_url) WHERE id = l.id;
  UPDATE sponsor_meeting_interests SET sponsor_id = _target WHERE event_id = l.event_id AND sponsor_id = s.id;
  UPDATE event_creatives SET sponsor_id = _target WHERE event_id = l.event_id AND sponsor_id = s.id;
  -- Assigned contacts follow, with the access they have.
  FOR r IN SELECT a.id AS assignment, m.* FROM event_sponsor_contacts a JOIN sponsor_members m ON m.id = a.member_id WHERE a.event_sponsor_id = l.id LOOP
    SELECT id INTO _mid FROM sponsor_members WHERE sponsor_id = _target AND lower(email) = lower(r.email) LIMIT 1;
    IF _mid IS NULL THEN
      INSERT INTO sponsor_members (sponsor_id, user_id, email, display_name, role, accepted_at, title, first_name, last_name, company, designation,
                                   mobile_country_code, mobile_number, linkedin_url)
      VALUES (_target, r.user_id, lower(r.email), r.display_name, r.role, r.accepted_at, r.title, r.first_name, r.last_name, c.name, r.designation,
              r.mobile_country_code, r.mobile_number, r.linkedin_url)
      RETURNING id INTO _mid;
    END IF;
    UPDATE event_sponsor_contacts SET member_id = _mid WHERE id = r.assignment;
  END LOOP;

  INSERT INTO audit_logs (actor_id, action, target_type, target_id, details)
  VALUES (_uid, 'intel.sponsorship_moved', 'event_sponsor', l.id::text,
          jsonb_build_object('event_id', l.event_id, 'from_sponsor', s.id, 'to_sponsor', _target, 'from_company', s.company_id, 'to_company', _company, 'reason', _reason));
  RETURN _target;
END;
$$;


ALTER FUNCTION "public"."intel_move_sponsorship"("_event_sponsor" "uuid", "_company" "uuid", "_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_overview"("_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "_country" "text" DEFAULT NULL::"text", "_industry" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _p jsonb;
  _c jsonb;
BEGIN
  PERFORM public._require_super_admin();
  WITH pp AS (
    SELECT p.* FROM people p
     WHERE p.merged_into IS NULL
       AND (_from IS NULL OR p.created_at >= _from) AND (_to IS NULL OR p.created_at < _to)
       AND (_country IS NULL OR lower(p.country) = lower(_country))
  )
  SELECT jsonb_build_object(
    'contacts', count(*),
    'unverified', count(*) FILTER (WHERE NOT EXISTS (SELECT 1 FROM person_emails e WHERE e.person_id = pp.id AND e.verified_at IS NOT NULL)),
    'incomplete', count(*) FILTER (WHERE pp.first_name IS NULL OR pp.last_name IS NULL OR pp.designation IS NULL OR pp.current_company_id IS NULL),
    'without_company', count(*) FILTER (WHERE pp.current_company_id IS NULL),
    'with_account', count(*) FILTER (WHERE pp.user_id IS NOT NULL),
    -- Quality: share of name, company, designation and a verified address present.
    'quality', COALESCE(round(100.0 * avg(
        ((pp.first_name IS NOT NULL AND pp.last_name IS NOT NULL)::int
       + (pp.current_company_id IS NOT NULL)::int
       + (pp.designation IS NOT NULL)::int
       + EXISTS (SELECT 1 FROM person_emails e WHERE e.person_id = pp.id AND e.verified_at IS NOT NULL)::int) / 4.0)), 0)
  ) INTO _p FROM pp;

  WITH cc AS (
    SELECT c.* FROM companies c
     WHERE c.merged_into IS NULL AND c.verification_status <> 'rejected'
       AND (_from IS NULL OR c.created_at >= _from) AND (_to IS NULL OR c.created_at < _to)
       AND (_country IS NULL OR lower(c.hq_country) = lower(_country))
       AND (_industry IS NULL OR lower(c.industry) = lower(_industry))
  )
  SELECT jsonb_build_object(
    'companies', count(*),
    'missing_domain', count(*) FILTER (WHERE NOT EXISTS (SELECT 1 FROM company_domains d WHERE d.company_id = cc.id)),
    'provisional', count(*) FILTER (WHERE cc.verification_status = 'provisional'),
    'incomplete', count(*) FILTER (WHERE cc.industry IS NULL OR cc.website IS NULL)
  ) INTO _c FROM cc;

  RETURN jsonb_build_object(
    'people', _p, 'companies', _c,
    'duplicate_contacts', (SELECT count(*) FROM identity_match_candidates m JOIN people a ON a.id = m.person_a JOIN people b ON b.id = m.person_b
                            WHERE m.status IN ('open','flagged') AND a.merged_into IS NULL AND b.merged_into IS NULL AND m.score >= 60),
    'duplicate_companies', (SELECT count(*) FROM company_match_candidates m JOIN companies a ON a.id = m.company_a JOIN companies b ON b.id = m.company_b
                            WHERE m.status IN ('open','flagged') AND a.merged_into IS NULL AND b.merged_into IS NULL AND m.score >= 60),
    'flagged', (SELECT count(*) FROM identity_match_candidates WHERE status = 'flagged') + (SELECT count(*) FROM company_match_candidates WHERE status = 'flagged'),
    'corrections_open', (SELECT count(*) FROM correction_suggestions WHERE status = 'open'),
    'corrections_safe', (SELECT count(*) FROM correction_suggestions WHERE status = 'open' AND safe),
    'association_suggestions', (SELECT count(*) FROM correction_suggestions WHERE status = 'open' AND kind IN ('conflicting','missing_domain')),
    'merges', (SELECT count(*) FROM merge_operations WHERE reverted_at IS NULL),
    'sponsors_unconnected', (SELECT count(*) FROM sponsors WHERE company_id IS NULL AND merged_into IS NULL),
    'sponsors_repeats', (SELECT COALESCE(sum(n - 1), 0) FROM (SELECT count(*) AS n FROM sponsors WHERE company_id IS NOT NULL AND merged_into IS NULL GROUP BY company_id, public._sponsor_scope(id) HAVING count(*) > 1) g),
    -- A connected company counts once, however many organisers have a record of it.
    'sponsor_identities', (SELECT count(DISTINCT company_id) + count(*) FILTER (WHERE company_id IS NULL) FROM sponsors WHERE merged_into IS NULL),
    'event_sponsorships', (SELECT count(*) FROM event_sponsors),
    'merge_recommendations',
      (SELECT count(*) FROM identity_match_candidates m JOIN people a ON a.id = m.person_a JOIN people b ON b.id = m.person_b
        WHERE m.status = 'open' AND a.merged_into IS NULL AND b.merged_into IS NULL AND m.score >= 80)
    + (SELECT count(*) FROM company_match_candidates m JOIN companies a ON a.id = m.company_a JOIN companies b ON b.id = m.company_b
        WHERE m.status = 'open' AND a.merged_into IS NULL AND b.merged_into IS NULL AND m.score >= 80)
    + (SELECT count(*) FROM (SELECT 1 FROM sponsors WHERE company_id IS NOT NULL AND merged_into IS NULL GROUP BY company_id, public._sponsor_scope(id) HAVING count(*) > 1) g)
  );
END;
$$;


ALTER FUNCTION "public"."intel_overview"("_from" timestamp with time zone, "_to" timestamp with time zone, "_country" "text", "_industry" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_refresh_company_duplicates"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _n integer;
BEGIN
  PERFORM public._require_super_admin();
  WITH live AS (SELECT * FROM companies WHERE merged_into IS NULL AND verification_status <> 'rejected'),
  signals AS (
    SELECT a.id ca, b.id cb, 60 w, 'same_name' why FROM live a JOIN live b ON a.name_key = b.name_key AND a.id < b.id
    UNION ALL
    SELECT LEAST(a.id, x.company_id), GREATEST(a.id, x.company_id), 50, 'alias'
      FROM live a JOIN company_aliases x ON x.alias_key = a.name_key AND x.company_id <> a.id
    UNION ALL
    SELECT LEAST(a.id, b.id), GREATEST(a.id, b.id), 35, 'initials'
      FROM live a JOIN live b ON a.id <> b.id AND length(a.name_key) BETWEEN 2 AND 6 AND a.name_key !~ ' '
       AND a.name_key = public._company_initials(b.name_key) AND b.name_key ~ ' '
    UNION ALL
    -- Nearly the same name; spelling slips and small additions.
    SELECT a.id, b.id, 45, 'similar_name'
      FROM live a JOIN live b ON a.id < b.id AND left(a.name_key, 3) = left(b.name_key, 3) AND a.name_key <> b.name_key
     WHERE public._intel_name_similarity(a.name_key, b.name_key) >= 0.6
  ),
  pairs AS (SELECT DISTINCT ca, cb FROM signals),
  domain_conflict AS (
    SELECT p.ca, p.cb, -30, 'different_domains' FROM pairs p
     WHERE EXISTS (SELECT 1 FROM company_domains d WHERE d.company_id = p.ca)
       AND EXISTS (SELECT 1 FROM company_domains d WHERE d.company_id = p.cb)
       AND NOT EXISTS (SELECT 1 FROM company_domains d1 JOIN company_domains d2 ON split_part(d1.domain, '.', 1) = split_part(d2.domain, '.', 1)
                        WHERE d1.company_id = p.ca AND d2.company_id = p.cb)
  ),
  scored AS (
    SELECT ca, cb, GREATEST(0, LEAST(100, sum(w)))::int score,
           ARRAY_AGG(DISTINCT why ORDER BY why) FILTER (WHERE w > 0) reasons
      FROM (SELECT * FROM signals UNION ALL SELECT * FROM domain_conflict) s
     GROUP BY ca, cb
  )
  INSERT INTO company_match_candidates (company_a, company_b, reasons, score)
  SELECT s.ca, s.cb, s.reasons, s.score FROM scored s
   WHERE s.score >= 30
     AND s.ca IN (SELECT id FROM live) AND s.cb IN (SELECT id FROM live)
     -- separate legal entities: different identifiers of the same kind
     AND NOT EXISTS (SELECT 1 FROM company_identifiers i1 JOIN company_identifiers i2 ON i1.scheme = i2.scheme AND i1.value <> i2.value
                      WHERE i1.company_id = s.ca AND i2.company_id = s.cb)
     -- parent and subsidiary
     AND NOT EXISTS (SELECT 1 FROM companies c WHERE (c.id = s.ca AND c.parent_company_id = s.cb) OR (c.id = s.cb AND c.parent_company_id = s.ca))
  ON CONFLICT (company_a, company_b) DO UPDATE SET score = EXCLUDED.score, reasons = EXCLUDED.reasons;
  GET DIAGNOSTICS _n = ROW_COUNT;
  RETURN _n;
END;
$$;


ALTER FUNCTION "public"."intel_refresh_company_duplicates"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_refresh_person_duplicates"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _n integer;
BEGIN
  PERFORM public._require_super_admin();
  WITH live AS (SELECT * FROM people WHERE merged_into IS NULL),
  -- Keys worked out once, so names are matched by a hash join rather than by
  -- comparing every contact with every other.
  name_parts AS MATERIALIZED (
    SELECT id, public.person_name_key(first_name) fk, public.person_name_key(last_name) lk
      FROM live WHERE first_name IS NOT NULL AND last_name IS NOT NULL
  ),
  company_keys AS (
    SELECT x.person_id, x.k FROM (
      SELECT r.person_id, public.company_name_key(r.company) k FROM registrations r WHERE r.person_id IS NOT NULL
      UNION SELECT s.person_id, public.company_name_key(s.company) FROM speakers s WHERE s.person_id IS NOT NULL
      UNION SELECT m.person_id, public.company_name_key(m.company) FROM sponsor_members m WHERE m.person_id IS NOT NULL
      UNION SELECT l.id, c.name_key FROM live l JOIN companies c ON c.id = l.current_company_id
    ) x WHERE x.k <> ''
  ),
  signals AS (
    SELECT LEAST(a.person_id, b.person_id) pa, GREATEST(a.person_id, b.person_id) pb,
           CASE WHEN a.verified_at IS NOT NULL AND b.verified_at IS NOT NULL THEN 70 ELSE 50 END w, 'phone' why
      FROM person_phones a JOIN person_phones b ON a.phone_e164 = b.phone_e164 AND a.person_id < b.person_id
    UNION ALL
    SELECT LEAST(a.person_id, b.person_id), GREATEST(a.person_id, b.person_id), 60, 'linkedin'
      FROM person_links a JOIN person_links b ON a.kind = 'linkedin' AND b.kind = 'linkedin' AND a.url_key = b.url_key AND a.person_id < b.person_id
    UNION ALL
    SELECT a.id, b.id, 25, 'same_name'
      FROM live a JOIN live b ON a.name_key = b.name_key AND a.id < b.id
     WHERE a.name_key LIKE '% %'
    UNION ALL
    SELECT LEAST(a.id, b.id), GREATEST(a.id, b.id), 20, 'swapped_name'
      FROM name_parts a JOIN name_parts b ON a.fk = b.lk AND a.lk = b.fk AND a.id <> b.id
     WHERE a.fk <> '' AND a.lk <> '' AND a.fk <> a.lk
    UNION ALL
    -- Nearly the same name at the same company. Only looked for within a
    -- company, so one common name elsewhere is never a signal.
    SELECT DISTINCT LEAST(a.id, b.id), GREATEST(a.id, b.id), 45, 'similar_name'
      FROM company_keys x JOIN company_keys y ON x.k = y.k AND x.person_id < y.person_id
      JOIN live a ON a.id = x.person_id JOIN live b ON b.id = y.person_id
     WHERE a.name_key <> '' AND b.name_key <> '' AND a.name_key <> b.name_key
       AND left(a.name_key, 1) = left(b.name_key, 1)
       AND public._intel_name_similarity(a.name_key, b.name_key) >= 0.6
  ),
  named AS (SELECT DISTINCT pa, pb FROM signals),
  extra AS (
    SELECT n.pa, n.pb, 20, 'same_company' FROM named n
     WHERE EXISTS (SELECT 1 FROM company_keys x JOIN company_keys y ON x.k = y.k WHERE x.person_id = n.pa AND y.person_id = n.pb)
    UNION ALL
    SELECT n.pa, n.pb, 5, 'same_designation' FROM named n JOIN live a ON a.id = n.pa JOIN live b ON b.id = n.pb
     WHERE lower(public.norm_text(a.designation)) = lower(public.norm_text(b.designation)) AND a.designation IS NOT NULL
  ),
  scored AS (
    SELECT pa, pb, LEAST(100, sum(w))::int score, ARRAY_AGG(DISTINCT why ORDER BY why) reasons
      FROM (SELECT * FROM signals UNION ALL SELECT * FROM extra) s
     WHERE pa IN (SELECT id FROM live) AND pb IN (SELECT id FROM live)
     GROUP BY pa, pb
  )
  INSERT INTO identity_match_candidates (person_a, person_b, reasons, score)
  SELECT pa, pb, reasons, score FROM scored WHERE score >= 40
  ON CONFLICT (person_a, person_b) DO UPDATE
    SET score = EXCLUDED.score,
        reasons = ARRAY(SELECT DISTINCT r FROM unnest(identity_match_candidates.reasons || EXCLUDED.reasons) r ORDER BY r);
  GET DIAGNOSTICS _n = ROW_COUNT;
  RETURN _n;
END;
$$;


ALTER FUNCTION "public"."intel_refresh_person_duplicates"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_revert_change"("_history" "uuid", "_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid uuid := public._require_super_admin();
  h    intel_field_history%ROWTYPE;
  _cur text;
BEGIN
  SELECT * INTO h FROM intel_field_history WHERE id = _history FOR UPDATE;
  IF NOT FOUND OR h.reverted_at IS NOT NULL OR h.source IN ('rollback','merge')
     OR NOT public._intel_field_allowed(h.entity_type, h.field) THEN
    RAISE EXCEPTION 'This change cannot be reverted here' USING ERRCODE = '22023';
  END IF;
  _cur := CASE h.entity_type
            WHEN 'person'  THEN (SELECT to_jsonb(x) ->> h.field FROM people x WHERE x.id = h.entity_id)
            ELSE (SELECT to_jsonb(x) ->> h.field FROM companies x WHERE x.id = h.entity_id) END;
  IF _cur IS DISTINCT FROM h.new_value THEN
    RAISE EXCEPTION 'The field has changed again since; revert the later change first' USING ERRCODE = '40001';
  END IF;
  PERFORM public._intel_set_field(h.entity_type, h.entity_id, h.field, h.old_value, 'rollback', COALESCE(_reason, 'Reverted'), _uid);
  UPDATE intel_field_history SET reverted_at = now(), reverted_by = _uid WHERE id = h.id;
  INSERT INTO audit_logs (actor_id, action, target_type, target_id, details)
  VALUES (_uid, 'intel.change_reverted', h.entity_type, h.entity_id::text,
          jsonb_build_object('history_id', h.id, 'field', h.field, 'restored', h.old_value, 'replaced', h.new_value, 'reason', _reason));
END;
$$;


ALTER FUNCTION "public"."intel_revert_change"("_history" "uuid", "_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_revert_merge"("_merge" "uuid", "_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  _uid uuid := public._require_super_admin();
  m    merge_operations%ROWTYPE;
  x    jsonb;
  _tbl text;
  _ref text;
  f    text;
BEGIN
  SELECT * INTO m FROM merge_operations WHERE id = _merge FOR UPDATE;
  IF NOT FOUND OR m.reverted_at IS NOT NULL THEN RAISE EXCEPTION 'This merge cannot be rolled back' USING ERRCODE = '22023'; END IF;
  IF EXISTS (SELECT 1 FROM intel_field_history h WHERE h.entity_type = m.entity_type AND h.entity_id = m.survivor_id
              AND h.created_at > m.created_at AND h.merge_id IS DISTINCT FROM m.id AND h.reverted_at IS NULL
              -- an entry that undid a later edit restores what the merge left
              AND h.source <> 'rollback') THEN
    RAISE EXCEPTION 'The surviving record was edited after this merge; revert those changes first' USING ERRCODE = '40001';
  END IF;
  IF EXISTS (SELECT 1 FROM merge_operations o WHERE o.reverted_at IS NULL AND o.created_at > m.created_at AND o.entity_type = m.entity_type
              AND (o.survivor_id = ANY (m.merged_ids || m.survivor_id) OR o.merged_ids && (m.merged_ids || m.survivor_id))) THEN
    RAISE EXCEPTION 'A later merge involves these records; roll that back first' USING ERRCODE = '40001';
  END IF;

  IF m.entity_type = 'sponsor' THEN
    PERFORM public._intel_revert_sponsor_merge(m.id, _reason, _uid);
    RETURN;
  END IF;
  -- Sponsor records combined after this company merge come apart first.
  IF m.entity_type = 'company' AND EXISTS (
       SELECT 1 FROM merge_operations o JOIN sponsors s ON s.id = o.survivor_id
        WHERE o.entity_type = 'sponsor' AND o.reverted_at IS NULL AND o.created_at > m.created_at AND s.company_id = m.survivor_id) THEN
    RAISE EXCEPTION 'Sponsor records were merged after this; roll those back first' USING ERRCODE = '40001';
  END IF;

  _ref := CASE m.entity_type WHEN 'person' THEN 'person_id' ELSE 'company_id' END;
  FOR x IN SELECT * FROM jsonb_array_elements(m.moved) LOOP
    _tbl := x ->> 'table';
    IF _tbl = 'company_aliases_added' THEN
      DELETE FROM company_aliases WHERE id = (x ->> 'id')::uuid;
    ELSIF _tbl = 'companies_parent_of_survivor' THEN
      UPDATE companies SET parent_company_id = (x ->> 'from')::uuid WHERE id = m.survivor_id;
    ELSIF _tbl = 'company_mentions' AND m.entity_type = 'person' THEN
      UPDATE company_mentions SET person_id = (x ->> 'from')::uuid
       WHERE company_id = (x ->> 'company_id')::uuid AND person_id = m.survivor_id;
    ELSIF _tbl = 'company_mentions' THEN
      UPDATE company_mentions SET company_id = (x ->> 'from')::uuid
       WHERE person_id = (x ->> 'person_id')::uuid AND company_id = m.survivor_id;
    ELSIF _tbl = 'people' AND m.entity_type = 'company' THEN
      UPDATE people SET current_company_id = (x ->> 'from')::uuid WHERE id = (x ->> 'id')::uuid AND current_company_id = m.survivor_id;
    ELSIF _tbl = 'companies' THEN
      UPDATE companies SET parent_company_id = (x ->> 'from')::uuid WHERE id = (x ->> 'id')::uuid AND parent_company_id = m.survivor_id;
    ELSE
      EXECUTE format('UPDATE public.%I SET %I = $1 WHERE id = $2 AND %I = $3', _tbl, _ref, _ref)
        USING (x ->> 'from')::uuid, (x ->> 'id')::uuid, m.survivor_id;
    END IF;
  END LOOP;
  FOR x IN SELECT * FROM jsonb_array_elements(m.removed) LOOP
    EXECUTE format('INSERT INTO public.%I SELECT * FROM jsonb_populate_record(NULL::public.%I, $1) ON CONFLICT DO NOTHING',
                   x ->> 'table', x ->> 'table') USING x -> 'row';
  END LOOP;

  -- The survivor's fields as they were, recorded as a rollback.
  FOR f IN SELECT jsonb_object_keys(m.field_choices) LOOP
    PERFORM public._intel_set_field(m.entity_type, m.survivor_id, f, m.survivor_before ->> f, 'rollback',
                                    COALESCE(_reason, 'Merge rolled back'), _uid, m.id);
  END LOOP;
  UPDATE intel_field_history SET reverted_at = now(), reverted_by = _uid
   WHERE merge_id = m.id AND source = 'merge';

  IF m.entity_type = 'person' THEN
    UPDATE people SET merged_into = NULL, updated_at = now() WHERE id = ANY (m.merged_ids) AND merged_into = m.survivor_id;
    UPDATE companies c SET entry_count = (SELECT count(*) FROM company_mentions cm WHERE cm.company_id = c.id)
     WHERE c.id IN (SELECT company_id FROM company_mentions WHERE person_id = ANY (m.merged_ids || m.survivor_id));
  ELSE
    UPDATE companies SET merged_into = NULL, updated_at = now() WHERE id = ANY (m.merged_ids) AND merged_into = m.survivor_id;
    UPDATE companies c SET entry_count = (SELECT count(*) FROM company_mentions cm WHERE cm.company_id = c.id)
     WHERE c.id = ANY (m.merged_ids || m.survivor_id);
  END IF;

  -- These records are separate again, so their suggestions are open again.
  IF m.entity_type = 'person' THEN
    UPDATE identity_match_candidates SET status = 'open', reviewed_by = NULL, reviewed_at = NULL
     WHERE status = 'merged' AND person_a = ANY (m.merged_ids || m.survivor_id) AND person_b = ANY (m.merged_ids || m.survivor_id);
  ELSE
    UPDATE company_match_candidates SET status = 'open', reviewed_by = NULL, reviewed_at = NULL
     WHERE status = 'merged' AND company_a = ANY (m.merged_ids || m.survivor_id) AND company_b = ANY (m.merged_ids || m.survivor_id);
  END IF;
  UPDATE merge_operations SET reverted_at = now(), reverted_by = _uid WHERE id = m.id;
  INSERT INTO audit_logs (actor_id, action, target_type, target_id, details)
  VALUES (_uid, 'intel.merge_reverted', m.entity_type, m.survivor_id::text,
          jsonb_build_object('merge_id', m.id, 'restored', m.merged_ids, 'reason', _reason));
END;
$_$;


ALTER FUNCTION "public"."intel_revert_merge"("_merge" "uuid", "_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_review_correction"("_id" "uuid", "_approve" boolean, "_value" "text" DEFAULT NULL::"text", "_reason" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid uuid := public._require_super_admin();
  s    correction_suggestions%ROWTYPE;
  _v   text;
  _cur text;
BEGIN
  SELECT * INTO s FROM correction_suggestions WHERE id = _id FOR UPDATE;
  IF NOT FOUND OR s.status <> 'open' THEN RAISE EXCEPTION 'This suggestion is no longer open' USING ERRCODE = '22023'; END IF;
  IF NOT _approve THEN
    UPDATE correction_suggestions SET status = 'rejected', reviewed_by = _uid, reviewed_at = now() WHERE id = _id;
    INSERT INTO audit_logs (actor_id, action, target_type, target_id, details)
    VALUES (_uid, 'intel.correction_rejected', s.entity_type, s.entity_id::text,
            jsonb_build_object('field', s.field, 'kind', s.kind, 'current', s.current_value, 'suggested', s.suggested_value, 'reason', _reason));
    RETURN 'rejected';
  END IF;
  _v := COALESCE(NULLIF(public.norm_text(_value), ''), s.suggested_value);
  IF _v IS NULL THEN RAISE EXCEPTION 'Enter the value to apply' USING ERRCODE = '22023'; END IF;
  -- Refuse if the field changed after the suggestion was made.
  _cur := CASE s.entity_type
            WHEN 'person'  THEN (SELECT to_jsonb(x) ->> s.field FROM people x WHERE x.id = s.entity_id)
            ELSE (SELECT to_jsonb(x) ->> s.field FROM companies x WHERE x.id = s.entity_id) END;
  IF _cur IS DISTINCT FROM s.current_value THEN
    UPDATE correction_suggestions SET status = 'stale' WHERE id = _id;
    RAISE EXCEPTION 'The field changed since this was suggested; review it again' USING ERRCODE = '40001';
  END IF;
  IF s.kind = 'swapped_names' THEN
    PERFORM public._intel_set_field('person', s.entity_id, 'last_name', s.current_value, 'correction', COALESCE(_reason, s.reason), _uid);
  END IF;
  PERFORM public._intel_set_field(s.entity_type, s.entity_id, s.field, _v, 'correction', COALESCE(_reason, s.reason), _uid);
  UPDATE correction_suggestions SET status = 'approved', suggested_value = _v, reviewed_by = _uid, reviewed_at = now() WHERE id = _id;
  INSERT INTO audit_logs (actor_id, action, target_type, target_id, details)
  VALUES (_uid, 'intel.correction_approved', s.entity_type, s.entity_id::text,
          jsonb_build_object('field', s.field, 'kind', s.kind, 'from', s.current_value, 'to', _v, 'edited', _value IS NOT NULL));
  RETURN 'approved';
END;
$$;


ALTER FUNCTION "public"."intel_review_correction"("_id" "uuid", "_approve" boolean, "_value" "text", "_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_search_companies"("_q" "text" DEFAULT NULL::"text", "_limit" integer DEFAULT 50, "_offset" integer DEFAULT 0, "_filter" "text" DEFAULT 'all'::"text", "_sort" "text" DEFAULT 'entries'::"text", "_dir" "text" DEFAULT 'desc'::"text", "_country" "text" DEFAULT NULL::"text", "_industry" "text" DEFAULT NULL::"text") RETURNS TABLE("company_id" "uuid", "name" "text", "website" "text", "industry" "text", "hq_country" "text", "verification_status" "text", "source" "text", "contacts" integer, "entry_count" integer, "domains" "text"[], "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _k text := public.company_name_key(_q);
  _d text := lower(public.norm_text(_q));
BEGIN
  PERFORM public._require_super_admin();
  RETURN QUERY
  WITH m AS (
    SELECT c.* FROM companies c
     WHERE c.merged_into IS NULL
       AND (_d = '' OR c.id::text = _d
            OR (_k <> '' AND (c.name_key LIKE '%' || _k || '%'
                              OR EXISTS (SELECT 1 FROM company_aliases a WHERE a.company_id = c.id AND a.alias_key LIKE '%' || _k || '%')))
            OR EXISTS (SELECT 1 FROM company_domains d WHERE d.company_id = c.id AND d.domain LIKE '%' || _d || '%')
            OR EXISTS (SELECT 1 FROM company_identifiers i WHERE i.company_id = c.id AND lower(i.value) = _d))
       AND CASE _filter
             WHEN 'no_domain'  THEN NOT EXISTS (SELECT 1 FROM company_domains d WHERE d.company_id = c.id)
             WHEN 'incomplete' THEN c.industry IS NULL OR c.website IS NULL OR c.hq_country IS NULL
             WHEN 'verified'   THEN c.verification_status = 'verified'
             WHEN 'provisional' THEN c.verification_status = 'provisional'
             WHEN 'has_sponsors' THEN EXISTS (SELECT 1 FROM sponsors s WHERE s.company_id = c.id)
             WHEN 'possible_duplicate' THEN EXISTS (SELECT 1 FROM company_match_candidates d WHERE d.status IN ('open','flagged') AND (d.company_a = c.id OR d.company_b = c.id))
             ELSE true END
       AND (NULLIF(btrim(_country), '') IS NULL OR lower(c.hq_country) = lower(btrim(_country)))
       AND (NULLIF(btrim(_industry), '') IS NULL OR lower(c.industry) = lower(btrim(_industry)))
  )
  SELECT m.id, m.name, m.website, m.industry, m.hq_country, m.verification_status, m.source,
         (SELECT count(DISTINCT pp.id)::int FROM people pp WHERE pp.current_company_id = m.id AND pp.merged_into IS NULL),
         m.entry_count,
         ARRAY(SELECT d.domain FROM company_domains d WHERE d.company_id = m.id ORDER BY d.domain),
         m.created_at, m.updated_at, count(*) OVER ()
    FROM m
    CROSS JOIN LATERAL (SELECT CASE _sort
        WHEN 'name' THEN lower(m.name)
        WHEN 'industry' THEN lower(m.industry)
        WHEN 'contacts' THEN lpad((SELECT count(*) FROM people pp WHERE pp.current_company_id = m.id AND pp.merged_into IS NULL)::text, 10, '0')
        WHEN 'created' THEN m.created_at::text
        WHEN 'updated' THEN m.updated_at::text
        ELSE lpad(m.entry_count::text, 10, '0') END AS k) o
   ORDER BY CASE WHEN lower(_dir) = 'asc' THEN o.k END ASC NULLS LAST,
            CASE WHEN lower(_dir) <> 'asc' THEN o.k END DESC NULLS LAST, m.name, m.id
   LIMIT LEAST(GREATEST(COALESCE(_limit, 50), 1), 200) OFFSET GREATEST(COALESCE(_offset, 0), 0);
END;
$$;


ALTER FUNCTION "public"."intel_search_companies"("_q" "text", "_limit" integer, "_offset" integer, "_filter" "text", "_sort" "text", "_dir" "text", "_country" "text", "_industry" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_search_contacts"("_q" "text" DEFAULT NULL::"text", "_limit" integer DEFAULT 50, "_offset" integer DEFAULT 0, "_filter" "text" DEFAULT 'all'::"text", "_sort" "text" DEFAULT 'updated'::"text", "_dir" "text" DEFAULT 'desc'::"text", "_country" "text" DEFAULT NULL::"text") RETURNS TABLE("person_id" "uuid", "display_name" "text", "first_name" "text", "last_name" "text", "email" "text", "phone" "text", "company" "text", "designation" "text", "has_account" boolean, "registrations" integer, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _t  text := lower(public.norm_text(_q));
  _nk text := public.person_name_key(_q);
  _ph text := regexp_replace(COALESCE(_q, ''), '[^0-9]', '', 'g');
BEGIN
  PERFORM public._require_super_admin();
  RETURN QUERY
  WITH m AS (
    SELECT p.* FROM people p
     WHERE p.merged_into IS NULL
       AND (_t = '' OR p.id::text = _t
            OR (_nk <> '' AND p.name_key LIKE '%' || _nk || '%')
            OR EXISTS (SELECT 1 FROM person_emails e WHERE e.person_id = p.id AND e.email_key LIKE '%' || _t || '%')
            OR (length(_ph) >= 5 AND EXISTS (SELECT 1 FROM person_phones ph WHERE ph.person_id = p.id AND ph.phone_e164 LIKE '%' || _ph || '%'))
            OR EXISTS (SELECT 1 FROM person_links l WHERE l.person_id = p.id AND l.url_key LIKE '%' || _t || '%')
            OR lower(COALESCE(p.designation, '')) LIKE '%' || _t || '%'
            OR EXISTS (SELECT 1 FROM companies c WHERE c.id = p.current_company_id AND c.name_key LIKE '%' || public.company_name_key(_q) || '%' AND public.company_name_key(_q) <> ''))
       AND CASE _filter
             WHEN 'no_company' THEN p.current_company_id IS NULL
             WHEN 'incomplete' THEN p.first_name IS NULL OR p.last_name IS NULL OR p.designation IS NULL OR p.current_company_id IS NULL
             WHEN 'unverified' THEN NOT EXISTS (SELECT 1 FROM person_emails e WHERE e.person_id = p.id AND e.verified_at IS NOT NULL)
             WHEN 'with_account' THEN p.user_id IS NOT NULL
             WHEN 'possible_duplicate' THEN EXISTS (SELECT 1 FROM identity_match_candidates d WHERE d.status IN ('open','flagged') AND (d.person_a = p.id OR d.person_b = p.id))
             ELSE true END
       AND (NULLIF(btrim(_country), '') IS NULL OR lower(p.country) = lower(btrim(_country)))
  )
  SELECT m.id, m.display_name, m.first_name, m.last_name,
         (SELECT e.email FROM person_emails e WHERE e.person_id = m.id ORDER BY e.verified_at IS NULL, e.created_at LIMIT 1),
         (SELECT ph.phone_e164 FROM person_phones ph WHERE ph.person_id = m.id ORDER BY ph.verified_at IS NULL, ph.created_at LIMIT 1),
         (SELECT c.name FROM companies c WHERE c.id = m.current_company_id),
         m.designation, m.user_id IS NOT NULL,
         (SELECT count(*)::int FROM registrations r WHERE r.person_id = m.id),
         m.created_at, m.updated_at, count(*) OVER ()
    FROM m
    CROSS JOIN LATERAL (SELECT CASE _sort
        WHEN 'name' THEN lower(m.display_name)
        WHEN 'designation' THEN lower(m.designation)
        WHEN 'company' THEN (SELECT lower(c.name) FROM companies c WHERE c.id = m.current_company_id)
        WHEN 'events' THEN lpad((SELECT count(*) FROM registrations r WHERE r.person_id = m.id)::text, 10, '0')
        WHEN 'created' THEN m.created_at::text
        ELSE m.updated_at::text END AS k) o
   ORDER BY CASE WHEN lower(_dir) = 'asc' THEN o.k END ASC NULLS LAST,
            CASE WHEN lower(_dir) <> 'asc' THEN o.k END DESC NULLS LAST, m.id
   LIMIT LEAST(GREATEST(COALESCE(_limit, 50), 1), 200) OFFSET GREATEST(COALESCE(_offset, 0), 0);
END;
$$;


ALTER FUNCTION "public"."intel_search_contacts"("_q" "text", "_limit" integer, "_offset" integer, "_filter" "text", "_sort" "text", "_dir" "text", "_country" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_search_sponsors"("_q" "text" DEFAULT NULL::"text", "_limit" integer DEFAULT 25, "_offset" integer DEFAULT 0, "_filter" "text" DEFAULT 'all'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _k text := COALESCE(public.company_name_key(_q), '');
  _t text := lower(COALESCE(public.norm_text(_q), ''));
BEGIN
  PERFORM public._require_super_admin();
  RETURN (
    WITH m AS (
      SELECT s.*, (SELECT lower(c.name) FROM companies c WHERE c.id = s.company_id) AS company_sort FROM sponsors s
       WHERE s.merged_into IS NULL
         AND (_t = '' OR s.id::text = _t OR public.company_name_key(s.name) LIKE '%' || _k || '%'
              OR lower(COALESCE(s.email, '')) LIKE '%' || _t || '%' OR lower(COALESCE(s.website, '')) LIKE '%' || _t || '%')
         AND CASE _filter
               WHEN 'unconnected' THEN s.company_id IS NULL
               WHEN 'repeats' THEN s.company_id IS NOT NULL AND EXISTS (SELECT 1 FROM sponsors o WHERE o.company_id = s.company_id AND o.id <> s.id AND o.merged_into IS NULL)
               ELSE true END
    ), page AS (
      -- Repeats read best side by side, so they are grouped by company.
      SELECT * FROM m ORDER BY CASE WHEN _filter = 'repeats' THEN m.company_sort END, lower(m.name), m.id
       LIMIT LEAST(GREATEST(COALESCE(_limit, 25), 1), 200) OFFSET GREATEST(COALESCE(_offset, 0), 0)
    )
    SELECT jsonb_build_object(
      'total', (SELECT count(*) FROM m),
      'rows', COALESCE((SELECT jsonb_agg(jsonb_build_object(
          'id', p.id, 'name', p.name, 'email', p.email, 'website', p.website, 'logo_url', p.logo_url,
          'company_id', p.company_id, 'company', (SELECT c.name FROM companies c WHERE c.id = p.company_id),
          'same_company', (SELECT count(*) FROM sponsors o WHERE p.company_id IS NOT NULL AND o.company_id = p.company_id AND o.id <> p.id AND o.merged_into IS NULL),
          'same_owner', ARRAY(SELECT o.id FROM sponsors o WHERE p.company_id IS NOT NULL AND o.company_id = p.company_id AND o.id <> p.id AND o.merged_into IS NULL
                               AND (o.user_id IS NOT DISTINCT FROM p.user_id OR public._sponsor_scope(o.id) = public._sponsor_scope(p.id))),
          'events', (SELECT count(*) FROM event_sponsors es WHERE es.sponsor_id = p.id),
          'sponsorships', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', es.id, 'event', e.title, 'date', e.date, 'tier', es.tier, 'tier_label', es.tier_label) ORDER BY e.date DESC NULLS LAST)
                             FROM event_sponsors es JOIN events e ON e.id = es.event_id WHERE es.sponsor_id = p.id), '[]'::jsonb),
          'team', (SELECT count(*) FROM sponsor_members sm WHERE sm.sponsor_id = p.id),
          'created_by', (SELECT u.email FROM auth.users u WHERE u.id = p.user_id))
          ORDER BY CASE WHEN _filter = 'repeats' THEN p.company_sort END, lower(p.name), p.id) FROM page p), '[]'::jsonb))
  );
END;
$$;


ALTER FUNCTION "public"."intel_search_sponsors"("_q" "text", "_limit" integer, "_offset" integer, "_filter" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_set_duplicate_status"("_entity" "text", "_id" "uuid", "_status" "text", "_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _uid uuid := public._require_super_admin();
BEGIN
  IF _entity = 'person' THEN
    IF _status NOT IN ('open','different_people','ignored','flagged') THEN RAISE EXCEPTION 'Unknown decision' USING ERRCODE = '22023'; END IF;
    UPDATE identity_match_candidates SET status = _status, reviewed_by = _uid, reviewed_at = now() WHERE id = _id;
  ELSIF _entity = 'company' THEN
    IF _status NOT IN ('open','different_companies','ignored','flagged') THEN RAISE EXCEPTION 'Unknown decision' USING ERRCODE = '22023'; END IF;
    UPDATE company_match_candidates SET status = _status, reviewed_by = _uid, reviewed_at = now() WHERE id = _id;
  ELSE
    RAISE EXCEPTION 'Unknown record type' USING ERRCODE = '22023';
  END IF;
  IF NOT FOUND THEN RAISE EXCEPTION 'Suggestion not found' USING ERRCODE = 'P0002'; END IF;
  INSERT INTO audit_logs (actor_id, action, target_type, target_id, details)
  VALUES (_uid, 'intel.duplicate_' || _status, _entity || '_match', _id::text, jsonb_build_object('reason', _reason));
END;
$$;


ALTER FUNCTION "public"."intel_set_duplicate_status"("_entity" "text", "_id" "uuid", "_status" "text", "_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_set_duplicate_statuses"("_entity" "text", "_ids" "uuid"[], "_status" "text", "_reason" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _id uuid;
  _n  integer := 0;
BEGIN
  PERFORM public._require_super_admin();
  FOREACH _id IN ARRAY COALESCE(_ids, '{}') LOOP
    PERFORM public.intel_set_duplicate_status(_entity, _id, _status, _reason);
    _n := _n + 1;
  END LOOP;
  RETURN _n;
END;
$$;


ALTER FUNCTION "public"."intel_set_duplicate_statuses"("_entity" "text", "_ids" "uuid"[], "_status" "text", "_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_sponsor_companies"("_q" "text" DEFAULT NULL::"text", "_limit" integer DEFAULT 25, "_offset" integer DEFAULT 0, "_filter" "text" DEFAULT 'all'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _k text := COALESCE(public.company_name_key(_q), '');
  _t text := lower(COALESCE(public.norm_text(_q), ''));
BEGIN
  PERFORM public._require_super_admin();
  RETURN (
    WITH live AS (
      SELECT s.*, public._sponsor_scope(s.id) AS scope, COALESCE(s.company_id::text, s.id::text) AS grp FROM sponsors s WHERE s.merged_into IS NULL
    ), grouped AS (
      SELECT l.grp, max(l.company_id::text)::uuid AS company_id, count(*) AS records,
             lower(COALESCE((SELECT c.name FROM companies c WHERE c.id = max(l.company_id::text)::uuid), btrim(min(l.name)))) AS sort_name,
             COALESCE((SELECT c.name FROM companies c WHERE c.id = max(l.company_id::text)::uuid), btrim(min(l.name))) AS name
        FROM live l
       WHERE _t = '' OR EXISTS (SELECT 1 FROM live o WHERE o.grp = l.grp
               AND (public.company_name_key(o.name) LIKE '%' || _k || '%' OR lower(COALESCE(o.email, '')) LIKE '%' || _t || '%' OR lower(COALESCE(o.website, '')) LIKE '%' || _t || '%'))
       GROUP BY l.grp
    ), q AS (
      SELECT g.* FROM grouped g
       WHERE CASE _filter WHEN 'unconnected' THEN g.company_id IS NULL WHEN 'repeats' THEN g.records > 1 ELSE true END
    ), page AS (
      SELECT * FROM q ORDER BY q.sort_name, q.grp
       LIMIT LEAST(GREATEST(COALESCE(_limit, 25), 1), 200) OFFSET GREATEST(COALESCE(_offset, 0), 0)
    )
    SELECT jsonb_build_object(
      'total', (SELECT count(*) FROM q),
      -- How many records Combine all would fold in.
      'combinable', (SELECT COALESCE(sum(n - 1), 0) FROM (SELECT count(*) AS n FROM live WHERE company_id IS NOT NULL GROUP BY company_id, scope HAVING count(*) > 1) x),
      'rows', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'key', p.grp, 'company_id', p.company_id, 'name', p.name, 'record_count', p.records,
        'domains', ARRAY(SELECT d.domain FROM company_domains d WHERE d.company_id = p.company_id ORDER BY d.domain),
        'records', (SELECT jsonb_agg(jsonb_build_object('id', l.id, 'name', btrim(l.name), 'email', l.email, 'website', l.website,
                      'owner', (SELECT u.email FROM auth.users u WHERE u.id = l.user_id),
                      'events', (SELECT count(*) FROM event_sponsors es WHERE es.sponsor_id = l.id),
                      'team', (SELECT count(*) FROM sponsor_members m WHERE m.sponsor_id = l.id)) ORDER BY l.created_at, l.id)
                      FROM live l WHERE l.grp = p.grp),
        -- Sets of records that can become one; records outside them belong to other organisations.
        'combine_sets', COALESCE((SELECT jsonb_agg(x.ids) FROM (
                      SELECT ARRAY_AGG(l.id ORDER BY (SELECT count(*) FROM event_sponsors es WHERE es.sponsor_id = l.id) DESC, l.created_at, l.id) AS ids
                        FROM live l WHERE l.grp = p.grp AND p.company_id IS NOT NULL GROUP BY l.scope HAVING count(*) > 1) x), '[]'::jsonb),
        'organisations', (SELECT count(DISTINCT l.scope) FROM live l WHERE l.grp = p.grp),
        'team', (SELECT count(*) FROM sponsor_members m JOIN live l ON l.id = m.sponsor_id WHERE l.grp = p.grp),
        'sponsorships', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', es.id, 'event', e.title, 'date', e.date, 'tier', es.tier, 'tier_label', es.tier_label,
                      'sponsor_id', l.id, 'owner', (SELECT u.email FROM auth.users u WHERE u.id = l.user_id)) ORDER BY e.date DESC NULLS LAST, es.id)
                      FROM live l JOIN event_sponsors es ON es.sponsor_id = l.id JOIN events e ON e.id = es.event_id WHERE l.grp = p.grp), '[]'::jsonb))
        ORDER BY p.sort_name, p.grp) FROM page p), '[]'::jsonb))
  );
END;
$$;


ALTER FUNCTION "public"."intel_sponsor_companies"("_q" "text", "_limit" integer, "_offset" integer, "_filter" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_sponsor_merge_preview"("_survivor" "uuid", "_others" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _all uuid[] := _others || _survivor;
BEGIN
  PERFORM public._require_super_admin();
  RETURN jsonb_build_object(
    'records', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', s.id, 'name', s.name, 'email', s.email, 'website', s.website, 'logo_url', s.logo_url,
        'description', s.description, 'company_id', s.company_id, 'company', (SELECT c.name FROM companies c WHERE c.id = s.company_id), 'user_id', s.user_id,
        'owner', (SELECT u.email FROM auth.users u WHERE u.id = s.user_id), 'created_at', s.created_at,
        'team', (SELECT count(*) FROM sponsor_members m WHERE m.sponsor_id = s.id),
        'events', COALESCE((SELECT jsonb_agg(jsonb_build_object('event', e.title, 'date', e.date, 'tier', es.tier, 'tier_label', es.tier_label) ORDER BY e.date DESC NULLS LAST)
                      FROM event_sponsors es JOIN events e ON e.id = es.event_id WHERE es.sponsor_id = s.id), '[]'::jsonb)))
        FROM sponsors s WHERE s.id = ANY (_all)), '[]'::jsonb),
    'same_owner', (SELECT count(DISTINCT user_id) = 1 OR count(DISTINCT public._sponsor_scope(id)) = 1 FROM sponsors WHERE id = ANY (_all)),
    'same_company', (SELECT count(DISTINCT company_id) = 1 AND bool_and(company_id IS NOT NULL) FROM sponsors WHERE id = ANY (_all)),
    'conflicts', COALESCE((SELECT jsonb_agg(DISTINCT e.title)
        FROM event_sponsors a JOIN event_sponsors b ON a.event_id = b.event_id AND a.id < b.id JOIN events e ON e.id = a.event_id
       WHERE a.sponsor_id = ANY (_all) AND b.sponsor_id = ANY (_all)
         AND public._sponsorship_title(a.tier, a.tier_label) <> public._sponsorship_title(b.tier, b.tier_label)), '[]'::jsonb),
    'repeats', (SELECT count(*) FROM event_sponsors a JOIN event_sponsors b ON a.event_id = b.event_id AND a.id < b.id
       WHERE a.sponsor_id = ANY (_all) AND b.sponsor_id = ANY (_all)
         AND public._sponsorship_title(a.tier, a.tier_label) = public._sponsorship_title(b.tier, b.tier_label))
  );
END;
$$;


ALTER FUNCTION "public"."intel_sponsor_merge_preview"("_survivor" "uuid", "_others" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_sponsor_review"("_kind" "text" DEFAULT NULL::"text", "_limit" integer DEFAULT 25, "_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM public._require_super_admin();
  RETURN (
    WITH live AS (SELECT s.*, public._canonical_company(s.company_id) AS co FROM sponsors s WHERE s.merged_into IS NULL),
    mem AS (SELECT m.*, l.co, l.name AS sponsor_name, COALESCE(m.display_name, m.email) AS label FROM sponsor_members m JOIN live l ON l.id = m.sponsor_id),
    items AS (
      -- Records of one organisation for one company.
      SELECT 'duplicate_sponsor_records' AS kind, c.name AS title,
             count(*) || ' records from ' || string_agg(DISTINCT COALESCE((SELECT u.email FROM auth.users u WHERE u.id = l.user_id), 'an organiser'), ', ') AS detail,
             c.id AS company_id, ARRAY_AGG(l.id ORDER BY l.created_at) AS sponsor_ids, '{}'::uuid[] AS person_ids
        FROM live l JOIN companies c ON c.id = l.co GROUP BY c.id, c.name, public._sponsor_scope(l.id) HAVING count(*) > 1
      UNION ALL
      -- One company twice on one event, on any organiser's records.
      SELECT 'same_event_repeat', c.name, count(*) || ' sponsorships on ' || COALESCE(e.title, 'an event') || ': ' ||
             string_agg(COALESCE(NULLIF(es.tier_label, ''), es.tier, 'no title'), ', ' ORDER BY es.created_at),
             c.id, ARRAY_AGG(l.id ORDER BY es.created_at), '{}'::uuid[]
        FROM event_sponsors es JOIN live l ON l.id = es.sponsor_id JOIN companies c ON c.id = l.co JOIN events e ON e.id = es.event_id
       GROUP BY c.id, c.name, e.id, e.title HAVING count(*) > 1
      UNION ALL
      -- Records not tied to a company, which means their team isn't either.
      SELECT 'contact_no_company', l.name, count(m.id) || ' team members; this sponsor isn''t connected to a company',
             NULL::uuid, ARRAY[l.id], '{}'::uuid[]
        FROM live l JOIN sponsor_members m ON m.sponsor_id = l.id WHERE l.co IS NULL GROUP BY l.id, l.name
      UNION ALL
      SELECT 'contact_no_person', m.label, m.sponsor_name || ' team; no contact record, probably an invalid email (' || m.email || ')',
             m.co, ARRAY[m.sponsor_id], '{}'::uuid[]
        FROM mem m WHERE m.person_id IS NULL
      UNION ALL
      -- The team member's own record names a different company from their sponsor's.
      SELECT 'contact_company_mismatch', m.label, 'Entered as "' || m.company || '", but on the team of ' || c.name,
             c.id, ARRAY[m.sponsor_id], ARRAY_REMOVE(ARRAY[m.person_id], NULL)
        FROM mem m JOIN companies c ON c.id = m.co
       WHERE public.company_name_key(m.company) <> '' AND public.company_name_key(m.company) <> c.name_key
         AND NOT EXISTS (SELECT 1 FROM company_aliases a WHERE a.company_id = c.id AND a.alias_key = public.company_name_key(m.company))
      UNION ALL
      -- Same name at one company under different contact records.
      SELECT 'duplicate_contact', max(m.label), 'Same name at ' || c.name || ' with ' || count(DISTINCT m.person_id) || ' contact records',
             c.id, '{}'::uuid[], ARRAY_AGG(DISTINCT m.person_id)
        FROM mem m JOIN companies c ON c.id = m.co JOIN people p ON p.id = m.person_id
       WHERE p.name_key <> '' GROUP BY c.id, c.name, p.name_key HAVING count(DISTINCT m.person_id) > 1
      UNION ALL
      -- One person on the teams of different companies.
      SELECT 'contact_multiple_companies', COALESCE(p.display_name, 'Contact'), 'On the teams of ' || string_agg(DISTINCT c.name, ', '),
             NULL::uuid, ARRAY_AGG(DISTINCT m.sponsor_id), ARRAY[p.id]
        FROM mem m JOIN companies c ON c.id = m.co JOIN people p ON p.id = m.person_id
       GROUP BY p.id, p.display_name HAVING count(DISTINCT m.co) > 1
    ),
    q AS (SELECT * FROM items WHERE _kind IS NULL OR kind = _kind),
    page AS (SELECT * FROM q ORDER BY kind, title, company_id LIMIT LEAST(GREATEST(COALESCE(_limit, 25), 1), 200) OFFSET GREATEST(COALESCE(_offset, 0), 0))
    SELECT jsonb_build_object(
      'total', (SELECT count(*) FROM q),
      'counts', COALESCE((SELECT jsonb_object_agg(kind, n) FROM (SELECT kind, count(*) n FROM items GROUP BY kind) k), '{}'::jsonb),
      'rows', COALESCE((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.kind, p.title, p.company_id) FROM page p), '[]'::jsonb))
  );
END;
$$;


ALTER FUNCTION "public"."intel_sponsor_review"("_kind" "text", "_limit" integer, "_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."intel_update_company"("_id" "uuid", "_changes" "jsonb", "_reason" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid uuid := public._require_super_admin();
  k    text;
  _n   integer := 0;
BEGIN
  PERFORM 1 FROM companies WHERE id = _id AND merged_into IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Company not found or merged' USING ERRCODE = 'P0002'; END IF;
  FOR k IN SELECT jsonb_object_keys(COALESCE(_changes, '{}'::jsonb)) LOOP
    IF public._intel_set_field('company', _id, k, _changes ->> k, 'manual', _reason, _uid) THEN _n := _n + 1; END IF;
  END LOOP;
  IF _n > 0 THEN
    INSERT INTO audit_logs (actor_id, action, target_type, target_id, details)
    VALUES (_uid, 'intel.company_edited', 'company', _id::text, jsonb_build_object('changes', _changes, 'reason', _reason));
  END IF;
  RETURN _n;
END;
$$;


