  END LOOP;
  IF _n > 0 THEN
    INSERT INTO audit_logs (actor_id, action, target_type, target_id, details)
    VALUES (_uid, 'intel.contact_edited', 'person', _id::text, jsonb_build_object('changes', _changes, 'reason', _reason));
  END IF;
  RETURN _n;
