    SELECT 1
      FROM public.event_speakers es
      JOIN public.speakers s ON s.id = es.speaker_id
     WHERE es.event_id = _event_id
       AND (
         s.user_id = _user_id
         OR lower(s.email) = lower((SELECT email FROM auth.users WHERE id = _user_id))
       )
  );
