CREATE OR REPLACE FUNCTION "public"."meeting_history"("_eid" "uuid", "_registration_id" "uuid" DEFAULT NULL::"uuid", "_speaker_id" "uuid" DEFAULT NULL::"uuid", "_sponsor_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("created_at" timestamp with time zone, "action" "text", "from_status" "text", "to_status" "text", "side" "text", "reason" "text", "cause" "text", "scheduled_at" timestamp with time zone, "location" "text", "backfilled" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE _sid uuid; _side text;
BEGIN
  SELECT a.sponsor_id, a.side INTO _sid, _side FROM public._meeting_actor(_eid, _sponsor_id) a;
  RETURN QUERY
    SELECT me.created_at, me.action, me.from_status, me.to_status, me.side,
           me.reason, me.cause, me.scheduled_at, me.location, me.backfilled
      FROM meeting_events me
     WHERE me.event_id = _eid AND me.sponsor_id = _sid
       AND (me.registration_id = _registration_id OR me.speaker_id = _speaker_id)
     ORDER BY me.created_at, me.id;
END;
$$;


