CREATE OR REPLACE FUNCTION "public"."my_bans"() RETURNS TABLE("scope" "text", "community_id" "uuid", "community_name" "text", "community_slug" "text", "banned_at" timestamp with time zone, "reason" "text", "request_id" "uuid", "request_status" "text", "request_created_at" timestamp with time zone, "review_note" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH bans AS (
    SELECT 'platform'::text AS scope, NULL::uuid AS community_id, NULL::text AS community_name,
           NULL::text AS community_slug, p.banned_at, p.banned_reason AS reason
      FROM profiles p
     WHERE p.user_id = auth.uid() AND p.banned_at IS NOT NULL
    UNION ALL
    SELECT 'community', cm.community_id, c.name, c.slug, NULL::timestamptz, NULL::text
      FROM community_members cm JOIN communities c ON c.id = cm.community_id
     WHERE cm.user_id = auth.uid() AND cm.status = 'banned'
  )
  SELECT b.scope, b.community_id, b.community_name, b.community_slug, b.banned_at, b.reason,
         r.id, r.status, r.created_at, r.review_note
    FROM bans b
    LEFT JOIN LATERAL (
      SELECT * FROM unban_requests ur
       WHERE ur.user_id = auth.uid() AND ur.scope = b.scope
         AND ur.community_id IS NOT DISTINCT FROM b.community_id
       ORDER BY ur.created_at DESC LIMIT 1
    ) r ON true;
$$;


ALTER FUNCTION "public"."my_bans"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."my_profile_suggestions"() RETURNS TABLE("field" "text", "current_value" "text", "suggested_value" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid   uuid := auth.uid();
  _email text;
  _pre   jsonb;
  _prof  profiles%ROWTYPE;
  _f     text;
  _cur   text;
  _sug   text;
BEGIN
  IF _uid IS NULL THEN RETURN; END IF;
  SELECT email INTO _email FROM auth.users WHERE id = _uid AND email_confirmed_at IS NOT NULL;
  IF _email IS NULL THEN RETURN; END IF;
  SELECT * INTO _prof FROM profiles WHERE user_id = _uid;
  IF NOT FOUND THEN RETURN; END IF;
  _pre := public.invitation_prefill(_email, true);
  FOREACH _f IN ARRAY ARRAY['title','first_name','last_name','designation','company',
                            'mobile_country_code','mobile_number','linkedin_url'] LOOP
    _sug := NULLIF(public.norm_text(_pre ->> _f), '');
    _cur := NULLIF(public.norm_text(to_jsonb(_prof) ->> _f), '');
    IF _sug IS NOT NULL AND lower(_sug) IS DISTINCT FROM lower(COALESCE(_cur, ''))
       AND NOT EXISTS (SELECT 1 FROM profile_suggestion_dismissals d
                        WHERE d.user_id = _uid AND d.field = _f AND d.value_key = lower(_sug)) THEN
      field := _f; current_value := _cur; suggested_value := _sug;
      RETURN NEXT;
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."my_profile_suggestions"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."new_certificate_code"() RETURNS "text"
    LANGUAGE "sql"
    SET "search_path" TO 'public'
    AS $$
  SELECT 'ILX-' || substr(h, 1, 4) || '-' || substr(h, 5, 4) || '-' || substr(h, 9, 4)
    FROM (SELECT upper(replace(gen_random_uuid()::text, '-', '')) AS h) x;
$$;


ALTER FUNCTION "public"."new_certificate_code"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."norm_country_code"("_raw" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER PARALLEL SAFE
    SET "search_path" TO ''
    AS $_$
DECLARE
  _t      text := upper(public.norm_text(_raw));
  _dial   text;
  _rest   text;
  _digits text;
BEGIN
  IF _t = '' THEN RETURN NULL; END IF;
  SELECT d.dial INTO _dial FROM public.dial_codes d WHERE d.iso = _t;
  IF _dial IS NOT NULL THEN RETURN _dial; END IF;
  _rest := regexp_replace(_t, '^00', '');
  IF _rest ~ '[^0-9+\s()-]' THEN RETURN NULL; END IF;
  _digits := regexp_replace(_rest, '[^0-9]', '', 'g');
  IF _digits !~ '^[0-9]{1,4}$' THEN RETURN NULL; END IF;
  RETURN '+' || _digits;
END;
$_$;


ALTER FUNCTION "public"."norm_country_code"("_raw" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."norm_email"("_raw" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $_$
  SELECT CASE
           WHEN e ~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$' AND e !~ '\.\.' AND length(e) <= 254 THEN e
         END
    FROM (SELECT lower(public.norm_text(_raw)) AS e) s;
$_$;


ALTER FUNCTION "public"."norm_email"("_raw" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."norm_phone"("_country_code" "text", "_number" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER PARALLEL SAFE
    SET "search_path" TO ''
    AS $_$
DECLARE
  _raw    text := public.norm_text(_number);
  _no_ext text;
  _digits text;
  _cc     text;
  _given  text;
  _best   text;
BEGIN
  IF _raw = '' THEN RETURN NULL; END IF;
  _no_ext := regexp_replace(_raw, '\s*(ext|x)\.?\s*[0-9]+$', '', 'i');
  IF _no_ext ~* '[a-z]' THEN RETURN NULL; END IF;
  _digits := regexp_replace(_no_ext, '[\s().-]', '', 'g');

  IF _digits ~ '^(\+|00)' THEN
    -- The number carries its own country code.
    _digits := regexp_replace(_digits, '^(\+|00)', '');
    IF _digits !~ '^[0-9]+$' THEN RETURN NULL; END IF;
    _given := public.norm_country_code(_country_code);
    SELECT x.p INTO _best
      FROM (SELECT substr(d.dial, 2) AS p FROM public.dial_codes d
            UNION SELECT substr(_given, 2) WHERE _given IS NOT NULL) x
     WHERE _digits LIKE x.p || '%'
     ORDER BY length(x.p) DESC
     LIMIT 1;
    IF _best IS NULL THEN RETURN NULL; END IF;
    _cc := '+' || _best;
    _digits := substr(_digits, length(_best) + 1);
  ELSE
    IF _digits !~ '^[0-9]+$' THEN RETURN NULL; END IF;
    _cc := public.norm_country_code(_country_code);
    IF _cc IS NULL THEN RETURN NULL; END IF;
    _digits := regexp_replace(_digits, '^0+', '');           -- national trunk 0
    IF length(_digits) > 10 AND _digits LIKE substr(_cc, 2) || '%' THEN
      _digits := substr(_digits, length(_cc));               -- code typed twice
    END IF;
  END IF;

  IF length(_digits) < 6 OR length(_cc) - 1 + length(_digits) > 15 THEN RETURN NULL; END IF;
  RETURN _cc || _digits;
END;
$_$;


ALTER FUNCTION "public"."norm_phone"("_country_code" "text", "_number" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."norm_text"("_raw" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $$
  SELECT btrim(regexp_replace(
           regexp_replace(normalize(COALESCE(_raw, ''), NFKC), '[\u200B-\u200D\uFEFF]', '', 'g'),
           '\s+', ' ', 'g'));
$$;


ALTER FUNCTION "public"."norm_text"("_raw" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."norm_website_domain"("_raw" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $_$
DECLARE
  _t    text := public.norm_text(_raw);
  _host text;
BEGIN
  IF _t = '' OR _t ~ '\s' THEN RETURN NULL; END IF;
  IF _t ~* '^[a-z][a-z0-9+.-]*://' AND _t !~* '^https?://' THEN RETURN NULL; END IF;
  _host := lower(substring(regexp_replace(_t, '^https?://', '', 'i') FROM '^([^/?#:]+)'));
  _host := regexp_replace(regexp_replace(_host, '^www\.', ''), '\.$', '');
  IF _host !~ '^[a-z0-9-]+(\.[a-z0-9-]+)+$' OR _host ~ '^[0-9]+(\.[0-9]+){3}$' THEN RETURN NULL; END IF;
  RETURN _host;
END;
$_$;


ALTER FUNCTION "public"."norm_website_domain"("_raw" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."note_company_from_entry"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.company IS NOT NULL AND btrim(NEW.company) <> ''
     AND (TG_OP = 'INSERT' OR NEW.company IS DISTINCT FROM OLD.company OR NEW.person_id IS DISTINCT FROM OLD.person_id) THEN
    PERFORM public._note_company_mention(NEW.person_id, NEW.company);
  END IF;
  RETURN NULL;
END;
$$;


