CREATE OR REPLACE FUNCTION "public"."notify_organizer_venue_response"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  _supabase_url text;
  _service_key  text;
BEGIN
  -- Only fire on real status transitions into accepted / declined. Skips
  -- the initial contacted → contacted upsert and any no-op UPDATE.
  IF TG_OP <> 'UPDATE'
     OR NEW.status = OLD.status
     OR NEW.status NOT IN ('accepted', 'declined') THEN
    RETURN NEW;
  END IF;

  SELECT value INTO _supabase_url FROM public.app_settings WHERE key = 'supabase_url';
  SELECT value INTO _service_key  FROM public.app_settings WHERE key = 'service_role_key';

  IF _supabase_url IS NULL OR _service_key IS NULL THEN
    -- Not configured yet — dev / preview environment. Silently skip so the
    -- vendor's accept / decline still commits.
    RETURN NEW;
  END IF;

  BEGIN
    PERFORM net.http_post(
      url     := _supabase_url || '/functions/v1/notify-organizer-venue-response',
      headers := jsonb_build_object(
        'Authorization', 'Bearer ' || _service_key,
        'Content-Type',  'application/json'
      ),
      body    := jsonb_build_object(
        'selection_id',  NEW.id,
        'event_id',      NEW.event_id,
        'vendor_id',     NEW.vendor_id,
        'status',        NEW.status,
        'previous_status', OLD.status,
        'notes',         NEW.notes
      )
    );
  EXCEPTION WHEN OTHERS THEN
    -- Never fail the trigger for a delivery hiccup. Row is already saved.
    RAISE NOTICE 'notify_organizer_venue_response dispatch failed: %', SQLERRM;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_organizer_venue_response"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."on_vendor_email_confirmed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_business_name text;
  new_vendor_id   uuid;
  v_venue_cat_id  uuid;
begin
  v_business_name := nullif(trim(new.raw_user_meta_data->>'business_name'), '');
  if v_business_name is null then
    return new;
  end if;

  if exists (select 1 from public.vendor_members where user_id = new.id) then
    return new;
  end if;

  -- ── ALLOWLIST GATE (migration 105) ──
  -- Skip the entire vendor provisioning path when the email isn't on
  -- the allowlist. The email still gets confirmed on auth.users so
  -- the user can log into the main app if they have access there.
  if not exists (
    select 1 from public.vendor_email_allowlist a
    where lower(a.email) = lower(new.email)
  ) then
    return new;
  end if;

  insert into public.vendors (business_name)
  values (v_business_name)
  returning id into new_vendor_id;

  insert into public.vendor_members (vendor_id, user_id, role)
  values (new_vendor_id, new.id, 'owner');

  select id into v_venue_cat_id
    from public.vendor_categories
   where slug = 'venue';
  if v_venue_cat_id is not null then
    insert into public.vendor_category_map (vendor_id, category_id)
    values (new_vendor_id, v_venue_cat_id)
    on conflict do nothing;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."on_vendor_email_confirmed"() OWNER TO "postgres";


