CREATE OR REPLACE FUNCTION "public"."org_invitations_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _issuing boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.token_hash  := NULL;
    NEW.claimed_at  := NULL;
    NEW.accepted_at := NULL;
    NEW.accepted_by := NULL;
    _issuing := NEW.status = 'pending';
  ELSE
    IF NEW.token_hash IS DISTINCT FROM OLD.token_hash AND NEW.token_hash IS NOT NULL THEN
      NEW.token_hash := OLD.token_hash;
    END IF;
    IF NEW.email IS DISTINCT FROM OLD.email
       OR NEW.org_id IS DISTINCT FROM OLD.org_id
       OR (NEW.status = 'pending' AND OLD.status <> 'pending') THEN
      NEW.token_hash := NULL;
    END IF;
    _issuing := NEW.status = 'pending' AND (
         OLD.status <> 'pending'
      OR NEW.email IS DISTINCT FROM OLD.email
      OR NEW.role IS DISTINCT FROM OLD.role
      OR NEW.token IS DISTINCT FROM OLD.token
      OR NEW.expires_at IS DISTINCT FROM OLD.expires_at
    );
  END IF;

  IF _issuing THEN
    IF NOT EXISTS (
      SELECT 1 FROM auth.users u WHERE u.id = auth.uid() AND u.email_confirmed_at IS NOT NULL
    ) THEN
      RAISE EXCEPTION 'Verify your email address before inviting team members.'
        USING ERRCODE = '42501';
    END IF;
    NEW.invited_by := auth.uid();
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."org_invitations_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."org_invitations_hand_over"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.transfer_ownership
     AND NEW.status = 'accepted'
     AND OLD.status IS DISTINCT FROM 'accepted'
     AND NEW.accepted_by IS NOT NULL THEN
    UPDATE public.organizations
       SET owner_id = NEW.accepted_by, updated_at = now()
     WHERE id = NEW.org_id;
    INSERT INTO public.org_members (org_id, user_id, role)
         VALUES (NEW.org_id, NEW.accepted_by, 'owner')
    ON CONFLICT (org_id, user_id) DO UPDATE SET role = 'owner';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."org_invitations_hand_over"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."org_invitations_hand_over"() IS 'When an ownership-handover invitation is accepted, the organization''s owner becomes the accepting user (with the owner membership), in the same transaction.';



