CREATE OR REPLACE FUNCTION "public"."organizer_add_event_sponsor"("_event" "uuid", "_sponsor" "uuid" DEFAULT NULL::"uuid", "_company" "uuid" DEFAULT NULL::"uuid", "_name" "text" DEFAULT NULL::"text", "_tier" "text" DEFAULT 'bronze'::"text", "_tier_label" "text" DEFAULT NULL::"text", "_email" "text" DEFAULT NULL::"text", "_website" "text" DEFAULT NULL::"text", "_logo_url" "text" DEFAULT NULL::"text", "_description" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _scope   text := public._event_scope(_event);
  _rec     sponsors%ROWTYPE;
  _co      uuid := _company;
  _created boolean := false;
  _link    uuid;
  _cname   text;
  _label   text := NULLIF(btrim(COALESCE(_tier_label, '')), '');
  _logo    text := NULLIF(btrim(COALESCE(_logo_url, '')), '');
BEGIN
  IF public._sponsorship_access(_event) IS NULL THEN
    RAISE EXCEPTION 'You don''t have access to this event''s sponsors' USING ERRCODE = '42501';
  END IF;
  IF COALESCE(_tier, 'bronze') = 'custom' AND _label IS NULL THEN RAISE EXCEPTION 'Enter the partnership title' USING ERRCODE = '22023'; END IF;

  IF _sponsor IS NOT NULL THEN
    IF NOT public._sponsor_usable_on(_sponsor, _event) THEN
      RAISE EXCEPTION 'That sponsor isn''t one of your organisation''s' USING ERRCODE = '42501';
    END IF;
    SELECT * INTO _rec FROM sponsors WHERE id = _sponsor;
    _co := public._canonical_company(_rec.company_id);
  ELSE
    IF _co IS NOT NULL THEN
      _co := public._canonical_company(_co);
      IF _co IS NULL THEN RAISE EXCEPTION 'Unknown company' USING ERRCODE = '22023'; END IF;
    ELSE
      IF NULLIF(public.norm_text(_name), '') IS NULL THEN RAISE EXCEPTION 'Enter the company name' USING ERRCODE = '22023'; END IF;
      _co := public._ensure_company_for_sponsor(_name, _website);
    END IF;
    IF _co IS NOT NULL THEN
      SELECT s.* INTO _rec FROM sponsors s
       WHERE s.company_id = _co AND s.merged_into IS NULL AND (s.user_id = auth.uid() OR public._sponsor_scope(s.id) = _scope)
       ORDER BY EXISTS (SELECT 1 FROM event_sponsors es WHERE es.sponsor_id = s.id AND es.event_id = _event) DESC,
                (SELECT count(*) FROM event_sponsors es WHERE es.sponsor_id = s.id) DESC, s.created_at, s.id
       LIMIT 1;
    END IF;
  END IF;

  SELECT name INTO _cname FROM companies WHERE id = _co;
  IF _rec.id IS NULL THEN
    _created := true;
    INSERT INTO sponsors (user_id, name, email, website, logo_url, description, tier, tier_label, company_id)
    VALUES (auth.uid(), COALESCE(_cname, public.norm_text(_name)), NULLIF(btrim(COALESCE(_email, '')), ''),
            COALESCE(NULLIF(btrim(COALESCE(_website, '')), ''), (SELECT website FROM companies WHERE id = _co)), _logo,
            NULLIF(btrim(COALESCE(_description, '')), ''), COALESCE(_tier, 'bronze'), _label, _co)
    RETURNING * INTO _rec;
  ELSE
    UPDATE sponsors
       SET email = COALESCE(email, NULLIF(btrim(COALESCE(_email, '')), '')),
           logo_url = COALESCE(logo_url, _logo),
           description = COALESCE(description, NULLIF(btrim(COALESCE(_description, '')), ''))
     WHERE id = _rec.id
    RETURNING * INTO _rec;
  END IF;

  IF EXISTS (SELECT 1 FROM event_sponsors WHERE event_id = _event AND sponsor_id = _rec.id) THEN
    RAISE EXCEPTION 'This sponsor is already on this event. Open it there to change its title.' USING ERRCODE = '23505';
  END IF;
  INSERT INTO event_sponsors (event_id, sponsor_id, tier, tier_label, logo_url, display_order)
  VALUES (_event, _rec.id, COALESCE(_tier, 'bronze'), CASE WHEN _tier = 'custom' THEN _label END,
          CASE WHEN _logo IS DISTINCT FROM _rec.logo_url THEN _logo END,
          COALESCE((SELECT max(display_order) + 1 FROM event_sponsors WHERE event_id = _event), 0))
  RETURNING id INTO _link;

  RETURN jsonb_build_object('event_sponsor_id', _link, 'sponsor_id', _rec.id, 'name', _rec.name, 'email', _rec.email,
                            'company_id', _co, 'company', _cname, 'created', _created);
END;
$$;


ALTER FUNCTION "public"."organizer_add_event_sponsor"("_event" "uuid", "_sponsor" "uuid", "_company" "uuid", "_name" "text", "_tier" "text", "_tier_label" "text", "_email" "text", "_website" "text", "_logo_url" "text", "_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."organizer_add_sponsor_contact"("_event_sponsor" "uuid", "_first_name" "text", "_last_name" "text", "_email" "text", "_designation" "text" DEFAULT NULL::"text", "_phone_cc" "text" DEFAULT NULL::"text", "_phone" "text" DEFAULT NULL::"text", "_linkedin" "text" DEFAULT NULL::"text", "_title" "text" DEFAULT NULL::"text", "_role_label" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  l        event_sponsors%ROWTYPE;
  _company uuid;
  _cname   text;
  _member  uuid;
  _person  uuid;
  _exists  boolean := true;
  _addr    text := lower(btrim(COALESCE(_email, '')));
  _name    text := NULLIF(btrim(COALESCE(_first_name, '') || ' ' || COALESCE(_last_name, '')), '');
BEGIN
  SELECT * INTO l FROM event_sponsors WHERE id = _event_sponsor;
  IF NOT FOUND THEN RAISE EXCEPTION 'Sponsorship not found' USING ERRCODE = 'P0002'; END IF;
  IF public._sponsorship_access(l.event_id) IS NULL THEN
    RAISE EXCEPTION 'You don''t have access to this event''s sponsors' USING ERRCODE = '42501';
  END IF;
  IF public.norm_email(_addr) IS NULL THEN RAISE EXCEPTION 'Enter a valid email address' USING ERRCODE = '22023'; END IF;
  IF _name IS NULL THEN RAISE EXCEPTION 'Enter the person''s name' USING ERRCODE = '22023'; END IF;

  _company := public._sponsor_company(l.sponsor_id);
  SELECT COALESCE((SELECT c.name FROM companies c WHERE c.id = _company), s.name) INTO _cname FROM sponsors s WHERE s.id = l.sponsor_id;

  SELECT id INTO _member FROM sponsor_members WHERE sponsor_id = l.sponsor_id AND lower(email) = _addr LIMIT 1;
  IF _member IS NULL THEN
    _exists := false;
    INSERT INTO sponsor_members (sponsor_id, email, display_name, title, first_name, last_name, designation, company,
                                 mobile_country_code, mobile_number, linkedin_url)
    VALUES (l.sponsor_id, _addr, _name, NULLIF(btrim(COALESCE(_title, '')), ''), NULLIF(btrim(COALESCE(_first_name, '')), ''), NULLIF(btrim(COALESCE(_last_name, '')), ''),
            NULLIF(btrim(COALESCE(_designation, '')), ''), _cname, NULLIF(btrim(COALESCE(_phone_cc, '')), ''), NULLIF(btrim(COALESCE(_phone, '')), ''), NULLIF(btrim(COALESCE(_linkedin, '')), ''))
    RETURNING id INTO _member;
  END IF;
  _person := public._link_member_to_company(_member, _company);

  INSERT INTO event_sponsor_contacts (event_sponsor_id, member_id, role_label, created_by)
  VALUES (l.id, _member, NULLIF(btrim(COALESCE(_role_label, '')), ''), auth.uid())
  ON CONFLICT (event_sponsor_id, member_id) DO UPDATE SET role_label = COALESCE(EXCLUDED.role_label, event_sponsor_contacts.role_label);

  RETURN jsonb_build_object('member_id', _member, 'person_id', _person, 'company_id', _company, 'company', _cname,
                            'sponsor_id', l.sponsor_id, 'event_id', l.event_id, 'event_sponsor_id', l.id, 'existing', _exists);
END;
$$;


ALTER FUNCTION "public"."organizer_add_sponsor_contact"("_event_sponsor" "uuid", "_first_name" "text", "_last_name" "text", "_email" "text", "_designation" "text", "_phone_cc" "text", "_phone" "text", "_linkedin" "text", "_title" "text", "_role_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."organizer_assign_sponsor_contact"("_event_sponsor" "uuid", "_member" "uuid", "_role_label" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  l    event_sponsors%ROWTYPE;
  m    sponsor_members%ROWTYPE;
  ms   sponsors%ROWTYPE;
  _co  uuid;
  _id  uuid;
  _new boolean := false;
BEGIN
  SELECT * INTO l FROM event_sponsors WHERE id = _event_sponsor;
  IF NOT FOUND THEN RAISE EXCEPTION 'Sponsorship not found' USING ERRCODE = 'P0002'; END IF;
  IF public._sponsorship_access(l.event_id) IS NULL THEN
    RAISE EXCEPTION 'You don''t have access to this event''s sponsors' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO m FROM sponsor_members WHERE id = _member;
  IF NOT FOUND THEN RAISE EXCEPTION 'Contact not found' USING ERRCODE = 'P0002'; END IF;
  SELECT * INTO ms FROM sponsors WHERE id = m.sponsor_id;
  _co := public._sponsor_company(l.sponsor_id);
  IF m.sponsor_id <> l.sponsor_id AND NOT (
       public._canonical_company(ms.company_id) = _co
       AND (ms.user_id = auth.uid() OR public.has_role(auth.uid(), 'admin') OR public._organises_sponsor_event(ms.id, auth.uid()))) THEN
    RAISE EXCEPTION 'That contact isn''t one of this company''s contacts you can use' USING ERRCODE = '42501';
  END IF;

  IF m.sponsor_id = l.sponsor_id THEN
    _id := m.id;
  ELSE
    SELECT id INTO _id FROM sponsor_members WHERE sponsor_id = l.sponsor_id AND lower(email) = lower(m.email) LIMIT 1;
    IF _id IS NULL THEN
      _new := true;
      INSERT INTO sponsor_members (sponsor_id, email, display_name, title, first_name, last_name, designation, company,
                                   mobile_country_code, mobile_number, linkedin_url)
      VALUES (l.sponsor_id, lower(m.email), m.display_name, m.title, m.first_name, m.last_name, m.designation,
              (SELECT name FROM companies WHERE id = _co), m.mobile_country_code, m.mobile_number, m.linkedin_url)
      RETURNING id INTO _id;
    END IF;
  END IF;
  PERFORM public._link_member_to_company(_id, _co);
  INSERT INTO event_sponsor_contacts (event_sponsor_id, member_id, role_label, created_by)
  VALUES (l.id, _id, NULLIF(btrim(COALESCE(_role_label, '')), ''), auth.uid())
  ON CONFLICT (event_sponsor_id, member_id) DO UPDATE SET role_label = COALESCE(EXCLUDED.role_label, event_sponsor_contacts.role_label);
  RETURN jsonb_build_object('member_id', _id, 'new_member', _new, 'sponsor_id', l.sponsor_id, 'event_id', l.event_id);
END;
$$;


ALTER FUNCTION "public"."organizer_assign_sponsor_contact"("_event_sponsor" "uuid", "_member" "uuid", "_role_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."organizer_event_sponsorships"("_event" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _access text := public._sponsorship_access(_event);
BEGIN
  IF _access IS NULL THEN RAISE EXCEPTION 'You don''t have access to this event''s sponsors' USING ERRCODE = '42501'; END IF;
  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
      'event_sponsor_id', es.id, 'sponsor_id', es.sponsor_id, 'company_id', s.company_id,
      'company', c.name, 'tier', es.tier, 'tier_label', es.tier_label, 'logo_url', COALESCE(es.logo_url, s.logo_url),
      'package', d.package, 'status', COALESCE(d.status, 'confirmed'),
      'commercial_value', CASE WHEN _access = 'commercial' THEN d.commercial_value END,
      'currency', CASE WHEN _access = 'commercial' THEN d.currency END,
      'contacts', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', m.id, 'name', COALESCE(m.display_name, m.email), 'role', a.role_label) ORDER BY m.created_at)
                              FROM event_sponsor_contacts a JOIN sponsor_members m ON m.id = a.member_id WHERE a.event_sponsor_id = es.id), '[]'::jsonb)
    ) ORDER BY es.display_order, es.created_at)
      FROM event_sponsors es
      JOIN sponsors s ON s.id = es.sponsor_id
      LEFT JOIN companies c ON c.id = public._canonical_company(s.company_id)
      LEFT JOIN event_sponsorship_details d ON d.event_sponsor_id = es.id
     WHERE es.event_id = _event), '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."organizer_event_sponsorships"("_event" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."organizer_revoke_sponsor_data"("_share" "uuid", "_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  x    sponsor_data_shares%ROWTYPE;
  _uid uuid;
BEGIN
  SELECT * INTO x FROM sponsor_data_shares WHERE id = _share FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Share not found' USING ERRCODE = 'P0002'; END IF;
  _uid := public._require_share_access(x.event_id);
  DELETE FROM sponsor_data_share_rows WHERE share_id = _share;
  IF x.status = 'revoked' THEN RETURN; END IF;
  UPDATE sponsor_data_shares SET status = 'revoked', revoked_by = _uid, revoked_at = now(), revoke_reason = NULLIF(btrim(COALESCE(_reason, '')), '')
   WHERE id = _share;
  INSERT INTO audit_logs (actor_id, action, target_type, target_id, details)
  VALUES (_uid, 'sponsor_data.revoked', 'event_sponsor', x.event_sponsor_id::text,
          jsonb_build_object('share_id', x.id, 'version', x.version, 'event_id', x.event_id, 'reason', _reason));
END;
$$;


ALTER FUNCTION "public"."organizer_revoke_sponsor_data"("_share" "uuid", "_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."organizer_search_company_contacts"("_event_sponsor" "uuid", "_q" "text" DEFAULT NULL::"text", "_limit" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  l    event_sponsors%ROWTYPE;
  _co  uuid;
  _t   text := lower(btrim(COALESCE(_q, '')));
  _ph  text := regexp_replace(COALESCE(_q, ''), '[^0-9]', '', 'g');
BEGIN
  SELECT * INTO l FROM event_sponsors WHERE id = _event_sponsor;
  IF NOT FOUND THEN RAISE EXCEPTION 'Sponsorship not found' USING ERRCODE = 'P0002'; END IF;
  IF public._sponsorship_access(l.event_id) IS NULL THEN
    RAISE EXCEPTION 'You don''t have access to this event''s sponsors' USING ERRCODE = '42501';
  END IF;
  SELECT public._canonical_company(company_id) INTO _co FROM sponsors WHERE id = l.sponsor_id;
  RETURN COALESCE((
    SELECT jsonb_agg(x.row ORDER BY x.name) FROM (
      SELECT DISTINCT ON (lower(m.email))
             lower(COALESCE(m.display_name, m.email)) AS name,
             jsonb_build_object('member_id', m.id, 'person_id', m.person_id, 'name', m.display_name, 'email', m.email,
               'designation', m.designation, 'phone', NULLIF(btrim(COALESCE(m.mobile_country_code, '') || ' ' || COALESCE(m.mobile_number, '')), ''),
               'assigned', EXISTS (SELECT 1 FROM event_sponsor_contacts a JOIN sponsor_members t ON t.id = a.member_id
                                    WHERE a.event_sponsor_id = l.id AND lower(t.email) = lower(m.email))) AS row
        FROM sponsor_members m JOIN sponsors s ON s.id = m.sponsor_id
       WHERE (m.sponsor_id = l.sponsor_id
              OR (_co IS NOT NULL AND public._canonical_company(s.company_id) = _co
                  AND (s.user_id = auth.uid() OR public.has_role(auth.uid(), 'admin') OR public._organises_sponsor_event(s.id, auth.uid()))))
         AND (_t = '' OR lower(COALESCE(m.display_name, '')) LIKE '%' || _t || '%' OR lower(m.email) LIKE '%' || _t || '%'
              OR lower(COALESCE(m.designation, '')) LIKE '%' || _t || '%'
              OR (length(_ph) >= 4 AND regexp_replace(COALESCE(m.mobile_number, ''), '[^0-9]', '', 'g') LIKE '%' || _ph || '%'))
       ORDER BY lower(m.email), (m.sponsor_id = l.sponsor_id) DESC, m.created_at
       LIMIT LEAST(GREATEST(COALESCE(_limit, 20), 1), 50)) x), '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."organizer_search_company_contacts"("_event_sponsor" "uuid", "_q" "text", "_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."organizer_set_sponsor_contact"("_event_sponsor" "uuid", "_member" "uuid", "_role_label" "text" DEFAULT NULL::"text", "_responsibilities" "text" DEFAULT NULL::"text", "_remove" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE l event_sponsors%ROWTYPE;
BEGIN
  SELECT * INTO l FROM event_sponsors WHERE id = _event_sponsor;
  IF NOT FOUND THEN RAISE EXCEPTION 'Sponsorship not found' USING ERRCODE = 'P0002'; END IF;
  IF public._sponsorship_access(l.event_id) IS NULL THEN
    RAISE EXCEPTION 'You don''t have access to this event''s sponsors' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM sponsor_members WHERE id = _member AND sponsor_id = l.sponsor_id) THEN
    RAISE EXCEPTION 'That person isn''t on this sponsor''s team' USING ERRCODE = '22023';
  END IF;
  IF _remove THEN
    DELETE FROM event_sponsor_contacts WHERE event_sponsor_id = l.id AND member_id = _member;
  ELSE
    INSERT INTO event_sponsor_contacts (event_sponsor_id, member_id, role_label, responsibilities, created_by)
    VALUES (l.id, _member, NULLIF(btrim(COALESCE(_role_label, '')), ''), NULLIF(btrim(COALESCE(_responsibilities, '')), ''), auth.uid())
    ON CONFLICT (event_sponsor_id, member_id) DO UPDATE SET role_label = EXCLUDED.role_label, responsibilities = EXCLUDED.responsibilities;
  END IF;
END;
$$;


ALTER FUNCTION "public"."organizer_set_sponsor_contact"("_event_sponsor" "uuid", "_member" "uuid", "_role_label" "text", "_responsibilities" "text", "_remove" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."organizer_share_sponsor_data"("_event_sponsor" "uuid", "_share_before_end" boolean DEFAULT false, "_allow_export" boolean DEFAULT true, "_include_without_permission" boolean DEFAULT true) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  l       event_sponsors%ROWTYPE;
  _uid    uuid;
  _ended  boolean;
  _id     uuid := gen_random_uuid();
  _ver    integer;
  _title  text;
  _name   text;
BEGIN
  SELECT * INTO l FROM event_sponsors WHERE id = _event_sponsor FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Sponsorship not found' USING ERRCODE = 'P0002'; END IF;
  _uid := public._require_share_access(l.event_id);
  _ended := public._event_has_ended(l.event_id);
  IF NOT _ended AND NOT COALESCE(_share_before_end, false) THEN
    RAISE EXCEPTION 'This event hasn''t ended. Confirm that you mean to share before it ends.' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(max(version), 0) + 1 INTO _ver FROM sponsor_data_shares WHERE event_id = l.event_id AND sponsor_id = l.sponsor_id;
  -- The version being replaced: its record stays, its copy of people's details doesn't.
  DELETE FROM sponsor_data_share_rows
   WHERE share_id IN (SELECT id FROM sponsor_data_shares WHERE event_sponsor_id = l.id AND status = 'active');
  UPDATE sponsor_data_shares SET status = 'superseded' WHERE event_sponsor_id = l.id AND status = 'active';

  CREATE TEMP TABLE IF NOT EXISTS _share_people (person_id uuid, data jsonb) ON COMMIT DROP;
  -- Supabase refuses a DELETE without a WHERE clause, so it says which rows: all of them.
  DELETE FROM _share_people WHERE true;
  INSERT INTO _share_people SELECT * FROM public._sponsor_share_people(l.event_id, _ended);

  INSERT INTO sponsor_data_shares (id, event_sponsor_id, event_id, sponsor_id, company_id, version, allow_export, includes_without_permission,
                                   fields, record_count, with_email, with_mobile, with_both, without_contact, without_permission,
                                   shared_before_end, shared_by)
  SELECT _id, l.id, l.event_id, l.sponsor_id, (SELECT public._canonical_company(company_id) FROM sponsors WHERE id = l.sponsor_id), _ver,
         COALESCE(_allow_export, true), true, public._sponsor_share_fields(),
         count(*), count(*) FILTER (WHERE p.data ? 'email'), count(*) FILTER (WHERE p.data ? 'mobile'),
         count(*) FILTER (WHERE p.data ? 'email' AND p.data ? 'mobile'), count(*) FILTER (WHERE NOT p.data ? 'email' AND NOT p.data ? 'mobile'),
         count(*) FILTER (WHERE NOT EXISTS (SELECT 1 FROM registrations r WHERE r.id = p.person_id AND r.sponsor_share_consent)),
         NOT _ended, _uid
    FROM _share_people p;
  INSERT INTO sponsor_data_share_rows (share_id, registration_id, data) SELECT _id, p.person_id, p.data FROM _share_people p;

  SELECT title INTO _title FROM events WHERE id = l.event_id;
  SELECT name INTO _name FROM sponsors WHERE id = l.sponsor_id;
  INSERT INTO app_notifications (user_id, type, title, body, link)
  SELECT DISTINCT m.user_id, 'sponsor_data_shared', 'Event data shared with you',
         COALESCE(_title, 'An event') || ': the participant list is ready to view.', '/sponsor/events/' || l.event_id || '#shared-data'
    FROM sponsor_members m
   WHERE m.sponsor_id = l.sponsor_id AND m.user_id IS NOT NULL AND m.accepted_at IS NOT NULL
     AND (m.role = 'admin' OR EXISTS (SELECT 1 FROM event_sponsor_contacts a WHERE a.event_sponsor_id = l.id AND a.member_id = m.id));

  INSERT INTO audit_logs (actor_id, action, target_type, target_id, details)
  VALUES (_uid, 'sponsor_data.shared', 'event_sponsor', l.id::text,
          jsonb_build_object('share_id', _id, 'version', _ver, 'event_id', l.event_id, 'sponsor', _name, 'before_end', NOT _ended,
                             'records', (SELECT record_count FROM sponsor_data_shares WHERE id = _id)));
  RETURN _id;
END;
$$;


ALTER FUNCTION "public"."organizer_share_sponsor_data"("_event_sponsor" "uuid", "_share_before_end" boolean, "_allow_export" boolean, "_include_without_permission" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."organizer_sponsor_options"("_event" "uuid", "_q" "text" DEFAULT NULL::"text", "_limit" integer DEFAULT 12) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _t     text := lower(COALESCE(public.norm_text(_q), ''));
  _k     text := COALESCE(public.company_name_key(_q), '');
  _lim   integer := LEAST(GREATEST(COALESCE(_limit, 12), 1), 30);
  _scope text := public._event_scope(_event);
BEGIN
  IF public._sponsorship_access(_event) IS NULL THEN
    RAISE EXCEPTION 'You don''t have access to this event''s sponsors' USING ERRCODE = '42501';
  END IF;
  RETURN (
    WITH mine AS (
      SELECT s.*, public._canonical_company(s.company_id) AS co,
             (SELECT count(*) FROM event_sponsors es WHERE es.sponsor_id = s.id) AS n
        FROM sponsors s
       WHERE s.merged_into IS NULL
         AND (s.user_id = auth.uid() OR public._sponsor_scope(s.id) = _scope)
         AND (_t = '' OR lower(s.name) LIKE '%' || _t || '%' OR lower(COALESCE(s.email, '')) LIKE '%' || _t || '%'
              OR lower(COALESCE(s.website, '')) LIKE '%' || _t || '%'
              OR (_k <> '' AND EXISTS (SELECT 1 FROM companies c WHERE c.id = public._canonical_company(s.company_id)
                    AND (c.name_key LIKE '%' || _k || '%'
                         OR EXISTS (SELECT 1 FROM company_aliases a WHERE a.company_id = c.id AND a.alias_key LIKE '%' || _k || '%')))))
    ), once AS (
      -- A company with two records yet to be combined is offered once.
      SELECT DISTINCT ON (COALESCE(m.co::text, m.id::text)) m.* FROM mine m
       ORDER BY COALESCE(m.co::text, m.id::text),
                EXISTS (SELECT 1 FROM event_sponsors es WHERE es.sponsor_id = m.id AND es.event_id = _event) DESC, m.n DESC, m.created_at, m.id
    ), rec AS (SELECT * FROM once ORDER BY lower(btrim(once.name)), once.id LIMIT _lim),
    dir AS (
      SELECT c.id, c.name, c.website, c.verification_status = 'verified' AS verified, c.entry_count
        FROM companies c
       WHERE _k <> '' AND c.merged_into IS NULL AND c.verification_status <> 'rejected'
         AND NOT EXISTS (SELECT 1 FROM mine m WHERE m.co = c.id)
         AND (c.name_key LIKE _k || '%' OR c.name_key LIKE '% ' || _k || '%'
              OR EXISTS (SELECT 1 FROM company_aliases a WHERE a.company_id = c.id AND a.alias_key LIKE _k || '%')
              OR EXISTS (SELECT 1 FROM company_domains d WHERE d.company_id = c.id AND d.domain LIKE _t || '%'))
       ORDER BY (c.name_key LIKE _k || '%') DESC, (c.verification_status = 'verified') DESC, c.entry_count DESC, c.name
       LIMIT _lim
    )
    SELECT jsonb_build_object(
      'records', COALESCE((SELECT jsonb_agg(jsonb_build_object(
          'sponsor_id', r.id, 'name', btrim(r.name), 'company_id', r.co, 'company', (SELECT c.name FROM companies c WHERE c.id = r.co),
          'website', r.website, 'email', r.email, 'logo_url', r.logo_url, 'tier', r.tier, 'tier_label', r.tier_label, 'events', r.n,
          'on_event', EXISTS (SELECT 1 FROM event_sponsors es JOIN sponsors o ON o.id = es.sponsor_id
                               WHERE es.event_id = _event AND (o.id = r.id OR (r.co IS NOT NULL AND o.company_id = r.co))))
          ORDER BY lower(btrim(r.name)), r.id) FROM rec r), '[]'::jsonb),
      'companies', COALESCE((SELECT jsonb_agg(jsonb_build_object('company_id', d.id, 'name', d.name, 'website', d.website, 'verified', d.verified)
          ORDER BY (lower(d.name) LIKE _t || '%') DESC, d.verified DESC, d.entry_count DESC, d.name) FROM dir d), '[]'::jsonb),
      -- Whether what was typed is already exactly one of the options.
      'exact', _k <> '' AND (EXISTS (SELECT 1 FROM rec r WHERE public.company_name_key(r.name) = _k)
                             OR EXISTS (SELECT 1 FROM dir d WHERE public.company_name_key(d.name) = _k)))
  );
END;
$$;


ALTER FUNCTION "public"."organizer_sponsor_options"("_event" "uuid", "_q" "text", "_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."organizer_sponsor_share_history"("_event_sponsor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE l event_sponsors%ROWTYPE;
BEGIN
  SELECT * INTO l FROM event_sponsors WHERE id = _event_sponsor;
  IF NOT FOUND THEN RAISE EXCEPTION 'Sponsorship not found' USING ERRCODE = 'P0002'; END IF;
  PERFORM public._require_share_access(l.event_id);
  RETURN COALESCE((
    SELECT jsonb_agg(to_jsonb(x) - 'fields' || jsonb_build_object(
             'shared_by_email', (SELECT u.email FROM auth.users u WHERE u.id = x.shared_by),
             'views', (SELECT count(*) FROM sponsor_data_access_log g WHERE g.share_id = x.id AND g.action = 'view'),
             'exports', (SELECT count(*) FROM sponsor_data_access_log g WHERE g.share_id = x.id AND g.action = 'export'),
             'last_opened', (SELECT max(g.created_at) FROM sponsor_data_access_log g WHERE g.share_id = x.id)) ORDER BY x.version DESC)
      FROM sponsor_data_shares x WHERE x.event_sponsor_id = l.id), '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."organizer_sponsor_share_history"("_event_sponsor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."organizer_sponsor_share_preview"("_event_sponsor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  l  event_sponsors%ROWTYPE;
  e  events%ROWTYPE;
BEGIN
  SELECT * INTO l FROM event_sponsors WHERE id = _event_sponsor;
  IF NOT FOUND THEN RAISE EXCEPTION 'Sponsorship not found' USING ERRCODE = 'P0002'; END IF;
  PERFORM public._require_share_access(l.event_id);
  SELECT * INTO e FROM events WHERE id = l.event_id;
  RETURN (
    WITH c AS (SELECT p.data ? 'email' AS em, p.data ? 'mobile' AS mo, p.data ->> 'participant_type' = 'Speaker' AS sp
                 FROM public._sponsor_share_people(l.event_id, public._event_has_ended(l.event_id)) p)
    SELECT jsonb_build_object(
      'event', jsonb_build_object('id', e.id, 'title', e.title, 'date', e.date, 'end_date', e.end_date, 'ended', public._event_has_ended(e.id)),
      'sponsor', (SELECT jsonb_build_object('id', s.id, 'name', COALESCE(co.name, s.name), 'title', l.tier, 'title_label', l.tier_label)
                    FROM sponsors s LEFT JOIN companies co ON co.id = public._canonical_company(s.company_id) WHERE s.id = l.sponsor_id),
      'eligible', (SELECT count(*) FROM c),
      'speakers', (SELECT count(*) FROM c WHERE sp),
      'attendees', (SELECT count(*) FROM c WHERE NOT sp),
      'with_email', (SELECT count(*) FROM c WHERE em),
      'with_mobile', (SELECT count(*) FROM c WHERE mo),
      'with_both', (SELECT count(*) FROM c WHERE em AND mo),
      'without_contact', (SELECT count(*) FROM c WHERE NOT em AND NOT mo),
      'without_permission', public._sponsor_share_without_permission(l.event_id),
      'fields', public._sponsor_share_fields(),
      'not_collected', '["Department","Country","City","Location","Custom questions"]'::jsonb,
      'current', (SELECT to_jsonb(x) - 'fields' FROM sponsor_data_shares x WHERE x.event_sponsor_id = l.id ORDER BY x.version DESC LIMIT 1)
    )
  );
END;
$$;


ALTER FUNCTION "public"."organizer_sponsor_share_preview"("_event_sponsor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."organizer_sponsor_share_status"("_event" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF public._sponsorship_access(_event) IS NULL THEN
    RAISE EXCEPTION 'You don''t have access to this event''s sponsors' USING ERRCODE = '42501';
  END IF;
  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object('event_sponsor_id', es.id, 'sponsor_id', es.sponsor_id, 'share',
             (SELECT to_jsonb(x) - 'fields' FROM sponsor_data_shares x WHERE x.event_sponsor_id = es.id ORDER BY x.version DESC LIMIT 1)))
      FROM event_sponsors es WHERE es.event_id = _event), '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."organizer_sponsor_share_status"("_event" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."organizer_sponsorship_detail"("_event_sponsor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  l       event_sponsors%ROWTYPE;
  s       sponsors%ROWTYPE;
  d       event_sponsorship_details%ROWTYPE;
  _access text;
  _co     uuid;
BEGIN
  SELECT * INTO l FROM event_sponsors WHERE id = _event_sponsor;
  IF NOT FOUND THEN RAISE EXCEPTION 'Sponsorship not found' USING ERRCODE = 'P0002'; END IF;
  _access := public._sponsorship_access(l.event_id);
  IF _access IS NULL THEN RAISE EXCEPTION 'You don''t have access to this event''s sponsors' USING ERRCODE = '42501'; END IF;
  SELECT * INTO s FROM sponsors WHERE id = l.sponsor_id;
  SELECT * INTO d FROM event_sponsorship_details WHERE event_sponsor_id = l.id;
  _co := public._canonical_company(s.company_id);
  RETURN jsonb_build_object(
    'access', _access,
    'sponsor', jsonb_build_object('id', s.id, 'name', s.name, 'email', s.email, 'website', s.website, 'logo_url', s.logo_url, 'description', s.description),
    'company', (SELECT jsonb_build_object('id', c.id, 'name', c.name, 'website', c.website, 'industry', c.industry, 'description', c.description,
                  'domains', ARRAY(SELECT dm.domain FROM company_domains dm WHERE dm.company_id = c.id ORDER BY dm.domain))
                  FROM companies c WHERE c.id = _co),
    'sponsorship', jsonb_build_object(
      'id', l.id, 'event_id', l.event_id, 'tier', l.tier, 'tier_label', l.tier_label, 'logo_url', l.logo_url,
      'package', d.package, 'deliverables', d.deliverables, 'status', COALESCE(d.status, 'confirmed'), 'notes', d.notes,
      'commercial_value', CASE WHEN _access = 'commercial' THEN d.commercial_value END,
      'currency', CASE WHEN _access = 'commercial' THEN COALESCE(d.currency, 'INR') END,
      'contract_url', CASE WHEN _access = 'commercial' THEN d.contract_url END,
      'payment_status', CASE WHEN _access = 'commercial' THEN COALESCE(d.payment_status, 'not_invoiced') END),
    'team', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', m.id, 'person_id', m.person_id, 'name', m.display_name, 'email', m.email, 'designation', m.designation,
              'accepted_at', m.accepted_at, 'invite_token', m.invite_token, 'assigned', a.id IS NOT NULL, 'role_label', a.role_label, 'responsibilities', a.responsibilities) ORDER BY a.id IS NULL, m.created_at)
              FROM sponsor_members m LEFT JOIN event_sponsor_contacts a ON a.member_id = m.id AND a.event_sponsor_id = l.id
             WHERE m.sponsor_id = l.sponsor_id), '[]'::jsonb),
    'history', COALESCE((SELECT jsonb_agg(jsonb_build_object('event_sponsor_id', o.id, 'event_id', e.id, 'event', e.title, 'date', e.date, 'tier', o.tier, 'tier_label', o.tier_label) ORDER BY e.date DESC NULLS LAST)
              FROM event_sponsors o JOIN sponsors os ON os.id = o.sponsor_id JOIN events e ON e.id = o.event_id
             WHERE o.id <> l.id AND public._sponsorship_access(o.event_id) IS NOT NULL
               AND (o.sponsor_id = l.sponsor_id OR (_co IS NOT NULL AND public._canonical_company(os.company_id) = _co))), '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."organizer_sponsorship_detail"("_event_sponsor" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."speakers" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "email" "text",
    "bio" "text",
    "photo_url" "text",
    "company" "text",
    "designation" "text",
    "title" "text",
    "first_name" "text",
    "last_name" "text",
    "mobile_country_code" "text",
    "mobile_number" "text",
    "linkedin_url" "text",
    "company_website" "text",
    "company_employee_count" "text",
    "industry" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "person_id" "uuid"
