CREATE OR REPLACE FUNCTION "public"."recompute_vendor_rating"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  SELECT b.vendor_id INTO v_id
    FROM public.vendor_bookings b
   WHERE b.id = COALESCE(NEW.booking_id, OLD.booking_id);

  IF v_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  UPDATE public.vendors v
     SET rating_avg = COALESCE((
           SELECT ROUND(AVG(r.rating)::numeric, 2)
             FROM public.vendor_reviews r
             JOIN public.vendor_bookings b ON b.id = r.booking_id
            WHERE b.vendor_id = v_id
              AND r.reviewer_type = 'organizer'
         ), 0),
         rating_count = (
           SELECT COUNT(*)
             FROM public.vendor_reviews r
             JOIN public.vendor_bookings b ON b.id = r.booking_id
            WHERE b.vendor_id = v_id
              AND r.reviewer_type = 'organizer'
         )
   WHERE v.id = v_id;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."recompute_vendor_rating"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_certificate_emails"("_certificate_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _n int := 0;
  c  record;
BEGIN
  FOR c IN SELECT * FROM public.certificates WHERE id = ANY (_certificate_ids) AND status = 'issued' LOOP
    IF public.can_manage_event_certificates(auth.uid(), c.event_id) THEN
      UPDATE public.certificates SET emailed_at = now(), email_count = email_count + 1 WHERE id = c.id;
      INSERT INTO public.certificate_audit (certificate_id, event_id, action, actor) VALUES (c.id, c.event_id, 'emailed', auth.uid());
      _n := _n + 1;
    END IF;
  END LOOP;
  RETURN _n;
END;
$$;


