CREATE OR REPLACE FUNCTION "public"."release_escrow"("p_escrow_id" "uuid", "p_actor_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_escrow payment_escrow%ROWTYPE;
  v_booking vendor_bookings%ROWTYPE;
  v_commission_share bigint;
  v_vendor_share bigint;
BEGIN
  SELECT * INTO v_escrow FROM payment_escrow WHERE id = p_escrow_id FOR UPDATE;
  IF v_escrow IS NULL THEN
    RAISE EXCEPTION 'Escrow entry not found';
  END IF;
  IF v_escrow.status != 'held' THEN
    RAISE EXCEPTION 'Escrow must be in "held" status to release (current: %)', v_escrow.status;
  END IF;

  -- Get booking for commission rate
  SELECT * INTO v_booking FROM vendor_bookings WHERE id = v_escrow.booking_id;

  -- Calculate split for this milestone payment
  v_commission_share := ROUND(v_escrow.amount * (v_booking.commission_rate / 100));
  v_vendor_share := v_escrow.amount - v_commission_share;

  -- Release
  UPDATE payment_escrow
  SET status = 'released', released_at = now(),
      payout_amount = v_vendor_share, platform_fee = v_commission_share
  WHERE id = p_escrow_id;

  -- Audit
  INSERT INTO vendor_audit_log (actor_id, action, entity_type, entity_id, metadata)
  VALUES (
    p_actor_id, 'escrow_released', 'payment_escrow', p_escrow_id,
    jsonb_build_object(
      'booking_id', v_escrow.booking_id,
      'amount', v_escrow.amount,
      'vendor_payout', v_vendor_share,
      'platform_fee', v_commission_share
    )
  );
END;
$$;


ALTER FUNCTION "public"."release_escrow"("p_escrow_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reliable_company_match"("_name" "text", "_website" "text" DEFAULT NULL::"text", "_email" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _domain text := public.norm_website_domain(_website);
  _mail   text := public.email_domain(_email);
  _key    text := public.company_name_key(_name);
  _ids    uuid[];
BEGIN
  IF _domain IS NOT NULL THEN
    SELECT ARRAY_AGG(company_id) INTO _ids FROM company_domains WHERE domain = _domain;
    IF array_length(_ids, 1) = 1 THEN RETURN _ids[1]; END IF;
  END IF;
  IF _mail IS NOT NULL AND NOT EXISTS (SELECT 1 FROM personal_email_domains WHERE domain = _mail) THEN
    SELECT ARRAY_AGG(company_id) INTO _ids FROM company_domains WHERE domain = _mail AND kind IN ('email','both');
    IF array_length(_ids, 1) = 1 THEN RETURN _ids[1]; END IF;
  END IF;
  IF _key <> '' THEN
    SELECT ARRAY_AGG(DISTINCT c.id) INTO _ids
      FROM companies c
      LEFT JOIN company_aliases a ON a.company_id = c.id
     WHERE c.verification_status = 'verified' AND c.merged_into IS NULL
       AND (c.name_key = _key OR a.alias_key = _key);
    IF array_length(_ids, 1) = 1 THEN RETURN _ids[1]; END IF;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."reliable_company_match"("_name" "text", "_website" "text", "_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_unban"("_scope" "text", "_community_id" "uuid", "_message" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _msg text := btrim(COALESCE(_message, ''));
  _id  uuid;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Sign in to send a request' USING ERRCODE = '42501'; END IF;
  IF _scope NOT IN ('platform', 'community') THEN RAISE EXCEPTION 'Invalid request' USING ERRCODE = '22023'; END IF;
  IF _scope = 'platform' THEN _community_id := NULL; END IF;
  IF char_length(_msg) < 10 OR char_length(_msg) > 2000 THEN
    RAISE EXCEPTION 'Write between 10 and 2000 characters' USING ERRCODE = '22023';
  END IF;

  IF _scope = 'platform' AND NOT EXISTS (
       SELECT 1 FROM profiles WHERE user_id = _uid AND banned_at IS NOT NULL) THEN
    RAISE EXCEPTION 'Your account is not banned' USING ERRCODE = '22023';
  END IF;
  IF _scope = 'community' AND NOT EXISTS (
       SELECT 1 FROM community_members
        WHERE user_id = _uid AND community_id = _community_id AND status = 'banned') THEN
    RAISE EXCEPTION 'You are not banned from this community' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (SELECT 1 FROM unban_requests
              WHERE user_id = _uid AND scope = _scope AND status = 'pending'
                AND community_id IS NOT DISTINCT FROM _community_id) THEN
    RAISE EXCEPTION 'Your request is already waiting for a decision' USING ERRCODE = '23505';
  END IF;
  IF (SELECT count(*) FROM unban_requests
       WHERE user_id = _uid AND scope = _scope AND status = 'rejected'
         AND community_id IS NOT DISTINCT FROM _community_id
         AND created_at > now() - interval '30 days') >= 3 THEN
    RAISE EXCEPTION 'Too many requests. You can ask again 30 days after your last one.' USING ERRCODE = '54000';
  END IF;

  INSERT INTO unban_requests (user_id, scope, community_id, message)
  VALUES (_uid, _scope, _community_id, _msg)
  RETURNING id INTO _id;
  RETURN _id;
END;
$$;


ALTER FUNCTION "public"."request_unban"("_scope" "text", "_community_id" "uuid", "_message" "text") OWNER TO "postgres";


