CREATE OR REPLACE FUNCTION "public"."resolve_meeting_dispute"("_eid" "uuid", "_sponsor_id" "uuid", "_keep" boolean, "_note" "text" DEFAULT NULL::"text", "_registration_id" "uuid" DEFAULT NULL::"uuid", "_speaker_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE _sid uuid; _side text; _row sponsor_meeting_interests%ROWTYPE; _to text; _email text;
BEGIN
  SELECT a.sponsor_id, a.side INTO _sid, _side FROM public._meeting_actor(_eid, _sponsor_id) a;
  IF _side <> 'organiser' THEN RAISE EXCEPTION 'Only the organiser settles a dispute.' USING ERRCODE = '42501'; END IF;
  PERFORM public._meeting_person_check(_eid, _registration_id, _speaker_id);

  SELECT * INTO _row FROM sponsor_meeting_interests smi
   WHERE smi.event_id = _eid AND smi.sponsor_id = _sid
     AND (smi.registration_id = _registration_id OR smi.speaker_id = _speaker_id)
   FOR UPDATE;
  IF NOT FOUND OR _row.dispute_status IS DISTINCT FROM 'open' THEN
    RAISE EXCEPTION 'There is no open dispute on this meeting.' USING ERRCODE = '22023';
  END IF;

  _to := CASE WHEN _keep THEN _row.status ELSE _row.dispute_requested_status END;

  UPDATE sponsor_meeting_interests smi SET
    status             = _to,
    met_at             = CASE WHEN _to = 'met' THEN coalesce(smi.met_at, now()) ELSE NULL END,
    status_cause       = CASE WHEN _to = 'not_met' THEN coalesce(smi.status_cause, 'other') END,
    status_reason      = CASE WHEN _to IN ('not_met', 'cancelled') THEN smi.status_reason END,
    scheduled_at       = CASE WHEN _to = 'interested' THEN NULL ELSE smi.scheduled_at END,
    location           = CASE WHEN _to = 'interested' THEN NULL ELSE smi.location END,
    outcome_at         = CASE WHEN _to IN ('met', 'not_met', 'cancelled') THEN coalesce(smi.outcome_at, now()) END,
    ever_progressed    = smi.ever_progressed OR _to <> 'interested',
    status_by          = auth.uid(),
    status_by_side     = 'organiser',
    status_changed_at  = now(),
    dispute_status     = 'resolved',
    dispute_resolution = CASE WHEN _keep THEN 'kept' ELSE 'changed' END,
    dispute_note       = NULLIF(btrim(left(_note, 1000)), ''),
    resolved_at        = now(),
    updated_at         = now()
  WHERE smi.id = _row.id;

  PERFORM public._log_meeting(_row.id, _eid, _sid, _registration_id, _speaker_id,
          CASE WHEN _keep THEN 'dispute_kept' ELSE 'dispute_changed' END, _row.status, _to, 'organiser', _note);

  SELECT u.email INTO _email FROM auth.users u WHERE u.id = auth.uid();
  INSERT INTO audit_logs (actor_id, actor_email, action, target_type, target_id, details)
  VALUES (auth.uid(), _email, 'meeting.dispute_resolved',
          CASE WHEN _speaker_id IS NOT NULL THEN 'speaker' ELSE 'registration' END,
          COALESCE(_speaker_id, _registration_id)::text,
          jsonb_build_object('event_id', _eid, 'sponsor_id', _sid, 'kept', _keep, 'to', _to));
END;
$$;


ALTER FUNCTION "public"."resolve_meeting_dispute"("_eid" "uuid", "_sponsor_id" "uuid", "_keep" boolean, "_note" "text", "_registration_id" "uuid", "_speaker_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_unban_request"("_request_id" "uuid", "_approve" boolean, "_note" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _req unban_requests%ROWTYPE;
  _note_clean text := NULLIF(btrim(COALESCE(_note, '')), '');
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501'; END IF;
  SELECT * INTO _req FROM unban_requests WHERE id = _request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Request not found' USING ERRCODE = 'P0002'; END IF;
  IF _req.status <> 'pending' THEN RAISE EXCEPTION 'This request was already decided' USING ERRCODE = '22023'; END IF;

  IF _req.scope = 'platform' AND NOT public.has_role(_uid, 'admin') THEN
    RAISE EXCEPTION 'Only a platform admin can decide this request' USING ERRCODE = '42501';
  END IF;
  IF _req.scope = 'community' AND NOT public.can_moderate_community(_uid, _req.community_id) THEN
    RAISE EXCEPTION 'Only this community''s organisers can decide this request' USING ERRCODE = '42501';
  END IF;
  IF char_length(COALESCE(_note_clean, '')) > 2000 THEN
    RAISE EXCEPTION 'Keep the note under 2000 characters' USING ERRCODE = '22023';
  END IF;

  UPDATE unban_requests
     SET status = CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,
         reviewed_by = _uid, reviewed_at = now(), review_note = _note_clean
   WHERE id = _request_id;

  IF _approve THEN
    PERFORM set_config('illuxus.unban_approved', 'on', true);
    IF _req.scope = 'platform' THEN
      UPDATE profiles SET banned_at = NULL, banned_reason = NULL, updated_at = now()
       WHERE user_id = _req.user_id;
    ELSE
      UPDATE community_members SET status = 'active'
       WHERE community_id = _req.community_id AND user_id = _req.user_id AND status = 'banned';
    END IF;
    PERFORM set_config('illuxus.unban_approved', 'off', true);
  END IF;

  IF _req.scope = 'platform' THEN
    INSERT INTO audit_logs(actor_id, actor_email, action, target_type, target_id, details)
    VALUES (_uid, public._audit_actor_email(_uid),
            CASE WHEN _approve THEN 'user.unbanned' ELSE 'user.unban_rejected' END,
            'profiles', _req.user_id::text,
            jsonb_build_object('request_id', _request_id, 'note', _note_clean));
  ELSE
    PERFORM _record_audit(
      CASE WHEN _approve THEN 'community.member.unbanned' ELSE 'community.member.unban_rejected' END,
      'community_member', _req.user_id::text,
      jsonb_build_object('community_id', _req.community_id, 'request_id', _request_id, 'note', _note_clean));
  END IF;
END;
$$;


ALTER FUNCTION "public"."review_unban_request"("_request_id" "uuid", "_approve" boolean, "_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revoke_certificate"("_certificate_id" "uuid", "_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  c record;
BEGIN
  SELECT * INTO c FROM public.certificates WHERE id = _certificate_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Certificate not found'; END IF;
  IF NOT public.can_manage_event_certificates(auth.uid(), c.event_id) THEN
    RAISE EXCEPTION 'You do not have permission to revoke certificates for this event' USING ERRCODE = '42501';
  END IF;
  IF c.status = 'revoked' THEN RETURN; END IF;
  UPDATE public.certificates
     SET status = 'revoked', revoked_at = now(), revoked_by = auth.uid(), revoked_reason = left(nullif(btrim(_reason), ''), 500)
   WHERE id = c.id;
  INSERT INTO public.certificate_audit (certificate_id, event_id, action, actor, detail)
       VALUES (c.id, c.event_id, 'revoked', auth.uid(), jsonb_build_object('reason', left(coalesce(_reason, ''), 500)));
END;
$$;


ALTER FUNCTION "public"."revoke_certificate"("_certificate_id" "uuid", "_reason" "text") OWNER TO "postgres";


