CREATE OR REPLACE FUNCTION "public"."self_check_in"("p_token" "text", "p_event_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("status" "text", "id" "uuid", "event_id" "uuid", "name" "text", "ticket_type" "text", "checked_in_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  r registrations%ROWTYPE; ev events%ROWTYPE; _wi boolean; _ee timestamptz;
  _k text; _ref uuid; _n text; _e text; _co text; _tt text;
  _ts timestamptz := now(); _d date; _rid uuid;
BEGIN
  IF p_token IS NULL OR length(trim(p_token)) = 0 THEN
    RETURN QUERY SELECT 'invalid'::text, NULL::uuid, NULL::uuid, NULL::text, NULL::text, NULL::timestamptz; RETURN;
  END IF;

  IF p_token LIKE 'speaker:%' OR p_token LIKE 'sponsor_contact:%' THEN
    IF p_event_id IS NULL THEN
      RETURN QUERY SELECT 'wrong_event'::text, NULL::uuid, NULL::uuid, NULL::text, NULL::text, NULL::timestamptz; RETURN;
    END IF;
    _k := split_part(p_token, ':', 1);
    BEGIN _ref := split_part(p_token, ':', 2)::uuid;
    EXCEPTION WHEN others THEN
      RETURN QUERY SELECT 'invalid'::text, NULL::uuid, NULL::uuid, NULL::text, NULL::text, NULL::timestamptz; RETURN;
    END;
    -- `_e` is still read internally: it is the key used to match or create the
    -- registration row. It is simply never returned to the caller now.
    IF _k = 'speaker' THEN
      SELECT sp.name, sp.email, sp.company, 'speaker' INTO _n, _e, _co, _tt
        FROM speakers sp
        JOIN event_speakers es ON es.speaker_id = sp.id AND es.event_id = p_event_id
       WHERE sp.id = _ref;
    ELSE
      SELECT sm.display_name, sm.email, sp.name, 'sponsor' INTO _n, _e, _co, _tt
        FROM sponsor_members sm
        JOIN sponsors sp ON sp.id = sm.sponsor_id
        JOIN event_sponsors es ON es.sponsor_id = sp.id AND es.event_id = p_event_id
       WHERE sm.id = _ref;
    END IF;
    IF _n IS NULL THEN
      RETURN QUERY SELECT 'not_found'::text, NULL::uuid, p_event_id, NULL::text, NULL::text, NULL::timestamptz; RETURN;
    END IF;
    SELECT reg.* INTO r FROM registrations reg
     WHERE reg.event_id = p_event_id AND reg.ticket_type = _tt
       AND lower(reg.email) = lower(COALESCE(_e, '')) LIMIT 1;
    IF NOT FOUND THEN
      INSERT INTO registrations(event_id, name, email, company, ticket_type, status, approval_status)
      VALUES (p_event_id, _n, COALESCE(_e, _n || '@no-email.local'), _co, _tt, 'confirmed', 'approved')
      RETURNING * INTO r;
    END IF;
  ELSE
    SELECT reg.* INTO r FROM registrations reg
     WHERE reg.qr_code = p_token OR reg.join_token = p_token OR reg.id::text = p_token LIMIT 1;
    IF NOT FOUND THEN
      RETURN QUERY SELECT 'not_found'::text, NULL::uuid, NULL::uuid, NULL::text, NULL::text, NULL::timestamptz; RETURN;
    END IF;
  END IF;

  IF p_event_id IS NOT NULL AND r.event_id <> p_event_id THEN
    RETURN QUERY SELECT 'wrong_event'::text, r.id, r.event_id, r.name, r.ticket_type, r.checked_in_at; RETURN;
  END IF;

  SELECT e.* INTO ev FROM events e WHERE e.id = r.event_id;
  IF FOUND THEN
    _ee := COALESCE(ev.end_date, ev.date);
    IF _ee IS NOT NULL AND now() > _ee + interval '2 hours' THEN
      RETURN QUERY SELECT 'expired'::text, r.id, r.event_id, r.name, r.ticket_type, r.checked_in_at; RETURN;
    END IF;
  END IF;

  IF r.status = 'cancelled' THEN
    RETURN QUERY SELECT 'cancelled'::text, r.id, r.event_id, r.name, r.ticket_type, r.checked_in_at; RETURN;
  END IF;

  _wi := (r.attendance_state = 'inside');
  _d  := (_ts AT TIME ZONE COALESCE(ev.timezone, 'UTC'))::date;
  _rid := r.id;

  -- REQ-14 (preserved verbatim): when already inside, return 'already' WITHOUT
  -- inserting any attendance_events row, so the public self-check-in flow can
  -- never check a participant out.
  IF _wi THEN
    RETURN QUERY SELECT 'already'::text, r.id, r.event_id, r.name, r.ticket_type, r.last_in_at;
  ELSE
    INSERT INTO attendance_events(registration_id, event_id, event_day, kind, method, occurred_at)
    VALUES (_rid, r.event_id, _d, 'in', 'self', _ts);
    SELECT reg.* INTO r FROM registrations reg WHERE reg.id = _rid;
    RETURN QUERY SELECT 'ok'::text, r.id, r.event_id, r.name, r.ticket_type, r.last_in_at;
  END IF;
END $$;


ALTER FUNCTION "public"."self_check_in"("p_token" "text", "p_event_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."self_check_in"("p_token" "text", "p_event_id" "uuid") IS 'Public self-check-in by QR / join token. Returns status + name + ticket_type; `email` was REMOVED from the return shape because this function is anon-callable and every path (including failures) previously disclosed the registrant address, which also defeated the REVOKE SELECT(email) on speakers/sponsors. Never inserts an out-event (REQ-14).';



CREATE OR REPLACE FUNCTION "public"."self_check_out"("p_token" "text", "p_event_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("status" "text", "id" "uuid", "event_id" "uuid", "name" "text", "ticket_type" "text", "checked_out_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  r registrations%ROWTYPE; ev events%ROWTYPE; _ee timestamptz;
  _k text; _ref uuid; _n text; _e text; _co text; _tt text;
  _ts timestamptz := now(); _d date; _rid uuid; _state text;
BEGIN
  IF p_token IS NULL OR length(trim(p_token)) = 0 THEN
    RETURN QUERY SELECT 'invalid'::text, NULL::uuid, NULL::uuid, NULL::text, NULL::text, NULL::timestamptz; RETURN;
  END IF;

  IF p_token LIKE 'speaker:%' OR p_token LIKE 'sponsor_contact:%' THEN
    IF p_event_id IS NULL THEN
      RETURN QUERY SELECT 'wrong_event'::text, NULL::uuid, NULL::uuid, NULL::text, NULL::text, NULL::timestamptz; RETURN;
    END IF;
    _k := split_part(p_token, ':', 1);
    BEGIN _ref := split_part(p_token, ':', 2)::uuid;
    EXCEPTION WHEN others THEN
      RETURN QUERY SELECT 'invalid'::text, NULL::uuid, NULL::uuid, NULL::text, NULL::text, NULL::timestamptz; RETURN;
    END;
    IF _k = 'speaker' THEN
      SELECT sp.name, sp.email, sp.company, 'speaker' INTO _n, _e, _co, _tt
        FROM speakers sp
        JOIN event_speakers es ON es.speaker_id = sp.id AND es.event_id = p_event_id
       WHERE sp.id = _ref;
    ELSE
      SELECT sm.display_name, sm.email, sp.name, 'sponsor' INTO _n, _e, _co, _tt
        FROM sponsor_members sm
        JOIN sponsors sp ON sp.id = sm.sponsor_id
        JOIN event_sponsors es ON es.sponsor_id = sp.id AND es.event_id = p_event_id
       WHERE sm.id = _ref;
    END IF;
    IF _n IS NULL THEN
      RETURN QUERY SELECT 'not_found'::text, NULL::uuid, p_event_id, NULL::text, NULL::text, NULL::timestamptz; RETURN;
    END IF;
    -- Self-check-out never lazy-creates a registration.
    SELECT reg.* INTO r FROM registrations reg
     WHERE reg.event_id = p_event_id AND reg.ticket_type = _tt
       AND lower(reg.email) = lower(COALESCE(_e, '')) LIMIT 1;
    IF NOT FOUND THEN
      RETURN QUERY SELECT 'not_checked_in_yet'::text, NULL::uuid, p_event_id, _n, _tt, NULL::timestamptz; RETURN;
    END IF;
  ELSE
    SELECT reg.* INTO r FROM registrations reg
     WHERE reg.qr_code = p_token OR reg.join_token = p_token OR reg.id::text = p_token LIMIT 1;
    IF NOT FOUND THEN
      RETURN QUERY SELECT 'not_found'::text, NULL::uuid, NULL::uuid, NULL::text, NULL::text, NULL::timestamptz; RETURN;
    END IF;
  END IF;

  IF p_event_id IS NOT NULL AND r.event_id <> p_event_id THEN
    RETURN QUERY SELECT 'wrong_event'::text, r.id, r.event_id, r.name, r.ticket_type, r.last_out_at; RETURN;
  END IF;

  SELECT e.* INTO ev FROM events e WHERE e.id = r.event_id;
  IF FOUND THEN
    _ee := COALESCE(ev.end_date, ev.date);
    IF _ee IS NOT NULL AND now() > _ee + interval '2 hours' THEN
      RETURN QUERY SELECT 'expired'::text, r.id, r.event_id, r.name, r.ticket_type, r.last_out_at; RETURN;
    END IF;
  END IF;

  IF r.status = 'cancelled' THEN
    RETURN QUERY SELECT 'cancelled'::text, r.id, r.event_id, r.name, r.ticket_type, r.last_out_at; RETURN;
  END IF;

  _state := r.attendance_state;
  _d := (_ts AT TIME ZONE COALESCE(ev.timezone, 'UTC'))::date;
  _rid := r.id;

  IF _state = 'inside' THEN
    INSERT INTO attendance_events(registration_id, event_id, event_day, kind, method, occurred_at)
    VALUES (_rid, r.event_id, _d, 'out', 'self', _ts);
    SELECT reg.* INTO r FROM registrations reg WHERE reg.id = _rid;
    RETURN QUERY SELECT 'ok'::text, r.id, r.event_id, r.name, r.ticket_type, r.last_out_at;
  ELSIF _state = 'outside' THEN
    RETURN QUERY SELECT 'already'::text, r.id, r.event_id, r.name, r.ticket_type, r.last_out_at;
  ELSE
    RETURN QUERY SELECT 'not_checked_in_yet'::text, r.id, r.event_id, r.name, r.ticket_type, NULL::timestamptz;
  END IF;
END $$;


ALTER FUNCTION "public"."self_check_out"("p_token" "text", "p_event_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."self_check_out"("p_token" "text", "p_event_id" "uuid") IS 'Public self-check-out by QR / join token. Mirrors self_check_in with inverted semantics. `email` was REMOVED from the return shape for the same anon-disclosure reason.';



CREATE OR REPLACE FUNCTION "public"."set_attendance"("p_reg_id" "uuid", "p_target" "text", "p_method" "text" DEFAULT 'qr'::"text") RETURNS TABLE("code" "text", "registration_id" "uuid", "attendance_state" "text", "last_in_at" timestamp with time zone, "last_out_at" timestamp with time zone, "total_minutes" integer, "name" "text", "ticket_type" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _code text;
BEGIN
  -- Delegate every rule (existence, authz, tracking window, status guards,
  -- state machine, and the audit-row INSERT) to the private helper. The
  -- helper runs as the same SECURITY DEFINER context, so its `auth.uid()`-
  -- driven authorization predicate sees this caller's identity.
  _code := public._apply_attendance(p_reg_id, p_target, p_method, auth.uid());

  -- Project the registration row the helper just (potentially) mutated via
  -- its `_attendance_recompute` AFTER-INSERT trigger. For every code other
  -- than 'not_found', this SELECT returns exactly one row.
  RETURN QUERY
    SELECT _code,
           r.id,
           r.attendance_state,
           r.last_in_at,
           r.last_out_at,
           r.total_minutes,
           r.name,
           r.ticket_type
    FROM public.registrations r
    WHERE r.id = p_reg_id;

  -- 'not_found' branch: keep the contract "exactly one row per call" so
  -- callers can rely on `.maybeSingle()` / first-row destructuring.
  IF NOT FOUND THEN
    RETURN QUERY
      SELECT _code,
             NULL::uuid,
             NULL::text,
             NULL::timestamptz,
             NULL::timestamptz,
             NULL::int,
             NULL::text,
             NULL::text;
  END IF;
END;
$$;


ALTER FUNCTION "public"."set_attendance"("p_reg_id" "uuid", "p_target" "text", "p_method" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_meeting_note"("_eid" "uuid", "_note" "text", "_registration_id" "uuid" DEFAULT NULL::"uuid", "_speaker_id" "uuid" DEFAULT NULL::"uuid", "_sponsor_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("note" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE _sid uuid; _side text; _id uuid; _clean text := NULLIF(btrim(left(_note, 2000)), '');
BEGIN
  SELECT a.sponsor_id, a.side INTO _sid, _side FROM public._meeting_actor(_eid, _sponsor_id) a;
  PERFORM public._meeting_person_check(_eid, _registration_id, _speaker_id);
  UPDATE sponsor_meeting_interests smi SET note = _clean, updated_at = now()
   WHERE smi.event_id = _eid AND smi.sponsor_id = _sid
     AND (smi.registration_id = _registration_id OR smi.speaker_id = _speaker_id)
  RETURNING smi.id INTO _id;
  IF _id IS NULL THEN RAISE EXCEPTION 'Mark interest first.' USING ERRCODE = '22023'; END IF;
  PERFORM public._log_meeting(_id, _eid, _sid, _registration_id, _speaker_id, 'note', NULL, NULL, _side);
  note := _clean;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."set_meeting_note"("_eid" "uuid", "_note" "text", "_registration_id" "uuid", "_speaker_id" "uuid", "_sponsor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_meeting_status"("_eid" "uuid", "_status" "text", "_registration_id" "uuid" DEFAULT NULL::"uuid", "_speaker_id" "uuid" DEFAULT NULL::"uuid", "_sponsor_id" "uuid" DEFAULT NULL::"uuid", "_scheduled_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "_location" "text" DEFAULT NULL::"text", "_reason" "text" DEFAULT NULL::"text", "_cause" "text" DEFAULT NULL::"text") RETURNS TABLE("registration_id" "uuid", "speaker_id" "uuid", "sponsor_id" "uuid", "status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  _sid uuid; _side text; _row sponsor_meeting_interests%ROWTYPE; _from text;
  _over boolean := public._event_over(_eid);
  _outcomes text[] := ARRAY['met', 'not_met', 'cancelled'];
  _cz text; _email text;
BEGIN
  IF _status IS NULL OR _status NOT IN ('interested', 'arranged', 'met', 'not_met', 'cancelled') THEN
    RAISE EXCEPTION 'Unknown meeting status.' USING ERRCODE = '22023';
  END IF;
  _cz := CASE WHEN _status = 'not_met' THEN coalesce(_cause, 'other') END;
  IF _cz IS NOT NULL AND _cz NOT IN ('attendee_no_show', 'sponsor_unavailable', 'rescheduled', 'other') THEN
    RAISE EXCEPTION 'Unknown reason the meeting did not happen.' USING ERRCODE = '22023';
  END IF;

  SELECT a.sponsor_id, a.side INTO _sid, _side FROM public._meeting_actor(_eid, _sponsor_id) a;
  PERFORM public._meeting_person_check(_eid, _registration_id, _speaker_id);

  SELECT * INTO _row FROM sponsor_meeting_interests smi
   WHERE smi.event_id = _eid AND smi.sponsor_id = _sid
     AND (smi.registration_id = _registration_id OR smi.speaker_id = _speaker_id)
   FOR UPDATE;

  IF NOT FOUND THEN
    IF _status NOT IN ('interested', 'arranged') THEN
      RAISE EXCEPTION 'Mark interest or arrange the meeting first.' USING ERRCODE = '22023';
    END IF;
    IF _side = 'sponsor' AND _status = 'arranged' AND _over THEN
      RAISE EXCEPTION 'EVENT_OVER' USING ERRCODE = '22023';
    END IF;
    INSERT INTO sponsor_meeting_interests (event_id, sponsor_id, registration_id, speaker_id, created_by)
         VALUES (_eid, _sid, _registration_id, _speaker_id, auth.uid())
    RETURNING * INTO _row;
    _from := NULL;
  ELSE
    _from := _row.status;
  END IF;

  IF _side = 'sponsor' THEN
    IF _row.dispute_status = 'open' THEN RAISE EXCEPTION 'DISPUTE_OPEN' USING ERRCODE = '22023'; END IF;
    IF _from = ANY (_outcomes) THEN
      IF _row.status_by_side = 'organiser' THEN RAISE EXCEPTION 'LOCKED_ORGANISER' USING ERRCODE = '42501'; END IF;
      IF coalesce(_row.outcome_at, _row.status_changed_at, now()) < now() - interval '15 minutes' THEN
        RAISE EXCEPTION 'LOCKED' USING ERRCODE = '42501';
      END IF;
    ELSE
      IF _over AND _status IN ('interested', 'arranged') AND _from IS NOT NULL THEN
        RAISE EXCEPTION 'EVENT_OVER' USING ERRCODE = '22023';
      END IF;
      IF _from = 'arranged' AND _status = 'interested' AND _row.status_by_side = 'organiser' THEN
        RAISE EXCEPTION 'ARRANGED_BY_ORGANISER' USING ERRCODE = '42501';
      END IF;
    END IF;
  ELSE
    IF _from = ANY (_outcomes) AND _over AND _from IS DISTINCT FROM _status AND coalesce(btrim(_reason), '') = '' THEN
      RAISE EXCEPTION 'REASON_REQUIRED' USING ERRCODE = '22023';
    END IF;
  END IF;

  UPDATE sponsor_meeting_interests smi SET
    status            = _status,
    scheduled_at      = CASE _status WHEN 'arranged' THEN _scheduled_at WHEN 'interested' THEN NULL ELSE smi.scheduled_at END,
    location          = CASE _status WHEN 'arranged' THEN NULLIF(btrim(left(_location, 200)), '') WHEN 'interested' THEN NULL ELSE smi.location END,
    met_at            = CASE _status WHEN 'met' THEN COALESCE(CASE WHEN smi.status = 'met' THEN smi.met_at END, now()) ELSE NULL END,
    status_reason     = CASE WHEN _status IN ('not_met', 'cancelled') THEN NULLIF(btrim(left(_reason, 500)), '') END,
    status_cause      = _cz,
    outcome_at        = CASE WHEN _status = ANY (_outcomes)
                             THEN CASE WHEN smi.status = ANY (_outcomes) THEN coalesce(smi.outcome_at, now()) ELSE now() END END,
    ever_progressed   = smi.ever_progressed OR _status <> 'interested',
    status_by         = auth.uid(),
    status_by_side    = _side,
    status_changed_at = now(),
    updated_at        = now(),
    dispute_status     = CASE WHEN _side = 'organiser' AND smi.dispute_status = 'open' THEN 'resolved' ELSE smi.dispute_status END,
    dispute_resolution = CASE WHEN _side = 'organiser' AND smi.dispute_status = 'open' THEN 'changed' ELSE smi.dispute_resolution END,
    dispute_note       = CASE WHEN _side = 'organiser' AND smi.dispute_status = 'open' THEN NULLIF(btrim(left(_reason, 1000)), '') ELSE smi.dispute_note END,
    resolved_at        = CASE WHEN _side = 'organiser' AND smi.dispute_status = 'open' THEN now() ELSE smi.resolved_at END
  WHERE smi.id = _row.id;

  PERFORM public._log_meeting(_row.id, _eid, _sid, _registration_id, _speaker_id,
          CASE WHEN _side = 'organiser' AND _row.dispute_status = 'open' THEN 'dispute_changed' ELSE _status END,
          _from, _status, _side, _reason, _cz,
          CASE WHEN _status = 'arranged' THEN _scheduled_at END,
          CASE WHEN _status = 'arranged' THEN NULLIF(btrim(left(_location, 200)), '') END);

  SELECT u.email INTO _email FROM auth.users u WHERE u.id = auth.uid();
  INSERT INTO audit_logs (actor_id, actor_email, action, target_type, target_id, details)
  VALUES (auth.uid(), _email, 'meeting.status_changed',
          CASE WHEN _speaker_id IS NOT NULL THEN 'speaker' ELSE 'registration' END,
          COALESCE(_speaker_id, _registration_id)::text,
          jsonb_build_object('event_id', _eid, 'sponsor_id', _sid, 'from', _from, 'to', _status, 'by', _side));

  registration_id := _registration_id; speaker_id := _speaker_id; sponsor_id := _sid; status := _status;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."set_meeting_status"("_eid" "uuid", "_status" "text", "_registration_id" "uuid", "_speaker_id" "uuid", "_sponsor_id" "uuid", "_scheduled_at" timestamp with time zone, "_location" "text", "_reason" "text", "_cause" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_my_sponsor_share_consent"("_registration" "uuid", "_consent" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _now boolean;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first' USING ERRCODE = '42501'; END IF;
  UPDATE registrations SET sponsor_share_consent = COALESCE(_consent, false)
   WHERE id = _registration AND user_id = auth.uid()
  RETURNING sponsor_share_consent INTO _now;
  IF NOT FOUND THEN RAISE EXCEPTION 'Registration not found' USING ERRCODE = 'P0002'; END IF;
  RETURN _now;
END;
$$;


ALTER FUNCTION "public"."set_my_sponsor_share_consent"("_registration" "uuid", "_consent" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shared_dataset_export"("_share" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _who text := public._share_reader(_share);
  x    sponsor_data_shares%ROWTYPE;
BEGIN
  IF _who IS NULL THEN RAISE EXCEPTION 'This shared data isn''t available to you' USING ERRCODE = '42501'; END IF;
  SELECT * INTO x FROM sponsor_data_shares WHERE id = _share;
  IF _who = 'sponsor' AND NOT x.allow_export THEN
    RAISE EXCEPTION 'The organiser hasn''t allowed this data to be downloaded' USING ERRCODE = '42501';
  END IF;
  IF _who = 'sponsor' THEN
    INSERT INTO sponsor_data_access_log (share_id, user_id, action, detail) VALUES (_share, auth.uid(), 'export', jsonb_build_object('rows', x.record_count));
  END IF;
  RETURN jsonb_build_object('fields', x.fields, 'rows',
    COALESCE((SELECT jsonb_agg(d.data ORDER BY lower(d.data ->> 'full_name')) FROM sponsor_data_share_rows d WHERE d.share_id = _share), '[]'::jsonb));
END;
$$;


ALTER FUNCTION "public"."shared_dataset_export"("_share" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shared_dataset_info"("_share" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _who text := public._share_reader(_share);
BEGIN
  IF _who IS NULL THEN RAISE EXCEPTION 'This shared data isn''t available to you' USING ERRCODE = '42501'; END IF;
  RETURN (
    SELECT to_jsonb(x) - 'fields' || jsonb_build_object('reader', _who, 'event', e.title, 'event_date', e.date,
             'title', es.tier, 'title_label', es.tier_label,
             'sponsor', COALESCE((SELECT c.name FROM companies c WHERE c.id = x.company_id), s.name))
      FROM sponsor_data_shares x JOIN events e ON e.id = x.event_id JOIN sponsors s ON s.id = x.sponsor_id
      LEFT JOIN event_sponsors es ON es.id = x.event_sponsor_id
     WHERE x.id = _share);
END;
$$;


ALTER FUNCTION "public"."shared_dataset_info"("_share" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shared_dataset_rows"("_share" "uuid", "_q" "text" DEFAULT NULL::"text", "_filter" "text" DEFAULT 'all'::"text", "_sort" "text" DEFAULT 'full_name'::"text", "_dir" "text" DEFAULT 'asc'::"text", "_limit" integer DEFAULT 25, "_offset" integer DEFAULT 0, "_type" "text" DEFAULT 'all'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _who  text := public._share_reader(_share);
  _t    text := lower(btrim(COALESCE(_q, '')));
  _ph   text := regexp_replace(COALESCE(_q, ''), '[^0-9]', '', 'g');
  _key  text := CASE WHEN _sort IN (SELECT f ->> 'key' FROM jsonb_array_elements(public._sponsor_share_fields()) f) THEN _sort ELSE 'full_name' END;
BEGIN
  IF _who IS NULL THEN RAISE EXCEPTION 'This shared data isn''t available to you' USING ERRCODE = '42501'; END IF;
  IF _who = 'sponsor' AND COALESCE(_offset, 0) = 0 AND _t = '' THEN
    INSERT INTO sponsor_data_access_log (share_id, user_id, action) VALUES (_share, auth.uid(), 'view');
  END IF;
  RETURN (
    WITH q AS (
      SELECT d.data FROM sponsor_data_share_rows d
       WHERE d.share_id = _share
         AND (_t = '' OR lower(COALESCE(d.data ->> 'full_name', '')) LIKE '%' || _t || '%'
              OR lower(COALESCE(d.data ->> 'company', '')) LIKE '%' || _t || '%'
              OR lower(COALESCE(d.data ->> 'designation', '')) LIKE '%' || _t || '%'
              OR lower(COALESCE(d.data ->> 'email', '')) LIKE '%' || _t || '%'
              OR (length(_ph) >= 4 AND regexp_replace(COALESCE(d.data ->> 'mobile', ''), '[^0-9]', '', 'g') LIKE '%' || _ph || '%'))
         AND CASE _filter
               WHEN 'attended' THEN d.data ->> 'attendance' = 'Attended'
               WHEN 'not_attended' THEN d.data ->> 'attendance' <> 'Attended'
               WHEN 'with_email' THEN d.data ? 'email'
               WHEN 'with_mobile' THEN d.data ? 'mobile'
               WHEN 'with_contact' THEN d.data ? 'email' OR d.data ? 'mobile'
               ELSE true END
         AND CASE _type
               WHEN 'speaker' THEN d.data ->> 'participant_type' = 'Speaker'
               WHEN 'attendee' THEN COALESCE(d.data ->> 'participant_type', 'Attendee') = 'Attendee'
               ELSE true END
    ), page AS (
      SELECT q.data FROM q
       ORDER BY CASE WHEN lower(_dir) = 'desc' THEN NULL ELSE lower(q.data ->> _key) END ASC NULLS LAST,
                CASE WHEN lower(_dir) = 'desc' THEN lower(q.data ->> _key) END DESC NULLS LAST,
                lower(q.data ->> 'full_name')
       LIMIT LEAST(GREATEST(COALESCE(_limit, 25), 1), 500) OFFSET GREATEST(COALESCE(_offset, 0), 0)
    )
    SELECT jsonb_build_object(
      'total', (SELECT count(*) FROM q),
      'fields', (SELECT x.fields FROM sponsor_data_shares x WHERE x.id = _share),
      'reader', _who,
      'rows', COALESCE((SELECT jsonb_agg(p.data) FROM page p), '[]'::jsonb))
  );
END;
$$;


ALTER FUNCTION "public"."shared_dataset_rows"("_share" "uuid", "_q" "text", "_filter" "text", "_sort" "text", "_dir" "text", "_limit" integer, "_offset" integer, "_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."site_asset_writable"("_name" "text", "_owner" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  _uid    uuid := auth.uid();
  _top    text := split_part(_name, '/', 1);
  _second text := split_part(_name, '/', 2);
  _third  text := split_part(_name, '/', 3);
  _org    text;
  _event  uuid;
  _uuid_re constant text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
BEGIN
  IF _uid IS NULL OR _name IS NULL THEN RETURN false; END IF;
  IF public.has_role(_uid, 'admin') THEN RETURN true; END IF;

  IF _top = 'event-covers' AND _second = 'drafts' THEN
    RETURN _third = _uid::text;
  ELSIF _top IN ('event-covers', 'event-creatives', 'ai-backgrounds') THEN
    RETURN _second ~ _uuid_re AND public._can_manage_event(_uid, _second::uuid);
  ELSIF _top = 'webinar-branding' THEN
    IF _second !~ _uuid_re THEN RETURN false; END IF;
    SELECT ws.event_id INTO _event FROM public.webinar_sessions ws WHERE ws.id = _second::uuid;
    RETURN _event IS NOT NULL AND public._can_manage_event(_uid, _event);
  ELSIF _top = 'brand-kits' OR _top LIKE 'org-%' THEN
    _org := CASE WHEN _top = 'brand-kits' THEN _second ELSE substring(_top FROM 5) END;
    RETURN _org ~ _uuid_re
       AND (public.is_org_owner(_uid, _org::uuid) OR public.is_org_member(_uid, _org::uuid));
  ELSIF _top IN ('speaker-photos', 'sponsor-logos') THEN
    -- No owner in the path: the uploader owns the file.
    RETURN _owner IS NULL OR _owner = _uid::text;
  END IF;

  -- The website's own files.
  RETURN false;
END;
$_$;


ALTER FUNCTION "public"."site_asset_writable"("_name" "text", "_owner" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."slugify"("_input" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$ SELECT trim(both '-' from regexp_replace(regexp_replace(lower(coalesce(_input,'')), '[^a-z0-9]+', '-', 'g'), '-+', '-', 'g')); $$;


ALTER FUNCTION "public"."slugify"("_input" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."speaker_portal_event_details"("_eid" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _email text;
  _result jsonb;
BEGIN
  SELECT email INTO _email FROM auth.users WHERE id = auth.uid();

  -- Verify the user is a speaker for this event by user_id OR email match.
  IF NOT EXISTS (
    SELECT 1 FROM speakers sp
    JOIN event_speakers es ON es.speaker_id = sp.id
    WHERE es.event_id = _eid
      AND (sp.user_id = auth.uid() OR lower(sp.email) = lower(COALESCE(_email, '')))
  ) THEN
    RETURN NULL;
  END IF;

  SELECT jsonb_build_object(
    'event', (SELECT to_jsonb(e) FROM (
      SELECT e.id, e.slug, e.title, e.description, e.date, e.end_date, e.location, e.venue,
             e.image_url, e.banner_landscape_url, e.status, e.timezone, e.event_format,
             o.name as organizer_name, o.slug as organizer_slug, o.logo_url as organizer_logo
      FROM events e LEFT JOIN organizations o ON o.id = e.org_id WHERE e.id = _eid
    ) e),
    'speaker', (SELECT to_jsonb(s) FROM (
      SELECT sp.id, sp.name, sp.email, sp.bio, sp.photo_url, sp.company, sp.designation,
             sp.linkedin_url, sp.company_website, sp.title, sp.first_name, sp.last_name
      FROM speakers sp
      JOIN event_speakers es ON es.speaker_id = sp.id
      WHERE es.event_id = _eid
        AND (sp.user_id = auth.uid() OR lower(sp.email) = lower(COALESCE(_email, '')))
      LIMIT 1
    ) s),
    'sessions', COALESCE((SELECT jsonb_agg(to_jsonb(ss) ORDER BY ss.start_time) FROM (
      SELECT s.id, s.title, s.description, s.session_type, s.start_time, s.end_time, s.location
      FROM sessions s
      WHERE s.event_id = _eid
        AND s.speaker_id IN (
          SELECT sp.id FROM speakers sp
          WHERE sp.user_id = auth.uid()
             OR lower(sp.email) = lower(COALESCE(_email, ''))
        )
    ) ss), '[]'::jsonb),
    'analytics', (SELECT jsonb_build_object(
      'total_registrations', (SELECT count(*) FROM registrations r
                                WHERE r.event_id = _eid AND r.approval_status = 'approved'),
      'checked_in_count',    (SELECT count(*) FROM registrations r
                                WHERE r.event_id = _eid AND r.checked_in = true)
    ))
  ) INTO _result;

  RETURN _result;
END;
$$;


ALTER FUNCTION "public"."speaker_portal_event_details"("_eid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."speaker_portal_events"() RETURNS TABLE("event_id" "uuid", "event_slug" "text", "event_title" "text", "event_description" "text", "event_date" timestamp with time zone, "end_date" timestamp with time zone, "location" "text", "venue" "text", "image_url" "text", "status" "text", "organizer_name" "text", "speaker_id" "uuid", "speaker_name" "text", "speaker_photo_url" "text", "speaker_company" "text", "session_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT DISTINCT
    e.id, e.slug, e.title, e.description, e.date, e.end_date, e.location, e.venue,
    COALESCE(NULLIF(e.banner_landscape_url, ''), NULLIF(e.image_url, ''), NULLIF(e.banner_portrait_url, '')),
    e.status,
    o.name,
    sp.id, sp.name, sp.photo_url, sp.company,
    (SELECT count(*) FROM sessions s WHERE s.event_id = e.id AND s.speaker_id = sp.id)
  FROM speakers sp
  JOIN event_speakers es ON es.speaker_id = sp.id
  JOIN events e         ON e.id = es.event_id
  LEFT JOIN organizations o ON o.id = e.org_id
  WHERE sp.user_id = auth.uid()
     OR lower(sp.email) = lower((SELECT email FROM auth.users WHERE id = auth.uid()))
  ORDER BY e.date DESC;
$$;


ALTER FUNCTION "public"."speaker_portal_events"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."speakers_link_person"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' OR NEW.email IS DISTINCT FROM OLD.email THEN
    NEW.person_id := public.ensure_contact_person(
      NEW.email, NEW.name, NEW.mobile_country_code, NEW.mobile_number, NEW.linkedin_url,
      NEW.company, NULL, NEW.designation, 'speaker');
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."speakers_link_person"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sponsor_event_counts"("_eid" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- The event's sponsors (their accepted team members) and its organisers.
  IF NOT EXISTS (SELECT 1 FROM public._my_event_sponsors(_eid))
     AND NOT EXISTS (SELECT 1 FROM events e WHERE e.id = _eid AND (e.user_id = auth.uid() OR public.has_role(auth.uid(), 'admin')
                     OR EXISTS (SELECT 1 FROM org_members m WHERE m.org_id = e.org_id AND m.user_id = auth.uid()))) THEN
    RAISE EXCEPTION 'Not allowed' USING ERRCODE = '42501';
  END IF;
  RETURN (
    WITH seats AS (
      SELECT r.*, (r.ticket_type = 'speaker' OR EXISTS (
               SELECT 1 FROM event_speakers es JOIN speakers sp ON sp.id = es.speaker_id
                WHERE es.event_id = r.event_id AND lower(NULLIF(btrim(sp.email), '')) = lower(r.email))) AS is_speaker
        FROM registrations r
       WHERE r.event_id = _eid AND r.status <> 'cancelled' AND r.approval_status NOT IN ('declined', 'waitlisted')
    )
    SELECT jsonb_build_object(
      'registered', (SELECT count(*) FROM seats),
      'checked_in', (SELECT count(*) FROM seats WHERE checked_in),
      'speakers', (SELECT count(*) FROM event_speakers WHERE event_id = _eid),
      'speakers_checked_in', (SELECT count(*) FROM seats WHERE is_speaker AND checked_in),
      'attendees', (SELECT count(*) FROM seats WHERE NOT is_speaker),
      'attendees_checked_in', (SELECT count(*) FROM seats WHERE NOT is_speaker AND checked_in))
  );
END;
$$;


ALTER FUNCTION "public"."sponsor_event_counts"("_eid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sponsor_meeting_report"("_eid" "uuid", "_sponsor_id" "uuid") RETURNS TABLE("kind" "text", "name" "text", "email" "text", "company" "text", "designation" "text", "status" "text", "status_cause" "text", "status_reason" "text", "interested_at" timestamp with time zone, "scheduled_at" timestamp with time zone, "location" "text", "met_at" timestamp with time zone, "checked_in" boolean, "checked_in_at" timestamp with time zone, "status_by_side" "text", "dispute_status" "text", "dispute_reason" "text", "dispute_resolution" "text", "dispute_note" "text", "history" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
BEGIN
  IF NOT public._can_view_event_registrations(_eid) THEN
    RAISE EXCEPTION 'Only the event organisers can download this report.' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
    SELECT CASE WHEN smi.speaker_id IS NOT NULL THEN 'speaker' ELSE 'attendee' END,
           coalesce(r.name, sp.name), coalesce(r.email, sp.email), coalesce(r.company, sp.company),
           coalesce(r.designation, NULLIF(sp.designation, ''), sp.title),
           smi.status, smi.status_cause, smi.status_reason, smi.created_at,
           smi.scheduled_at, smi.location, smi.met_at,
           coalesce(r.checked_in, sr.checked_in, false), coalesce(r.checked_in_at, sr.checked_in_at),
           smi.status_by_side,
           smi.dispute_status, smi.dispute_reason, smi.dispute_resolution, smi.dispute_note,
           coalesce((SELECT jsonb_agg(jsonb_build_object(
                       'at', me.created_at, 'action', me.action, 'from', me.from_status, 'to', me.to_status,
                       'side', me.side, 'reason', me.reason, 'cause', me.cause) ORDER BY me.created_at, me.id)
                       FROM meeting_events me
                      WHERE me.event_id = _eid AND me.sponsor_id = _sponsor_id
                        AND (me.registration_id = smi.registration_id OR me.speaker_id = smi.speaker_id)), '[]'::jsonb)
      FROM sponsor_meeting_interests smi
      LEFT JOIN registrations r ON r.id = smi.registration_id
      LEFT JOIN speakers sp ON sp.id = smi.speaker_id
      LEFT JOIN LATERAL (
        SELECT x.checked_in, x.checked_in_at FROM registrations x
         WHERE sp.id IS NOT NULL AND x.event_id = _eid AND x.ticket_type = 'speaker'
           AND lower(x.email) = lower(coalesce(sp.email, ''))
         LIMIT 1
      ) sr ON true
     WHERE smi.event_id = _eid AND smi.sponsor_id = _sponsor_id
     ORDER BY coalesce(r.name, sp.name);
END;
$$;


ALTER FUNCTION "public"."sponsor_meeting_report"("_eid" "uuid", "_sponsor_id" "uuid") OWNER TO "postgres";


