ALTER FUNCTION "public"."sponsor_members_link_person"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sponsor_portal_events"() RETURNS TABLE("event_id" "uuid", "event_title" "text", "event_date" timestamp with time zone, "end_date" timestamp with time zone, "location" "text", "sponsor_id" "uuid", "sponsor_name" "text", "tier" "text", "registrations_count" bigint, "checked_in_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH user_sponsors AS (
    SELECT sm.sponsor_id
      FROM sponsor_members sm
     WHERE sm.user_id = auth.uid() AND sm.accepted_at IS NOT NULL
    UNION
    SELECT s.id AS sponsor_id
      FROM sponsors s
     WHERE s.user_id = auth.uid()
  )
  SELECT
    e.id, e.title, e.date, e.end_date, e.location,
    s.id, s.name, COALESCE(es.tier_override, CASE WHEN es.tier = 'custom' THEN es.tier_label END, es.tier, s.tier),
    (SELECT count(*) FROM registrations r WHERE r.event_id = e.id AND r.approval_status = 'approved'),
    (SELECT count(*) FROM registrations r WHERE r.event_id = e.id AND r.checked_in = true)
  FROM user_sponsors us
  JOIN sponsors s         ON s.id = us.sponsor_id
  JOIN event_sponsors es  ON es.sponsor_id = s.id
  JOIN events e           ON e.id = es.event_id
  ORDER BY e.date DESC;
$$;


ALTER FUNCTION "public"."sponsor_portal_events"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sponsor_portal_people"("_eid" "uuid") RETURNS TABLE("kind" "text", "id" "uuid", "name" "text", "company" "text", "designation" "text", "ticket_type" "text", "checked_in" boolean, "checked_in_at" timestamp with time zone, "meeting_interest" boolean, "meeting_status" "text", "interested_at" timestamp with time zone, "scheduled_at" timestamp with time zone, "location" "text", "met_at" timestamp with time zone, "status_reason" "text", "note" "text", "status_by_side" "text", "status_changed_at" timestamp with time zone, "status_cause" "text", "ever_progressed" boolean, "outcome_at" timestamp with time zone, "dispute_status" "text", "dispute_reason" "text", "dispute_requested_status" "text", "disputed_at" timestamp with time zone, "dispute_resolution" "text", "dispute_note" "text", "resolved_at" timestamp with time zone, "event_over" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH allowed AS (
    SELECT 1 FROM sponsor_members sm JOIN event_sponsors es ON es.sponsor_id = sm.sponsor_id
     WHERE sm.user_id = auth.uid() AND sm.accepted_at IS NOT NULL AND es.event_id = _eid
    UNION ALL
    SELECT 1 FROM sponsors s JOIN event_sponsors es ON es.sponsor_id = s.id
     WHERE s.user_id = auth.uid() AND es.event_id = _eid
    LIMIT 1
  ),
  mine AS (
    SELECT smi.* FROM sponsor_meeting_interests smi
     WHERE smi.event_id = _eid
       AND smi.sponsor_id IN (SELECT sponsor_id FROM public._my_event_sponsors(_eid))
  ),
  over AS (SELECT public._event_over(_eid) AS v)
  SELECT 'speaker', sp.id, sp.name, sp.company, COALESCE(NULLIF(sp.designation, ''), sp.title), 'speaker',
         COALESCE(r.checked_in, false), r.checked_in_at,
         m.id IS NOT NULL, m.status, m.created_at, m.scheduled_at, m.location,
         m.met_at, m.status_reason, m.note, m.status_by_side, m.status_changed_at,
         m.status_cause, m.ever_progressed, m.outcome_at,
         m.dispute_status, m.dispute_reason, m.dispute_requested_status, m.disputed_at,
         m.dispute_resolution, m.dispute_note, m.resolved_at, (SELECT v FROM over)
    FROM event_speakers esp
    JOIN speakers sp ON sp.id = esp.speaker_id
    LEFT JOIN registrations r ON r.event_id = _eid AND r.ticket_type = 'speaker'
                              AND lower(r.email) = lower(COALESCE(sp.email, ''))
    LEFT JOIN LATERAL (SELECT * FROM mine WHERE mine.speaker_id = sp.id ORDER BY mine.created_at LIMIT 1) m ON true
   WHERE esp.event_id = _eid AND EXISTS(SELECT 1 FROM allowed)
  UNION ALL
  SELECT 'attendee', r.id, r.name, r.company, r.designation, r.ticket_type, r.checked_in, r.checked_in_at,
         m.id IS NOT NULL, m.status, m.created_at, m.scheduled_at, m.location,
         m.met_at, m.status_reason, m.note, m.status_by_side, m.status_changed_at,
         m.status_cause, m.ever_progressed, m.outcome_at,
         m.dispute_status, m.dispute_reason, m.dispute_requested_status, m.disputed_at,
         m.dispute_resolution, m.dispute_note, m.resolved_at, (SELECT v FROM over)
    FROM registrations r
    LEFT JOIN LATERAL (SELECT * FROM mine WHERE mine.registration_id = r.id ORDER BY mine.created_at LIMIT 1) m ON true
   WHERE r.event_id = _eid AND r.approval_status = 'approved' AND r.ticket_type <> 'speaker'
     AND EXISTS(SELECT 1 FROM allowed);
$$;


ALTER FUNCTION "public"."sponsor_portal_people"("_eid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sponsor_set_meeting_interest"("_eid" "uuid", "_registration_id" "uuid", "_interested" boolean, "_sponsor_id" "uuid" DEFAULT NULL::"uuid", "_speaker_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("registration_id" "uuid", "speaker_id" "uuid", "sponsor_id" "uuid", "meeting_interest" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE _sid uuid; _count int; _mid uuid; _row sponsor_meeting_interests%ROWTYPE; _email text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first.' USING ERRCODE = '42501'; END IF;
  IF num_nonnulls(_registration_id, _speaker_id) <> 1 THEN
    RAISE EXCEPTION 'Choose one attendee or one speaker.' USING ERRCODE = '22023';
  END IF;

  SELECT count(*) INTO _count FROM public._my_event_sponsors(_eid);
  IF _count = 0 THEN RAISE EXCEPTION 'You are not a sponsor of this event.' USING ERRCODE = '42501'; END IF;
  IF _sponsor_id IS NOT NULL THEN
    SELECT ms.sponsor_id INTO _sid FROM public._my_event_sponsors(_eid) ms WHERE ms.sponsor_id = _sponsor_id;
    IF _sid IS NULL THEN RAISE EXCEPTION 'You are not that sponsor.' USING ERRCODE = '42501'; END IF;
  ELSIF _count = 1 THEN
    SELECT ms.sponsor_id INTO _sid FROM public._my_event_sponsors(_eid) ms;
  ELSE
    RAISE EXCEPTION 'You represent more than one sponsor of this event; choose which.' USING ERRCODE = '22023';
  END IF;

  PERFORM public._meeting_person_check(_eid, _registration_id, _speaker_id);

  IF _interested THEN
    IF _speaker_id IS NOT NULL THEN
      INSERT INTO sponsor_meeting_interests (event_id, sponsor_id, speaker_id, created_by)
           VALUES (_eid, _sid, _speaker_id, auth.uid())
      ON CONFLICT (event_id, sponsor_id, speaker_id) WHERE speaker_id IS NOT NULL DO NOTHING
      RETURNING id INTO _mid;
    ELSE
      INSERT INTO sponsor_meeting_interests (event_id, sponsor_id, registration_id, created_by)
           VALUES (_eid, _sid, _registration_id, auth.uid())
      ON CONFLICT ON CONSTRAINT sponsor_meeting_interests_unique DO NOTHING
      RETURNING id INTO _mid;
    END IF;
    IF _mid IS NOT NULL THEN
      PERFORM public._log_meeting(_mid, _eid, _sid, _registration_id, _speaker_id, 'interested', NULL, 'interested', 'sponsor');
    END IF;
  ELSE
    SELECT * INTO _row FROM sponsor_meeting_interests smi
     WHERE smi.event_id = _eid AND smi.sponsor_id = _sid
       AND (smi.registration_id = _registration_id OR smi.speaker_id = _speaker_id)
     FOR UPDATE;
    IF FOUND THEN
      IF _row.status <> 'interested' OR _row.ever_progressed THEN
        RAISE EXCEPTION 'CANCEL_INSTEAD' USING ERRCODE = '22023';
      END IF;
      PERFORM public._log_meeting(_row.id, _eid, _sid, _registration_id, _speaker_id, 'removed', 'interested', NULL, 'sponsor');
      DELETE FROM sponsor_meeting_interests smi WHERE smi.id = _row.id;
    END IF;
  END IF;

  SELECT u.email INTO _email FROM auth.users u WHERE u.id = auth.uid();
  INSERT INTO audit_logs (actor_id, actor_email, action, target_type, target_id, details)
  VALUES (auth.uid(), _email,
          CASE WHEN _interested THEN 'meeting_interest.added' ELSE 'meeting_interest.removed' END,
          CASE WHEN _speaker_id IS NOT NULL THEN 'speaker' ELSE 'registration' END,
          COALESCE(_speaker_id, _registration_id)::text,
          jsonb_build_object('event_id', _eid, 'sponsor_id', _sid));

  registration_id := _registration_id; speaker_id := _speaker_id; sponsor_id := _sid; meeting_interest := _interested;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."sponsor_set_meeting_interest"("_eid" "uuid", "_registration_id" "uuid", "_interested" boolean, "_sponsor_id" "uuid", "_speaker_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sponsor_shared_datasets"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', x.id, 'version', x.version, 'event_id', e.id, 'event', e.title, 'event_date', e.date,
           'title', es.tier, 'title_label', es.tier_label,
           'sponsor', COALESCE((SELECT c.name FROM companies c WHERE c.id = public._canonical_company(s.company_id)), s.name),
           'record_count', x.record_count, 'with_email', x.with_email, 'with_mobile', x.with_mobile,
           'shared_at', x.shared_at, 'shared_by', (SELECT COALESCE(p.display_name, u.email) FROM auth.users u LEFT JOIN profiles p ON p.user_id = u.id WHERE u.id = x.shared_by),
           'allow_export', x.allow_export, 'status', x.status) ORDER BY x.shared_at DESC), '[]'::jsonb)
    FROM sponsor_data_shares x
    JOIN event_sponsors es ON es.id = x.event_sponsor_id
    JOIN events e ON e.id = x.event_id
    JOIN sponsors s ON s.id = es.sponsor_id
   WHERE x.status = 'active' AND public._share_reader(x.id) = 'sponsor';
$$;


ALTER FUNCTION "public"."sponsor_shared_datasets"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."suggest_companies"("_q" "text", "_limit" integer DEFAULT 8) RETURNS TABLE("company_id" "uuid", "name" "text", "verified" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid       uuid := auth.uid();
  _p         text;
  _organiser boolean;
  _headers   jsonb;
  _ip        text;
  _ip_hash   text;
BEGIN
  -- What was typed, as a key prefix (accents and punctuation removed; this
  -- also removes LIKE's % and _).
  _p := btrim(regexp_replace(replace(public.fold_text(_q), '&', ' and '),
              '[!-/:-@\[-`{-~\u00A0-\u00BF\u2010-\u2027\u2030-\u205E\s]+', ' ', 'g'));
  _p := regexp_replace(_p, '^the ', '');
  IF length(_p) < 2 THEN RETURN; END IF;

  _organiser := public._is_organiser(_uid);

  IF _uid IS NULL THEN
    BEGIN
      _headers := NULLIF(current_setting('request.headers', true), '')::jsonb;
    EXCEPTION WHEN others THEN
      _headers := NULL;
    END;
    _ip := COALESCE(_headers ->> 'cf-connecting-ip',
                    btrim(split_part(_headers ->> 'x-forwarded-for', ',', 1)),
                    'unknown');
    _ip_hash := encode(sha256(convert_to('company_suggest:' || _ip, 'UTF8')), 'hex');
    IF (SELECT count(*) FROM guest_rate_limits
         WHERE bucket = 'company_suggest' AND key_hash = _ip_hash
           AND created_at > now() - interval '1 minute') >= 60 THEN
      RAISE EXCEPTION 'Too many lookups — wait a moment' USING ERRCODE = '54000';
    END IF;
    INSERT INTO guest_rate_limits (bucket, key_hash) VALUES ('company_suggest', _ip_hash);
  END IF;

  RETURN QUERY
  SELECT c.id, c.name, c.verification_status = 'verified'
    FROM companies c
   WHERE c.verification_status <> 'rejected' AND c.merged_into IS NULL
     AND (_organiser OR c.verification_status = 'verified' OR c.source IN ('sponsor','organiser') OR c.entry_count >= 2)
     AND (c.name_key LIKE _p || '%'
          OR c.name_key LIKE '% ' || _p || '%'
          OR EXISTS (SELECT 1 FROM company_aliases a WHERE a.company_id = c.id AND a.alias_key LIKE _p || '%'))
   ORDER BY (c.name_key LIKE _p || '%') DESC,
            (c.verification_status = 'verified') DESC,
            c.entry_count DESC,
            c.name
   LIMIT LEAST(GREATEST(COALESCE(_limit, 8), 1), 8);
END;
$$;


ALTER FUNCTION "public"."suggest_companies"("_q" "text", "_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."support_tickets_before_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.ticket_number IS NULL OR NEW.ticket_number = '' THEN
    NEW.ticket_number := public.generate_ticket_number();
  END IF;
  NEW.email := lower(trim(NEW.email));
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."support_tickets_before_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."support_tickets_touch_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  NEW.updated_at := now();
  IF NEW.status = 'resolved' AND (OLD.status IS DISTINCT FROM 'resolved') AND NEW.resolved_at IS NULL THEN
    NEW.resolved_at := now();
  END IF;
  IF NEW.status = 'closed' AND (OLD.status IS DISTINCT FROM 'closed') AND NEW.closed_at IS NULL THEN
    NEW.closed_at := now();
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."support_tickets_touch_updated_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_profile_to_registrations"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN UPDATE registrations r SET title=COALESCE(NEW.title,r.title),first_name=COALESCE(NEW.first_name,r.first_name),last_name=COALESCE(NEW.last_name,r.last_name),name=COALESCE(NULLIF(TRIM(COALESCE(NEW.first_name,'')||' '||COALESCE(NEW.last_name,'')),''),r.name),designation=COALESCE(NEW.designation,r.designation),company=COALESCE(NEW.company,r.company),mobile_country_code=COALESCE(NEW.mobile_country_code,r.mobile_country_code),mobile_number=COALESCE(NEW.mobile_number,r.mobile_number),linkedin_url=COALESCE(NEW.linkedin_url,r.linkedin_url),company_website=COALESCE(NEW.company_website,r.company_website),company_employee_count=COALESCE(NEW.company_employee_count,r.company_employee_count),industry=COALESCE(NEW.industry,r.industry),updated_at=now() FROM events e WHERE r.user_id=NEW.user_id AND r.event_id=e.id AND COALESCE(e.end_date,e.date)>=now(); RETURN NEW; END; $$;


ALTER FUNCTION "public"."sync_profile_to_registrations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."take_rate_limit"("_bucket" "text", "_key_hash" "text", "_max" integer, "_window_seconds" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _used integer;
BEGIN
  IF _bucket IS NULL OR _key_hash IS NULL OR _max IS NULL OR _max < 1 OR _window_seconds IS NULL OR _window_seconds < 1 THEN
    RAISE EXCEPTION 'take_rate_limit: bucket, key, max >= 1 and window >= 1 are required' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(_bucket || ':' || _key_hash, 0));

  SELECT count(*) INTO _used FROM guest_rate_limits
   WHERE bucket = _bucket AND key_hash = _key_hash
     AND created_at > now() - make_interval(secs => _window_seconds);
  IF _used >= _max THEN
    RETURN false;
  END IF;

  INSERT INTO guest_rate_limits (bucket, key_hash) VALUES (_bucket, _key_hash);
  DELETE FROM guest_rate_limits
   WHERE bucket = _bucket AND key_hash = _key_hash
     AND created_at < now() - make_interval(secs => _window_seconds) - interval '1 day';
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."take_rate_limit"("_bucket" "text", "_key_hash" "text", "_max" integer, "_window_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toggle_attendance"("p_reg_id" "uuid", "p_method" "text" DEFAULT 'manual'::"text") RETURNS TABLE("state" "text", "event_id" "uuid", "occurred_at" timestamp with time zone, "total_minutes" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE r registrations%ROWTYPE; _k text; _ts timestamptz:=now(); _d date;
BEGIN SELECT * INTO r FROM registrations WHERE id=p_reg_id; IF NOT FOUND THEN RAISE EXCEPTION 'Not found'; END IF;
  IF NOT(has_role(auth.uid(),'admin') OR is_event_owner(auth.uid(),r.event_id) OR r.user_id=auth.uid()) THEN RAISE EXCEPTION 'Unauthorized'; END IF;
  IF event_tracking_closed(r.event_id) THEN RETURN QUERY SELECT 'tracking_closed'::text,r.event_id,_ts,r.total_minutes; RETURN; END IF;
  _k:=CASE WHEN r.attendance_state='inside' THEN 'out' ELSE 'in' END;
  _d:=(_ts AT TIME ZONE COALESCE((SELECT timezone FROM events WHERE id=r.event_id),'UTC'))::date;
  INSERT INTO attendance_events(registration_id,event_id,event_day,kind,method,actor_id,occurred_at) VALUES(r.id,r.event_id,_d,_k,COALESCE(p_method,'manual'),auth.uid(),_ts);
  SELECT * INTO r FROM registrations WHERE id=p_reg_id;
  RETURN QUERY SELECT r.attendance_state,r.event_id,_ts,r.total_minutes;
END; $$;


ALTER FUNCTION "public"."toggle_attendance"("p_reg_id" "uuid", "p_method" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unavailable_venue_ids"("p_start" "date", "p_end" "date" DEFAULT NULL::"date", "p_exclude_event_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with bounds as (
    select p_start as s, coalesce(p_end, p_start) as e
  )
  select v.id
    from public.venues v, bounds b
   where exists (
           select 1 from public.vendor_availability a
            where a.vendor_id = v.vendor_id
              and (a.venue_id is null or a.venue_id = v.id)
              and a.status in ('held', 'booked')
              and a.date between b.s and b.e
         )
      or exists (
           select 1
             from public.event_venue_selections s
             join public.events ev on ev.id = s.event_id
            where s.status = 'accepted'
              and (s.venue_id = v.id or (s.venue_id is null and s.vendor_id = v.vendor_id))
              and (p_exclude_event_id is null or s.event_id <> p_exclude_event_id)
              and ev.date::date <= b.e
              and coalesce(ev.end_date, ev.date)::date >= b.s
         );
$$;


ALTER FUNCTION "public"."unavailable_venue_ids"("p_start" "date", "p_end" "date", "p_exclude_event_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."unavailable_venue_ids"("p_start" "date", "p_end" "date", "p_exclude_event_id" "uuid") IS 'Venue ids that cannot be booked on any day of [p_start, p_end]: manual / booking blocks in vendor_availability, or an accepted event_venue_selections row on an overlapping event. SECURITY DEFINER so organizers see clashes with other organizations'' events without reading those rows.';



CREATE OR REPLACE FUNCTION "public"."unban_requests_to_review"("_community_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "user_id" "uuid", "display_name" "text", "avatar_url" "text", "scope" "text", "community_id" "uuid", "community_name" "text", "message" "text", "created_at" timestamp with time zone, "ban_reason" "text", "banned_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _admin boolean := public.has_role(_uid, 'admin');
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501'; END IF;
  IF _community_id IS NULL AND NOT _admin THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;
  IF _community_id IS NOT NULL AND NOT public.can_moderate_community(_uid, _community_id) THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
    SELECT ur.id, ur.user_id,
           COALESCE(NULLIF(btrim(concat_ws(' ', p.first_name, p.last_name)), ''), p.display_name, 'Member'),
           p.avatar_url, ur.scope, ur.community_id, c.name, ur.message, ur.created_at,
           CASE WHEN ur.scope = 'platform' THEN p.banned_reason END,
           CASE WHEN ur.scope = 'platform' THEN p.banned_at END
      FROM unban_requests ur
      LEFT JOIN profiles p ON p.user_id = ur.user_id
      LEFT JOIN communities c ON c.id = ur.community_id
     WHERE ur.status = 'pending'
       AND (CASE WHEN _community_id IS NULL THEN ur.scope = 'platform'
                 ELSE ur.scope = 'community' AND ur.community_id = _community_id END)
     ORDER BY ur.created_at;
END;
$$;


ALTER FUNCTION "public"."unban_requests_to_review"("_community_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."undo_attendance"("p_reg_id" "uuid", "p_kind" "text") RETURNS TABLE("deleted" boolean, "state" "text", "total_minutes" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE r registrations%ROWTYPE; _tid uuid; _to timestamptz; _lc boolean:=false;
BEGIN IF p_kind NOT IN('in','out') THEN RAISE EXCEPTION 'Invalid'; END IF;
  SELECT * INTO r FROM registrations WHERE id=p_reg_id; IF NOT FOUND THEN RAISE EXCEPTION 'Not found'; END IF;
  IF NOT(has_role(auth.uid(),'admin') OR is_event_owner(auth.uid(),r.event_id) OR r.user_id=auth.uid()) THEN RAISE EXCEPTION 'Unauthorized'; END IF;
  IF p_kind='in' THEN SELECT id,occurred_at INTO _tid,_to FROM attendance_events WHERE registration_id=p_reg_id AND kind='in' ORDER BY occurred_at DESC LIMIT 1;
  ELSE SELECT id,occurred_at INTO _tid,_to FROM attendance_events WHERE registration_id=p_reg_id AND kind IN('out','auto_out') ORDER BY occurred_at DESC LIMIT 1; END IF;
  IF _tid IS NOT NULL THEN DELETE FROM attendance_events WHERE id=_tid;
  ELSE
    IF p_kind='in' AND r.attendance_state IN('inside','outside') THEN UPDATE registrations SET attendance_state='never',checked_in=false,checked_in_at=NULL,last_in_at=NULL,last_out_at=NULL,total_minutes=0,updated_at=now() WHERE id=p_reg_id; _lc:=true;
    ELSIF p_kind='out' AND r.attendance_state='outside' THEN
      IF r.last_in_at IS NOT NULL THEN UPDATE registrations SET attendance_state='inside',checked_in=true,last_out_at=NULL,updated_at=now() WHERE id=p_reg_id;
      ELSE UPDATE registrations SET attendance_state='never',checked_in=false,last_out_at=NULL,updated_at=now() WHERE id=p_reg_id; END IF; _lc:=true;
    END IF;
    IF NOT _lc THEN RETURN QUERY SELECT false,r.attendance_state,r.total_minutes; RETURN; END IF;
  END IF;
  SELECT * INTO r FROM registrations WHERE id=p_reg_id;
  RETURN QUERY SELECT true,r.attendance_state,r.total_minutes;
END; $$;


ALTER FUNCTION "public"."undo_attendance"("p_reg_id" "uuid", "p_kind" "text") OWNER TO "postgres";


