CREATE OR REPLACE FUNCTION "public"."update_vendor_rating"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_vendor_id uuid;
  v_avg numeric(3,2);
  v_count int;
BEGIN
  -- Get vendor_id from the booking
  SELECT vendor_id INTO v_vendor_id
  FROM vendor_bookings WHERE id = NEW.booking_id;

  -- Only recompute from organizer reviews (about the vendor's performance)
  IF NEW.reviewer_type = 'organizer' THEN
    SELECT AVG(rating)::numeric(3,2), COUNT(*)
    INTO v_avg, v_count
    FROM vendor_reviews vr
    JOIN vendor_bookings vb ON vb.id = vr.booking_id
    WHERE vb.vendor_id = v_vendor_id
      AND vr.reviewer_type = 'organizer';

    UPDATE vendors
    SET rating_avg = v_avg, rating_count = v_count, updated_at = now()
    WHERE id = v_vendor_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_vendor_rating"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."user_role_assignments"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'has_speaker', EXISTS(
      -- match by user_id first (most reliable), fall back to email
      SELECT 1 FROM speakers sp
      JOIN event_speakers es ON es.speaker_id = sp.id
      WHERE sp.user_id = auth.uid()
         OR lower(sp.email) = lower((SELECT email FROM auth.users WHERE id = auth.uid()))
    ),
    'has_sponsor', EXISTS(
      -- team-invite path: a `sponsor_members` row that's been accepted
      SELECT 1 FROM sponsor_members sm
      WHERE sm.user_id = auth.uid() AND sm.accepted_at IS NOT NULL
    ) OR EXISTS(
      -- application-approval path: the user IS the sponsor (sponsors.user_id),
      -- and that sponsor is attached to at least one event via event_sponsors
      SELECT 1 FROM sponsors s
      JOIN event_sponsors es ON es.sponsor_id = s.id
      WHERE s.user_id = auth.uid()
    )
  );
$$;


ALTER FUNCTION "public"."user_role_assignments"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."utm_link_has_data"("_link_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  l public.utm_links;
BEGIN
  SELECT * INTO l FROM public.utm_links WHERE id = _link_id;
  IF l.id IS NULL THEN
    RETURN false;
  END IF;

  RETURN EXISTS(
    SELECT 1 FROM public.utm_clicks c
    WHERE c.event_id = l.event_id
      AND coalesce(c.utm_source,   '') = coalesce(l.utm_source,   '')
      AND coalesce(c.utm_medium,   '') = coalesce(l.utm_medium,   '')
      AND coalesce(c.utm_campaign, '') = coalesce(l.utm_campaign, '')
      AND NULLIF(btrim(c.utm_content), '') IS NOT DISTINCT FROM l.utm_content
      AND NULLIF(btrim(c.utm_term), '')    IS NOT DISTINCT FROM l.utm_term
  ) OR EXISTS(
    SELECT 1 FROM public.registrations r
    WHERE r.event_id = l.event_id
      AND coalesce(r.utm_source,   '') = coalesce(l.utm_source,   '')
      AND coalesce(r.utm_medium,   '') = coalesce(l.utm_medium,   '')
      AND coalesce(r.utm_campaign, '') = coalesce(l.utm_campaign, '')
      AND NULLIF(btrim(r.utm_content), '') IS NOT DISTINCT FROM l.utm_content
      AND NULLIF(btrim(r.utm_term), '')    IS NOT DISTINCT FROM l.utm_term
      AND r.status <> 'cancelled'
  );
END $$;


ALTER FUNCTION "public"."utm_link_has_data"("_link_id" "uuid") OWNER TO "postgres";


