CREATE OR REPLACE FUNCTION "public"."vendor_venue_requests"() RETURNS TABLE("selection_id" "uuid", "vendor_id" "uuid", "status" "text", "notes" "text", "created_at" timestamp with time zone, "responded_at" timestamp with time zone, "selected_service_ids" "uuid"[], "event_type" "text", "event_duration_hours" numeric, "expected_attendees" integer, "seating_capacity" integer, "seating_arrangement" "text", "needs_pre_function_area" boolean, "needs_vip_area" boolean, "needs_additional_rooms" boolean, "venue_link" "text", "event_id" "uuid", "event_title" "text", "event_description" "text", "event_date" timestamp with time zone, "event_end_date" timestamp with time zone, "event_timezone" "text", "event_location" "text", "event_venue" "text", "event_capacity" integer, "event_format" "text", "event_status" "text", "event_banner_url" "text", "venue_id" "uuid", "venue_name" "text", "org_name" "text", "organizer_name" "text", "organizer_email" "text", "organizer_phone" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  select
    s.id,
    s.vendor_id,
    s.status,
    s.notes,
    s.created_at,
    s.responded_at,
    coalesce(s.selected_service_ids, array[]::uuid[]),

    s.event_type,
    s.event_duration_hours::numeric,
    s.expected_attendees,
    s.seating_capacity,
    s.seating_arrangement,
    coalesce(s.needs_pre_function_area, false),
    coalesce(s.needs_vip_area, false),
    coalesce(s.needs_additional_rooms, false),
    s.venue_link,

    e.id,
    e.title,
    e.description,
    e.date,
    e.end_date,
    e.timezone,
    e.location,
    e.venue,
    e.capacity,
    e.event_format,
    e.status,
    coalesce(e.banner_landscape_url, e.banner_portrait_url, e.image_url),

    v.id,
    v.name,

    o.name,
    coalesce(
      nullif(trim(p.display_name), ''),
      nullif(trim(concat_ws(' ', p.first_name, p.last_name)), ''),
      u.raw_user_meta_data ->> 'display_name',
      split_part(u.email::text, '@', 1)
    ),
    u.email::text,
    nullif(concat_ws(' ', p.mobile_country_code, p.mobile_number), '')
  from public.event_venue_selections s
  join public.events e        on e.id = s.event_id
  left join public.venues v   on v.id = s.venue_id
  left join public.organizations o on o.id = e.org_id
  left join auth.users u      on u.id = e.user_id
  left join public.profiles p on p.user_id = e.user_id
  where exists (
    select 1 from public.vendor_members m
     where m.vendor_id = s.vendor_id
       and m.user_id = auth.uid()
  )
  order by s.created_at desc;
$$;


ALTER FUNCTION "public"."vendor_venue_requests"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."vendor_venue_requests"() IS 'Venue requests for every vendor the caller belongs to, with full event + organizer details. SECURITY DEFINER because events RLS hides draft events from non-owners.';



