    CONSTRAINT "events_attendance_target_pct_check" CHECK ((("attendance_target_pct" IS NULL) OR (("attendance_target_pct" >= 0) AND ("attendance_target_pct" <= 100)))),
    CONSTRAINT "events_event_format_check" CHECK (("event_format" = ANY (ARRAY['physical'::"text", 'virtual'::"text", 'hybrid'::"text"]))),
    CONSTRAINT "events_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'published'::"text", 'cancelled'::"text", 'completed'::"text"]))),
    CONSTRAINT "events_video_provider_check" CHECK ((("video_provider" IS NULL) OR ("video_provider" = ANY (ARRAY['livekit'::"text", 'agora'::"text"]))))
);


