CREATE OR REPLACE VIEW "public"."community_calendar" WITH ("security_invoker"='true') AS
 WITH "base" AS (
         SELECT "c"."id" AS "community_id",
            ("e"."id")::"text" AS "item_id",
            'event'::"text" AS "kind",
            "e"."title",
            "e"."date" AS "starts_at",
            COALESCE("e"."end_date", "e"."date") AS "ends_at",
            "e"."location",
            "e"."slug" AS "event_slug",
            NULL::"text" AS "session_id"
           FROM ("public"."communities" "c"
             LEFT JOIN "public"."events" "e" ON ((("c"."event_id" = "e"."id") OR (("c"."kind" = 'parent'::"public"."community_kind") AND ("e"."org_id" IS NOT NULL) AND ("e"."org_id" = "c"."org_id")))))
          WHERE ("e"."id" IS NOT NULL)
        UNION ALL
         SELECT "c"."id" AS "community_id",
            ("s"."id")::"text" AS "item_id",
            'session'::"text" AS "kind",
            "s"."title",
            "s"."start_time" AS "starts_at",
            "s"."end_time" AS "ends_at",
            "s"."location",
            "e"."slug" AS "event_slug",
            ("s"."id")::"text" AS "session_id"
           FROM (("public"."communities" "c"
             JOIN "public"."events" "e" ON (("e"."id" = "c"."event_id")))
             JOIN "public"."sessions" "s" ON (("s"."event_id" = "e"."id")))
        )
 SELECT "community_id",
    "item_id",
    "kind",
    "title",
    "starts_at",
    "ends_at",
    "location",
    "event_slug",
    "session_id"
   FROM "base";


ALTER VIEW "public"."community_calendar" OWNER TO "postgres";


