CREATE OR REPLACE VIEW "public"."community_leaderboard" WITH ("security_invoker"='true') AS
 SELECT "cm"."community_id",
    "cm"."user_id",
    COALESCE("p"."posts", (0)::bigint) AS "posts",
    COALESCE("co"."comments", (0)::bigint) AS "comments",
    COALESCE("r"."resources", (0)::bigint) AS "resources",
    (((COALESCE("p"."posts", (0)::bigint) * 5) + (COALESCE("co"."comments", (0)::bigint) * 2)) + (COALESCE("r"."resources", (0)::bigint) * 20)) AS "points"
   FROM ((("public"."community_members" "cm"
     LEFT JOIN ( SELECT "community_posts"."community_id",
            "community_posts"."author_id" AS "user_id",
            "count"(*) AS "posts"
           FROM "public"."community_posts"
          WHERE (NOT "community_posts"."hidden")
          GROUP BY "community_posts"."community_id", "community_posts"."author_id") "p" ON ((("p"."community_id" = "cm"."community_id") AND ("p"."user_id" = "cm"."user_id"))))
     LEFT JOIN ( SELECT "cp"."community_id",
            "c"."author_id" AS "user_id",
            "count"(*) AS "comments"
           FROM ("public"."community_comments" "c"
             JOIN "public"."community_posts" "cp" ON (("cp"."id" = "c"."post_id")))
          WHERE (NOT "c"."hidden")
          GROUP BY "cp"."community_id", "c"."author_id") "co" ON ((("co"."community_id" = "cm"."community_id") AND ("co"."user_id" = "cm"."user_id"))))
     LEFT JOIN ( SELECT "community_resources"."community_id",
            "community_resources"."uploaded_by" AS "user_id",
            "count"(*) AS "resources"
           FROM "public"."community_resources"
          GROUP BY "community_resources"."community_id", "community_resources"."uploaded_by") "r" ON ((("r"."community_id" = "cm"."community_id") AND ("r"."user_id" = "cm"."user_id"))))
  WHERE ("cm"."status" = 'active'::"text");


ALTER VIEW "public"."community_leaderboard" OWNER TO "postgres";


