    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "selected_service_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[] NOT NULL,
    "event_type" "text",
    "event_duration_hours" numeric(6,2),
    "expected_attendees" integer,
    "seating_capacity" integer,
    "seating_arrangement" "text",
    "needs_pre_function_area" boolean DEFAULT false NOT NULL,
    "needs_vip_area" boolean DEFAULT false NOT NULL,
    "needs_additional_rooms" boolean DEFAULT false NOT NULL,
    "venue_link" "text",
    "venue_id" "uuid",
    "response_notified_status" "text",
    CONSTRAINT "event_venue_selections_event_type_length" CHECK ((("event_type" IS NULL) OR ("length"("event_type") <= 60))),
    CONSTRAINT "event_venue_selections_seating_arrangement_length" CHECK ((("seating_arrangement" IS NULL) OR ("length"("seating_arrangement") <= 60))),
    CONSTRAINT "event_venue_selections_status_check" CHECK (("status" = ANY (ARRAY['contacted'::"text", 'accepted'::"text", 'declined'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "event_venue_selections_venue_link_length" CHECK ((("venue_link" IS NULL) OR ("length"("venue_link") <= 500)))
);


ALTER TABLE "public"."event_venue_selections" OWNER TO "postgres";


COMMENT ON COLUMN "public"."event_venue_selections"."selected_service_ids" IS 'Optional array of vendor_services.id values the organizer picked when contacting this vendor. Empty array = "no specific services chosen, please quote the venue itself". The vendor UI resolves these to service titles at read time.';



COMMENT ON COLUMN "public"."event_venue_selections"."event_type" IS 'Business type of the event (e.g. Wedding, Corporate offsite, Product launch). Free text, capped at 60 chars.';



COMMENT ON COLUMN "public"."event_venue_selections"."event_duration_hours" IS 'Planned event duration in hours. Numeric so half-days like 4.5 or overnight retreats can be modelled.';



COMMENT ON COLUMN "public"."event_venue_selections"."expected_attendees" IS 'Organizer''s attendee estimate — informs staffing / catering / capacity.';



COMMENT ON COLUMN "public"."event_venue_selections"."seating_capacity" IS 'Seat count the organizer needs the venue to comfortably support.';



COMMENT ON COLUMN "public"."event_venue_selections"."seating_arrangement" IS 'Layout preference (Theater, Classroom, Banquet, U-shape, Boardroom, Cocktail, Custom text). Free text, capped at 60 chars.';



COMMENT ON COLUMN "public"."event_venue_selections"."needs_pre_function_area" IS 'Organizer wants a lobby / reception / registration space.';



COMMENT ON COLUMN "public"."event_venue_selections"."needs_vip_area" IS 'Organizer wants a segregated VIP / green-room area.';



COMMENT ON COLUMN "public"."event_venue_selections"."needs_additional_rooms" IS 'Organizer wants breakout / secondary rooms beyond the main space.';



COMMENT ON COLUMN "public"."event_venue_selections"."venue_link" IS 'Reference URL — a preferred layout, a mood board, or an existing venue''s site the organizer wants to match.';



COMMENT ON COLUMN "public"."event_venue_selections"."venue_id" IS 'The specific venue (from public.venues) the organizer selected. Nullable — rows created before migration 036 have no venue_id and represent a vendor-level request. New rows should always populate this.';



COMMENT ON COLUMN "public"."event_venue_selections"."response_notified_status" IS 'Status (accepted / declined) the organizer was last emailed about. Set by notify-organizer-venue-response before sending so the trigger and the venue portal can both call it without a duplicate email.';



