CREATE OR REPLACE VIEW "public"."speakers_public" AS
 SELECT "id",
    "name",
    "first_name",
    "last_name",
    "title",
    "designation",
    "company",
    "bio",
    "photo_url",
    "linkedin_url",
    "company_website",
    "industry",
    "created_at",
    "updated_at"
   FROM "public"."speakers" "s"
  WHERE (EXISTS ( SELECT 1
           FROM ("public"."event_speakers" "es"
             JOIN "public"."events" "e" ON (("e"."id" = "es"."event_id")))
          WHERE (("es"."speaker_id" = "s"."id") AND ("e"."status" = 'published'::"text"))));


