CREATE TABLE IF NOT EXISTS "public"."sponsor_meeting_interests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "event_id" "uuid" NOT NULL,
    "sponsor_id" "uuid" NOT NULL,
    "registration_id" "uuid",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "speaker_id" "uuid",
    "status" "text" DEFAULT 'interested'::"text" NOT NULL,
    "scheduled_at" timestamp with time zone,
    "location" "text",
    "met_at" timestamp with time zone,
    "status_reason" "text",
    "note" "text",
    "status_by" "uuid",
    "status_by_side" "text",
    "status_changed_at" timestamp with time zone,
    "status_cause" "text",
    "ever_progressed" boolean DEFAULT false NOT NULL,
    "outcome_at" timestamp with time zone,
    "dispute_status" "text",
    "dispute_reason" "text",
    "dispute_requested_status" "text",
    "disputed_at" timestamp with time zone,
    "dispute_resolution" "text",
    "dispute_note" "text",
    "resolved_at" timestamp with time zone,
    CONSTRAINT "sponsor_meeting_interests_cause_check" CHECK ((("status_cause" IS NULL) OR ("status_cause" = ANY (ARRAY['attendee_no_show'::"text", 'sponsor_unavailable'::"text", 'rescheduled'::"text", 'other'::"text"])))),
    CONSTRAINT "sponsor_meeting_interests_dispute_check" CHECK (((("dispute_status" IS NULL) OR ("dispute_status" = ANY (ARRAY['open'::"text", 'resolved'::"text"]))) AND (("dispute_resolution" IS NULL) OR ("dispute_resolution" = ANY (ARRAY['kept'::"text", 'changed'::"text"]))) AND (("dispute_requested_status" IS NULL) OR ("dispute_requested_status" = ANY (ARRAY['interested'::"text", 'arranged'::"text", 'met'::"text", 'not_met'::"text", 'cancelled'::"text"]))) AND (COALESCE("length"("dispute_reason"), 0) <= 1000) AND (COALESCE("length"("dispute_note"), 0) <= 1000))),
    CONSTRAINT "sponsor_meeting_interests_lengths" CHECK (((COALESCE("length"("location"), 0) <= 200) AND (COALESCE("length"("status_reason"), 0) <= 500) AND (COALESCE("length"("note"), 0) <= 2000))),
    CONSTRAINT "sponsor_meeting_interests_one_person" CHECK (("num_nonnulls"("registration_id", "speaker_id") = 1)),
    CONSTRAINT "sponsor_meeting_interests_side_check" CHECK ((("status_by_side" IS NULL) OR ("status_by_side" = ANY (ARRAY['sponsor'::"text", 'organiser'::"text"])))),
    CONSTRAINT "sponsor_meeting_interests_status_check" CHECK (("status" = ANY (ARRAY['interested'::"text", 'arranged'::"text", 'met'::"text", 'not_met'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."sponsor_meeting_interests" OWNER TO "postgres";


COMMENT ON TABLE "public"."sponsor_meeting_interests" IS 'Meeting Interest: sponsor S would like to meet a person at event E — an attendee (registration_id) or a speaker (speaker_id), exactly one. One row per (event, sponsor, person). Written only through sponsor_set_meeting_interest.';



