CREATE TABLE IF NOT EXISTS "public"."venues" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "vendor_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "space_type" "text",
    "description" "text",
    "is_active" boolean DEFAULT true NOT NULL,
    "area_sqft" integer,
    "length_ft" numeric(6,1),
    "width_ft" numeric(6,1),
    "ceiling_height_ft" numeric(4,1),
    "capacity_floating" integer,
    "capacity_theater" integer,
    "capacity_banquet" integer,
    "capacity_ushape" integer,
    "capacity_classroom" integer,
    "climate_control" "text",
    "has_stage" boolean DEFAULT false NOT NULL,
    "stage_dimensions" "text",
    "green_rooms_count" integer,
    "has_projector" boolean DEFAULT false NOT NULL,
    "has_screen" boolean DEFAULT false NOT NULL,
    "has_sound_system" boolean DEFAULT false NOT NULL,
    "has_microphones" boolean DEFAULT false NOT NULL,
    "has_power_backup" boolean DEFAULT false NOT NULL,
    "has_wifi" boolean DEFAULT false NOT NULL,
    "catering_policy" "text",
    "decor_policy" "text",
    "alcohol_policy" "text",
    "music_curfew_time" time without time zone,
    "noise_restrictions" "text",
    "parking_car_capacity" integer,
    "parking_two_wheeler_capacity" integer,
    "has_valet" boolean DEFAULT false NOT NULL,
    "wheelchair_accessible" boolean DEFAULT false NOT NULL,
    "has_elevator" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "address_line" "text",
    "city" "text",
    "state" "text",
    "pincode" "text",
    "map_url" "text",
    CONSTRAINT "venues_alcohol_policy_check" CHECK ((("alcohol_policy" IS NULL) OR ("alcohol_policy" = ANY (ARRAY['in_house_only'::"text", 'outside_with_license'::"text", 'prohibited'::"text", 'both'::"text"])))),
    CONSTRAINT "venues_catering_policy_check" CHECK ((("catering_policy" IS NULL) OR ("catering_policy" = ANY (ARRAY['in_house_only'::"text", 'outside_permitted'::"text", 'both'::"text"])))),
    CONSTRAINT "venues_climate_control_check" CHECK ((("climate_control" IS NULL) OR ("climate_control" = ANY (ARRAY['central_ac'::"text", 'split_ac'::"text", 'non_ac'::"text"])))),
    CONSTRAINT "venues_decor_policy_check" CHECK ((("decor_policy" IS NULL) OR ("decor_policy" = ANY (ARRAY['empanelled_only'::"text", 'client_choice'::"text", 'both'::"text"])))),
    CONSTRAINT "venues_location_lengths" CHECK (((("address_line" IS NULL) OR ("length"("address_line") <= 300)) AND (("city" IS NULL) OR ("length"("city") <= 80)) AND (("state" IS NULL) OR ("length"("state") <= 80)) AND (("pincode" IS NULL) OR ("length"("pincode") <= 12)) AND (("map_url" IS NULL) OR ("length"("map_url") <= 500)))),
    CONSTRAINT "venues_name_length" CHECK ((("length"("name") >= 1) AND ("length"("name") <= 120))),
    CONSTRAINT "venues_space_type_length" CHECK ((("space_type" IS NULL) OR ("length"("space_type") <= 60)))
);


ALTER TABLE "public"."venues" OWNER TO "postgres";


COMMENT ON TABLE "public"."venues" IS 'Physical spaces a vendor rents out. A single vendor may own many venues (e.g. a hotel with ballroom + terrace + conference room). Distinct from `vendors` which is the business identity.';



