CREATE POLICY "Owner delete regs" ON "public"."registrations" FOR DELETE TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM (("public"."events" "e"
     LEFT JOIN "public"."organizations" "o" ON (("o"."id" = "e"."org_id")))
     LEFT JOIN "public"."org_members" "m" ON ((("m"."org_id" = "e"."org_id") AND ("m"."user_id" = "auth"."uid"()))))
  WHERE (("e"."id" = "registrations"."event_id") AND (("e"."user_id" = "auth"."uid"()) OR ("o"."owner_id" = "auth"."uid"()) OR (("m"."user_id" IS NOT NULL) AND (COALESCE("m"."role", 'member'::"text") = ANY (ARRAY['admin'::"text", 'member'::"text"]))) OR "public"."has_role"("auth"."uid"(), 'admin'::"public"."app_role"))))));



COMMENT ON POLICY "Owner delete regs" ON "public"."registrations" IS 'DELETE registrations: event creator, org owner, org_members with role admin/member (NOT viewer), or platform admin.';



