CREATE POLICY "Reviewers see unban requests" ON "public"."unban_requests" FOR SELECT TO "authenticated" USING (("public"."has_role"("auth"."uid"(), 'admin'::"public"."app_role") OR (("scope" = 'community'::"text") AND "public"."can_moderate_community"("auth"."uid"(), "community_id"))));



CREATE POLICY "Speaker read ws" ON "public"."webinar_sessions" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM ("public"."event_speakers" "es"
     JOIN "public"."speakers" "s" ON (("s"."id" = "es"."speaker_id")))
  WHERE (("es"."event_id" = "webinar_sessions"."event_id") AND (("s"."user_id" = "auth"."uid"()) OR ("lower"("s"."email") = "lower"(COALESCE(("auth"."jwt"() ->> 'email'::"text"), ''::"text"))))))));



CREATE POLICY "Speakers view their own record" ON "public"."speakers" FOR SELECT TO "authenticated" USING ((("email" IS NOT NULL) AND ("lower"("email") = "public"."_auth_user_email"())));



CREATE POLICY "Sponsor owner manage" ON "public"."sponsor_members" TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."sponsors" "s"
  WHERE (("s"."id" = "sponsor_members"."sponsor_id") AND (("s"."user_id" = "auth"."uid"()) OR "public"."has_role"("auth"."uid"(), 'admin'::"public"."app_role")))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM "public"."sponsors" "s"
  WHERE (("s"."id" = "sponsor_members"."sponsor_id") AND (("s"."user_id" = "auth"."uid"()) OR "public"."has_role"("auth"."uid"(), 'admin'::"public"."app_role"))))));



CREATE POLICY "Sponsor team views its sponsor" ON "public"."sponsors" FOR SELECT TO "authenticated" USING ("public"."is_sponsor_member"("auth"."uid"(), "id"));



CREATE POLICY "Sponsors view their meeting interests" ON "public"."sponsor_meeting_interests" FOR SELECT TO "authenticated" USING (("sponsor_id" IN ( SELECT "ms"."sponsor_id"
   FROM "public"."_my_event_sponsors"("sponsor_meeting_interests"."event_id") "ms"("sponsor_id"))));



