CREATE POLICY "Super admins insert messages" ON "public"."support_ticket_messages" FOR INSERT TO "authenticated" WITH CHECK ("public"."has_role"("auth"."uid"(), 'admin'::"public"."app_role"));



CREATE POLICY "Super admins read all messages" ON "public"."support_ticket_messages" FOR SELECT USING ("public"."has_role"("auth"."uid"(), 'admin'::"public"."app_role"));



CREATE POLICY "Super admins read all tickets" ON "public"."support_tickets" FOR SELECT USING ("public"."has_role"("auth"."uid"(), 'admin'::"public"."app_role"));



CREATE POLICY "Super admins update all tickets" ON "public"."support_tickets" FOR UPDATE USING ("public"."has_role"("auth"."uid"(), 'admin'::"public"."app_role")) WITH CHECK ("public"."has_role"("auth"."uid"(), 'admin'::"public"."app_role"));



CREATE POLICY "Update events" ON "public"."events" FOR UPDATE TO "authenticated" USING ((("auth"."uid"() = "user_id") OR "public"."has_role"("auth"."uid"(), 'admin'::"public"."app_role") OR (("org_id" IS NOT NULL) AND ("public"."is_org_owner"("auth"."uid"(), "org_id") OR ("public"."org_member_role"("auth"."uid"(), "org_id") <> 'viewer'::"text"))))) WITH CHECK ((("auth"."uid"() = "user_id") OR "public"."has_role"("auth"."uid"(), 'admin'::"public"."app_role") OR (("org_id" IS NOT NULL) AND ("public"."is_org_owner"("auth"."uid"(), "org_id") OR ("public"."org_member_role"("auth"."uid"(), "org_id") <> 'viewer'::"text")))));



COMMENT ON POLICY "Update events" ON "public"."events" IS 'UPDATE events: creator, platform admin, org owner, or any non-viewer org_member. Uses SECURITY DEFINER helpers so the check never reads organizations (whose policy reads events) and cannot recurse.';



